bool ok(string &S, int x0, int x1) {
  int N=SZ(S);
  VI x(N,-1);
  x[0]=x0,x[1]=x1;

  auto nex=[&](int ani, int sign, int left)->int {
    if(ani==sign) return left^1;
    else return left;
  };

  FOR(i,1,N-1) {
    int l=x[i-1];
    int ani=x[i],sign=S[i]=='o';
    x[i+1]=nex(ani,sign,l);
  }
  int y=nex(x[N-1],S[N-1]=='o',x[N-2]);

  string ani="SW";
  T=string(N,'?');
  REP(i,N) T[i]=ani[x[i]];

  return x[0]==y;
}
void solve() {
  REP(i,2)REP(j,2) if(ok(S,i,j)) {
    cout<<T<<endl;
    return;
  }
  cout<<-1<<endl;
}

