int getPrevIndex(int now, int mod) {
	return (now + mod - 1) % mod;
}

bool chk(int casenum, int index) {

	int next = getNextIndex(index, N);
	int prev = getPrevIndex(index, N);
	if (s[index] == 'o') {
		if (cases[casenum][index] == 'S' && cases[casenum][next] == cases[casenum][prev]) {
			return true;
