bool chk(int n, string s, vector<bool> &ans){
  rep(i, n){
    bool m = (s.at(i) == 'o');
    int bi = (i-1+n) % n;
    int ni = (i+1+n) % n;
    if(ans.at(i) == false) m ^= 1;
    if(i == 0 && m == false){
      break;
    }
    if(m == true){
      if(i != 0 && ans.at(bi) != ans.at(i)){
        return false;
      }
      if(i == n-1){
        if(ans.at(ni) != ans.at(i)){
          return false;
        }
      }
      ans.at(ni) = ans.at(i);
    }else{
      if(i != n-1){
      if(ans.at(bi) == ans.at(i)){
        ans.at(ni) = !ans.at(i);
      }else{
        ans.at(ni) = ans.at(i);
      }
      }else{
        bool f = (ans.at(i) == ans.at(bi));
        bool r = (ans.at(i) == ans.at(ni));
        if((f ^ r) == true){
          return true;
        }else{
          return false;
        }
      }
    }
  }

  ans.at(n-1) = ans.at(0);
  rep(i, n){
    bool m = (s.at(i) == 'o');
    int bi = (i-1+n) % n;
    int ni = (i+1+n) % n;
