    cin >> n;
    cin >> s;
    for(first = 0 ; first < 2 ; first++){
    	for(last = 0 ; last < 2 ; last++){
    		memset(dp,-1,sizeof dp);
    		if(calc(0,last,first)){
    			build(0,last,first);
    			cout << ans << endl;
    			return 0;
    		}
    	}
    }
    puts("-1");
    return 0;
}

