int n;
string s;

string solve(string start){
    string res = start;
    REP1(i, n-1){
        if(s[i] == 'o'){
            if(res[i] == 'S') res += (res[i-1] == 'S' ? 'S' : 'W');
            if(res[i] == 'W') res += (res[i-1] == 'S' ? 'W' : 'S');
        }else{
            if(res[i] == 'W') res += (res[i-1] == 'S' ? 'S' : 'W');
            if(res[i] == 'S') res += (res[i-1] == 'S' ? 'W' : 'S');
        }
    }

    bool check = true;
    REP1(i, n-1){
        if(res[i] == 'S'){
            if(s[i] == 'o') check &= res[i-1] == res[i+1];
            if(s[i] == 'x') check &= res[i-1] != res[i+1];
        }else{
            if(s[i] == 'o') check &= res[i-1] != res[i+1];
            if(s[i] == 'x') check &= res[i-1] == res[i+1];
        }
    }

    if(res[0] == 'S'){
        if(s[0] == 'o') check &= res[n-1] == res[1];
        if(s[0] == 'x') check &= res[n-1] != res[1];
    }else{
        if(s[0] == 'o') check &= res[n-1] != res[1];
        if(s[0] == 'x') check &= res[n-1] == res[1];
    }

    if(res[n-1] == 'S'){
        if(s[n-1] == 'o') check &= res[n-2] == res[0];
        if(s[n-1] == 'x') check &= res[n-2] != res[0];
    }else{
        if(s[n-1] == 'o') check &= res[n-2] != res[0];
        if(s[n-1] == 'x') check &= res[n-2] == res[0];
    }

    if(check) return res;
    return "";
}

