bool check(string t)
{
	char c = t[0]; t.push_back(c);

	if (t[0] == 'S')
	{
		if (s[0] == 'o' && t[n - 1] != t[1]) return false;
		if (s[0] == 'x' && t[n - 1] == t[1]) return false;
	}
	if (t[0] == 'W')
	{
		if (s[0] == 'o' && t[n - 1] == t[1]) return false;
		if (s[0] == 'x' && t[n - 1] != t[1]) return false;
	}
	FOR(i, 1, t.size() - 1)
	{
		if (t[i] == '.') return false;
		if (t[i] == 'S')
		{
			if (s[i] == 'o' && t[i - 1] != t[i + 1]) return false;
			if (s[i] == 'x' && t[i - 1] == t[i + 1]) return false;
		}
		if (t[i] == 'W')
		{
			if (s[i] == 'o' && t[i - 1] == t[i + 1]) return false;
			if (s[i] == 'x' && t[i - 1] != t[i + 1]) return false;
		}
	} 
	return true;
}

