        if(str[cnt % n] == 'o' && array[cnt % n] == 0 || str[cnt % n] == 'x' && array[cnt % n] == 1){
            array[(cnt + 1) % n] = array[(cnt - 1 + n) % n];
            //cout << cnt << " " <<  << "\n";
        }
        else if(str[cnt % n] == 'o' && array[cnt % n] == 1 || array[cnt % n] == 0 && str[cnt % n] == 'x'){
            array[(cnt + 1) % n] = 1 - array[(cnt - 1 + n) % n];
            //cout << cnt << " " <<  << "\n";
        }
        ++cnt;
    }
    for(int i = 0;i < n;i++){
        if(str[i] == 'o'){
            if(array[i] == 0 && array[(i - 1 + n) % n] != array[(i + 1) % n]){
                cout << "-1";
