            }
            if(array[i] == 1 && array[(i - 1 + n) % n] == array[(i + 1) % n]){
                cout << "-1";
                return 0;
            }
        }
        if(str[i] == 'x'){
            if(array[i] == 0 && array[(i - 1 + n) % n] == array[(i + 1) % n]){
                cout << "-1";
                return 0;
            }
