            }
            if (i < n - 1) ans += cur ? 'W' : 'S';
        }
        bool flag;
        if ((s[0] == 'o') ^ cur) flag = prev == b;
        else flag = prev != b;
        return flag && cur == a;
    };
    for (int i = 0; i < 2; i++) {
        for (int j = 0; j < 2; j++) {
            if (func(i, j)) {
