bool claim[100001]; // true : 両隣同じ

bool kind[100001]; // true : 羊
				   // false : 狼

bool next_animal(bool before, bool animal, bool say) {
	if (animal) {
		if (say) return before;
		else return !before;
	}
	else {
		if (say) return !before;
		else return before;
	}
}

