void loop(bool List[100010], long long N, string s) {
  REP(i, N) {
    int in1 = i - 1 < 0 ? N - 1 : i - 1;
    int in2 = i + 1 == N ? 0 : i + 1;

    if (s[i] == 'o') {
      List[in2] = List[i] ? List[in1] : List[in1] ^ true;
    } else {
      List[in2] = List[i] ? List[in1] ^ true : List[in1];
    }
  }
}

void solve(long long N, string s) {
  bool List[100010] = {};

  List[0] = false;
  List[N - 1] = false;
  loop(List, N, s);
  if (List[0] == false && List[N - 1] == false) {
    REP(i, N) { cout << (List[i] ? "S" : "W"); }
    cout << endl;
    return;
  }

  List[0] = false;
  List[N - 1] = true;
  loop(List, N, s);
  if (List[0] == false && List[N - 1] == true) {
    REP(i, N) { cout << (List[i] ? "S" : "W"); }
    cout << endl;
    return;
  }

  List[0] = true;
  List[N - 1] = false;
  loop(List, N, s);
  if (List[0] == true && List[N - 1] == false) {
    REP(i, N) { cout << (List[i] ? "S" : "W"); }
    cout << endl;
    return;
  }

  List[0] = true;
  List[N - 1] = true;
  loop(List, N, s);
  if (List[0] == true && List[N - 1] == true) {
    REP(i, N) { cout << (List[i] ? "S" : "W"); }
    cout << endl;
    return;
  }

  cout << "-1" << endl;
}

int main() {
