bool fichk(vector<bool> &f, string s){
  if(s.at(0) == 'o'){
    return f.at(1) == f.back();
  }else{
    return f.at(1) != f.back();
  }
}

bool fc(vector<bool> &f, string s){
  int n = s.size();
  rep2(i, 1, n){
    bool c = (s.at(i) == 'x');
    if((f.at(i) ^ c) == true){
      f.at(i+1) = f.at(i-1);
    }else{
      f.at(i+1) = !f.at(i-1);
    }
  }
  if(f.at(0) == f.at(n) && fichk(f, s)) return true;
  return false;
}

void ap(vector<bool> &f){
  rep(i, f.size()-1){
    char o;
    if(f.at(i) == true) o = 'S';
    else o = 'W';
    cout << o;
  }
  cout << endl;
}

