void construct()
{
	for(int i = 1; i <= N - 2; i++)
	{
		if(arr[i] == 0)	// sheep
		{
			if(S[i] == 'o')	arr[i + 1] = arr[i - 1];
			else			arr[i + 1] = !arr[i - 1];
		}
		else
		{
			if(S[i] == 'o')	arr[i + 1] = !arr[i - 1];
			else			arr[i + 1] = arr[i - 1];
		}
	}
}

bool satisfied()
{
	for(int i = 0; i < N; i++)
	{
		int next = (i + 1) % N;
		int prev = ((i - 1) + N) % N;

		if(arr[i] == 0)
		{
			if(S[i] == 'o')
			{
				if(arr[next] != arr[prev])	return 0;
			}
			else
			{
				if(arr[next] == arr[prev])	return 0;
			}
		}
		else
		{
			if(S[i] == 'o')
			{
				if(arr[next] == arr[prev])	return 0;
			}
			else
			{
				if(arr[next] != arr[prev])	return 0;
			}
		}
	}
	return 1;
}

