    if((ch == 'S' && s[0] == 'o') || (ch == 'W' && s[0] == 'x')) {
        if(str[1] == str[n - 1]) return true;
        return false;
    } else {
        if(str[1] != str[n - 1]) return true;
        return false;
    }
}

