const char SW[] = "SW";

char same( const char c )
{
	const bool w = c == 'W';
	return SW[w];
}

char differ( const char c )
{
	const bool w = c == 'W';
	return SW[ 1 - w ];
}


string solve( const int N, const string &S, const int s )
{
	string res( N + 2, '.' );
	REP( i, 2 )
	{
		res[i] = SW[ !!( s & ( i + 1 ) ) ];
	}

	REP( i, 1, N + 1 )
	{
		if ( res[i] == 'S' )
		{
			res[ i + 1 ] = ( S[ i % N ] == 'o' ? same : differ )( res[ i - 1 ] );
		}
		else
		{
			res[ i + 1 ] = ( S[ i % N ] == 'o' ? differ : same )( res[ i - 1 ] );
		}
	}

	if ( res[0] != res[N] || res[1] != res[ N + 1 ] )
	{
		return "";
	}

	res.resize( N );
	return res;
}

