    for( int i = 0 ; i <= size ; ++ i ) // note that 0 <= i <= size
      {

	for( int j = 0 ; j <= i ; ++ j )
	  {

	    if( j == 0 or j == i )
	      {
		val[i][j] = 1LL;
	      }
