using namespace std;

typedef long long ll;

constexpr ll BLANK = -1;
ll N;
string s;

vector<ll> recur(ll l, ll r, vector<ll> ans) {
    ll lans;
    if ((s[l + 1] == 'o' && ans[l + 1] == 1) || (s[l + 1] == 'x' && ans[l + 1] == 0)) {
        lans = ans[(l + 2) % N];
    } else {
        lans = (ans[(l + 2) % N] + 1) % 2;
    }

    ll rans;
    if ((s[r - 1] == 'o' && ans[r - 1] == 1) || (s[r - 1] == 'x' && ans[r - 1] == 0)) {
        rans = ans[(r - 2 + N) % N];
    } else {
        rans = (ans[(r - 2 + N) % N] + 1) % 2;
    }

    if (l == r) {
        if (lans == rans) {
            ans[l] = lans;
            return ans;
        }
        return vector<ll>();
    } else if (l + 1 == r) {
        if (lans == ans[r - 1] && rans == ans[l + 1]) {
            return ans;
        }
        return vector<ll>();
    }

    ans[l] = lans;
    ans[r] = rans;
    return recur(l - 1, r + 1, ans);
}

int main(void) {
    cin >> N;
    cin >> s;

    vector<ll> ss1(N, BLANK);
    vector<ll> ss2(N, BLANK);
    vector<ll> sw1(N, BLANK);
    vector<ll> sw2(N, BLANK);
    ss1[0] = 1;
    ss2[0] = 1;
    sw1[0] = 0;
    sw2[0] = 0;

    if (s[0] == 'o') {
        ss1[N - 1] = ss1[1] = 1;
        ss2[N - 1] = ss2[1] = 0;
        sw1[N - 1] = sw2[1] = 1;
        sw1[1] = sw2[N - 1] = 0;
    } else {
        ss1[N - 1] = ss2[1] = 1;
        ss1[1] = ss2[N - 1] = 0;
        sw1[N - 1] = sw1[1] = 1;
        sw2[N - 1] = sw2[1] = 0;
    }

    auto ans_ss1 = recur(N - 2, 2, ss1);
    auto ans_ss2 = recur(N - 2, 2, ss2);
    auto ans_sw1 = recur(N - 2, 2, sw1);
    auto ans_sw2 = recur(N - 2, 2, sw2);

    char animal[2] = {'W', 'S'};

    if (ans_ss1.size() != 0) {
        for (auto a : ans_ss1) {
            cout << animal[a];
        }
        cout << endl;
        return 0;
    }

    if (ans_ss2.size() != 0) {
        for (auto a : ans_ss2) {
            cout << animal[a];
        }
        cout << endl;
        return 0;
    }

    if (ans_sw1.size() != 0) {
        for (auto a : ans_sw1) {
            cout << animal[a];
        }
        cout << endl;
        return 0;
    }

    if (ans_sw2.size() != 0) {
        for (auto a : ans_sw2) {
            cout << animal[a];
        }
        cout << endl;
        return 0;
    }

    cout << -1 << endl;
    return 0;
}

