#define N 300001
using namespace std;
int n;
int A[N],ans[N];

bool check(int i){
  int l = (i+n-1)%n,r = (i+1)%n;
  if(ans[i]==0){
    if(A[i] == 1) return ans[l]==ans[r];
    if(A[i] == 0) return ans[l]!=ans[r];
  }
  if(ans[i]==1){
    if(A[i] == 1) return ans[l]!=ans[r];
    if(A[i] == 0) return ans[l]==ans[r];
  }
}

bool check(){
  for(int i=0;i<n;i++)if(!check(i))return 0;
  return 1;
}

int dfs(int pos,int cnt){
  if(cnt==n)return check();
  if(A[pos]){ //o
    if(ans[pos] == 0 ) ans[pos+1] = ans[pos-1];
    if(ans[pos] == 1 ) ans[pos+1] = !ans[pos-1];
    if(dfs(pos+1,cnt+1))return 1;
  }
  else {     //x
    if(ans[pos] == 0 ) ans[pos+1] = !ans[pos-1];
    if(ans[pos] == 1 ) ans[pos+1] =  ans[pos-1];
    if(dfs(pos+1,cnt+1))return 1;
  }
  return 0;
}

