    cout << itr;
  } END;
}

int main() {
  int n;
  string s;
  cin >> n;
  cin >> s;
  vector<char> applyed(2);
  applyed[0] = 'S';
  applyed[1] = 'W';

  for (int bit = 0; bit < (1 << 2); ++bit) {
    vector<int> thesis(2);
    // 0 -> 羊, 1 -> 狼
    vector<int> now(n+1);
    vector<char> ans(n+1);
    for (int j = 0; j < 2; ++j) {
      thesis[j] = (bit >> j) & 1;
      now[j] = thesis[j];

      ans[j] = applyed[now[j]];
    }

    int last = now.front();
    for (int i = 1; i < n; ++i) {
      if (now[i] == 0) {
        // 羊 phase
        if (s[i] == 'o') {
          now[i+1] = now[i-1];
        } else {
          now[i+1] = (now[i-1] == 0) ? 1 : 0;
        }
      } else {
        // 狼 phase
        if (s[i] == 'o') {
          now[i+1] = (now[i-1] == 0) ? 1 : 0;
        } else {
          now[i+1] = now[i-1];
        }
      }

      ans[i+1] = applyed[now[i+1]];
      if (i == n-1 and now[n] == last) {
        ans.pop_back();
        showes(ans);
        return 0;
      }
    }
  }

  cout << -1 << endl;
}

