bool compare(ll idx, vector<bool> ansT) {
    if (idx == 0) return ansT.back() == ansT[idx + 1];
    else if (idx == ansT.size() - 1) return ansT[idx - 1] == ansT[0];
    else return ansT[idx - 1] == ansT[idx + 1];
}


