string sol(string s, char c){
  int tmp = s.size();
  string t = "";
  for(int i=0; i<s.size(); i++) t += c;

  s = s + s + s;
  t = t + t + t;

  for(int ii=0; ii<tmp; ii++){
    int i = ii + tmp;
    if( s[i] == 'x' && t[i] == 'S' ){
      if( t[i-1] == 'S' ) t[i+1] = 'W';
      else if( t[i-1] == 'W' ) t[i+1] = 'S';

    }else if( s[i] == 'x' && t[i] == 'W' ){
      if( t[i-1] == 'S' ) t[i+1] = 'S';
      else if( t[i-1] == 'W' ) t[i+1] = 'W';

    }else if( s[i] == 'o' && t[i] == 'S' ){
      if( t[i-1] == 'S' ) t[i+1] = 'S';
      else if( t[i-1] == 'W' ) t[i+1] = 'W';

    }else if( s[i] == 'o' && t[i] == 'W' ){
      if( t[i-1] == 'S' ) t[i+1] = 'W';
      else if( t[i-1] == 'W' ) t[i+1] = 'S';

    }
  }
  string p = t.substr(tmp, tmp);
  p = p + p + p;
  for(int ii=0; ii<tmp; ii++){
    int i = ii + tmp;
    if( s[i] == 'x' && p[i] == 'S' ){
      if( p[i-1] == p[i+1] ){
        return "";
      }
    }else if( s[i] == 'x' && p[i] == 'W' ){
      if( p[i-1] != p[i+1] ){
        return "";
      }
    }else if( s[i] == 'o' && p[i] == 'S' ){
      if( p[i-1] != p[i+1] ){
        return "";
      }
    }else if( s[i] == 'o' && p[i] == 'W' ){
      if( p[i-1] == p[i+1] ){
        return "";
      }
    }
  }
  return p;
}

