struct yes_no : numpunct<char> {
  string_type do_truename()  const { return "Yes"; }
  string_type do_falsename() const { return "No"; }
};

char get_next(char prev, char curr, char resp) {
  bool same = (resp == 'o');
  if (curr == 'W') same = !same;
  if (same) return prev;
  return (prev == 'W' ? 'S' : 'W');
}

void make(const string &s, string &res) {
  const int n = s.size();
  for (int i = 1; i < n - 1; ++i) {
    res[i+1] = get_next(res[i-1], res[i], s[i]);
  }
}

void solve(ll N, string s) {
  s += s[0];
  s += s[1];
  string res(N + 2, '.');
  REP(i,2) REP(j,2) {
    res[0] = (i ? 'W' : 'S');
    res[1] = (j ? 'W' : 'S');
    make(s, res);
    if (res[0] == res[N] && res[1] == res[N + 1]) {
      cout << res.substr(0, N) << endl;
      return;
    }
  }
  cout << -1 << endl;
}

