int main(){
  ll N;
  cin >> N;

  string oxs;
  cin >> oxs; cin.ignore();

  vector<string> inits(4);
  inits[0] = "oo"; inits[1] = "ox"; inits[2] = "xo"; inits[3] = "xx";

