int func(string s, int start)
{
	s += s[0];
	int prev = start;
	string ans;
	if (s[0] == 'o') {
		if (start == 0) ans = "SSS";
		else if (start == 1) ans = "SWW";
		else if (start == 2) ans = "WWS";
		else ans = "WSW";
	} else {
		if (start == 0) ans = "SSW";
		else if (start == 1) ans = "WWW";
		else if (start == 2) ans = "WSS";
		else ans = "SWS";
	}

	rep(i, s.length() - 1) {
		if (s[i] == 'o' && s[i + 1] == 'o') {
			ans += GOOD[prev][0];
			prev = good[prev][0];
		} else if (s[i] == 'o' && s[i + 1] == 'x') {
			ans += GOOD[prev][1];
			prev = good[prev][1];
		} else if (s[i] == 'x' && s[i + 1] == 'o') {
			ans += BAD[prev][0];
			prev = bad[prev][0];
		} else {
			ans += BAD[prev][1];
			prev = bad[prev][1];
		}
	}
	if (start == prev) {
		for (int i = 1; i < ans.length() - 2; i++) cout << ans[i];
		cout << endl;
		return 1;
	} else return 0;
}

