bool translate(int n, string s, string in)
{
	ss = in;
	s = s + s[0];
	for(int i=1; i<n+1; i++) {
		if(ss[i] == 'S') {
			if(s[i] == 'o')
				ss = ss + ss[i-1];
			else {
				char ch = 'W' ^ 'S' ^ ss[i-1];
				ss = ss + ch;
			}
		}
		else {
			if(s[i] == 'o') {
				char ch = 'W' ^ 'S' ^ ss[i-1];
				ss = ss + ch;
			}
			else
				ss = ss + ss[i-1];
		}
	}
	string str1 = ss.substr(0, 2);
	string str2 = ss.substr(n, 2);
	if(str1 == str2)
		ss = ss.substr(0, n);
	else
		return false;
	return true;
}

