string solve(int N, const string &S, int a, int b) {
    int M = S.size();
    string res(M, 'A');
    res[0] = itos[a], res[1] = itos[b];
    for(int i = 1; i < M - 1; ++i) {
        res[i + 1] = itos[id[res[i - 1]] ^ dif(res[i], S[i])];
        if(i + 1 >= N && res[i + 1 - N] != res[i + 1]) return "";
    }
    return res.substr(N);
}

