class Union_find{
private:
	vector<int> par;
	vector<int> rank;
	int n;

public:
	Union_find(int a){
		n = a;
		for(int i = 0;i < n;i++){
			par.push_back(i);
			rank.push_back(0);
		}
	}

	int find(int x){
		if(par[x] == x){
			return x;
		}else{
			return par[x] = find(par[x]);
		}
	}

	void unite(int x, int y){
		x = find(x);
		y = find(y);
		if(x == y) return;

		if(rank[x] < rank[y]){
			par[x] = y;
		}else{
			par[y] = x;
			if(rank[x] == rank[y]) rank[x]++;
		}
	}

	bool same(int x, int y){
		return find(x) == find(y);
	}
};

int n;

int solve(string ans, string s){
	REP(i, n){
		if((ans[i] == 'S' && s[i] == 'o') || (ans[i] == 'W' && s[i] == 'x')){
			if(ans[(i-1+n)%n] == '.')
				ans[(i-1+n)%n] = ans[(i+1)%n];
			else
				ans[(i+1)%n] = ans[(i-1+n)%n];
		}else{
			if(ans[(i-1+n)%n] == '.'){
				if(ans[(i+1)%n] == 'W')
					ans[(i-1+n)%n] = 'S';
				else
					ans[(i-1+n)%n] = 'W';
			}else{
				if(ans[(i-1+n)%n] == 'W')
					ans[(i+1)%n] = 'S';
				else
					ans[(i+1)%n] = 'W';
			}
		}
	}
	REP(i, n){
		if((s[i] == 'o' && ans[i] == 'S') || (s[i] == 'x' && ans[i] == 'W')){
			if(ans[(i-1+n)%n] != ans[(i+1)%n])
				return 0;
		}else{
			if(ans[(i-1+n)%n] == ans[(i+1)%n])
				return 0;
		}
	}
	cout << ans << endl;
	return 1;
}

