inline char dif(char sp) {
  if (sp == 'S') {
    return 'W';
  } else {
    return 'S';
  }
}

inline char next(char prevsp, char prevsay, char nowsp, char nowsay) {
  char res;
  if (nowsp == 'S') {
    if (nowsay == 'o') {
      res = prevsp;
    } else {
      res = dif(prevsp);
    }
  } else {
    if (nowsay == 'o') {
      res = dif(prevsp);
    } else {
      res = prevsp;
    }
  }
  return res;
}

string check(char ze, char one, string say) {
  int n = say.length();
  string ani(n + 1, '0');
  ani[0] = ze;
  ani[1] = one;
  for (int i = 2; i <= n; i++) {
    ani[i] = next(ani[i - 2], say[i - 2], ani[i - 1], say[i - 1]);
  }
  return ani;
}
