struct Xorshift {
  uint64_t x = 88172645463325252LL;
  unsigned next_int() {
    x = x ^ (x << 7);
    return x = x ^ (x >> 9);
  }
  unsigned next_int(unsigned mod) {
    x = x ^ (x << 7);
    x = x ^ (x >> 9);
    return x % mod;
  }
  unsigned next_int(unsigned l, unsigned r) {
    x = x ^ (x << 7);
    x = x ^ (x >> 9);
    return x % (r - l + 1) + l;
  }
  double next_double() {
    return double(next_int()) / UINT_MAX;
  }
} rnd;

template<typename T>
void shuffle_vector(vector<T>& v, Xorshift& rnd) {
  int n = v.size();
  for (int i = n - 1; i >= 1; i--) {
    int r = rnd.next_int(i);
    swap(v[i], v[r]);
  }
}



unsigned popcount(unsigned bits) {
  bits = (bits & 0x55555555) + (bits >> 1 & 0x55555555);
  bits = (bits & 0x33333333) + (bits >> 2 & 0x33333333);
  bits = (bits & 0x0f0f0f0f) + (bits >> 4 & 0x0f0f0f0f);
  bits = (bits & 0x00ff00ff) + (bits >> 8 & 0x00ff00ff);
  return (bits & 0x0000ffff) + (bits >> 16 & 0x0000ffff);
}



int main() {
  ios::sync_with_stdio(false);
  cin.tie(0);

  int N;
  string s;
  cin >> N >> s;

  // N-1,0,1 を決める -> 2 ~ N-2 が決まる -> N-2 で矛盾が生じなければ ok

  const int S = 0, W = 1;

  vector<vector<int>> oks({ {S,S,S},{W,S,W},{S,W,W},{W,W,S} });
  vector<vector<int>> ngs({ {S,S,W},{W,S,S},{S,W,S},{W,W,W} });

  for(auto v : (s[0] == 'o' ? oks : ngs)) {
    // a[N-1] = a[0] = a[1] = S
    vector<int> a(N);
    a[N - 1] = v[0]; a[0] = v[1]; a[1] = v[2];
    for (int i = 1; i < N - 2; i++) {
      if (a[i] == S) {
        if (s[i] == 'o') a[i + 1] = a[i - 1];
        else a[i + 1] = 1 - a[i - 1];
      }
      else {
        if (s[i] == 'o') a[i + 1] = 1 - a[i - 1];
        else a[i + 1] = a[i - 1];
      }
    }
    // 矛盾チェック
    bool ok = true;
    for (int i = 0; i < N; i++) {
      int l = (i + N - 1) % N, m = i, r = (i + 1) % N;
      if (s[m] == 'o') {
        if (!(a[m] == S && a[l] == a[r] || a[m] == W && a[l] != a[r])) {
          ok = false;
          break;
        }
      }
      else {
        if (!(a[m] == S && a[l] != a[r] || a[m] == W && a[l] == a[r])) {
          ok = false;
          break;
        }
      }
    }
    if (ok) {
      for (int x : a) cout << (x == S ? 'S' : 'W');
      cout << endl;
      return 0;
    }
  }

  cout << -1 << endl;

  return 0;
}

