using namespace std;

char opposite_animal(char a)
{
	return a == 'S' ? 'W' : 'S';
}

char next_animal(char a0, char a1, char s1)
{
	if (a1 == 'S') {
		if (s1 == 'o') {
			return a0;
		}
		else {
			return opposite_animal(a0);
		}
	}
	else {
		if (s1 == 'o') {
			return opposite_animal(a0);
		}
		else {
			return a0;
		}
	}
}

string solve(int N, const string &s, string t)
{
	for (int i = 1; i + 1 < N; ++i) {
		t += next_animal(t[i - 1], t[i], s[i]);
	}
	if (next_animal(t[N - 2], t[N - 1], s[N - 1]) == t[0]) {
		return t;
	}
	else {
		return "";
	}
}

int main()
{
	int N;
	string s;
	cin >> N >> s;

	string ans;
	for (const auto &t : { "SS", "SW", "WS", "WW" }) {
		ans = solve(N, s, t);
		if (!ans.empty()) {
			break;
		}
	}
	if (ans.empty()) {
		cout << -1 << endl;
	}
	else {
		cout << ans << endl;
	}
}

