char conv(char c){
	return c == 'W' ? 'S' : 'W';
}
char next(char prev, char now){
	if(now == 'S')	return prev;
	else	return conv(prev);
}

string restore(char first,char second){
	string ret = "";
	ret += first;
	ret += second;
	char prev = first;
	char cur = second;
	char tmp;
	for(int i = 1;i<n;i++){
		if(s[i] == 'o')
			tmp=next(prev,cur);
		else
			tmp = conv(next(conv(prev),conv(cur)));
		prev = cur;
		cur = tmp;
		ret += cur;
	}
	return ret;
}

