bool find_cand(char c0, char c1, int N, const char *ans, char *cand)
{
    cand[N] = '\0';

    cand[0] = c0;
    cand[1] = c1;

    for (int i = 0; i < N; i++)
    {
        int curr = i + 2;
        bool same = ans[(curr - 1) % N] == 'o';
        bool honest = cand[(curr - 1) % N] == 'S';
        bool sheep = cand[(curr - 2) % N] == 'S';

        cand[curr % N] = !(honest ^ same) ? sheep ? 'S' : 'W'
                                          : sheep ? 'W' : 'S';
    }

    return cand[0] == c0 && cand[1] == c1;
}

