typedef long long ll;
using namespace std;
typedef pair<int, int> pii;
const int maxn = 1e3 + 10;
 int n;
 vector<bool> res;
bool work(const string &s) {
    for (int i = 1; i < n - 1; i++) {
        if(s[i] == 'o') {
            if(res[i]) {
                res[i + 1] = !res[i - 1];
            } else {
                res[i + 1] = res[i - 1];
            }
        } else {
            if(res[i]) {
                res[i + 1] = res[i - 1];
            } else {
                res[i + 1] = !res[i - 1];
            }
        }
    }
    if(s[n - 1] == 'o') {
        if(res[n - 1]) {
            return res[n - 2] != res[0];
        } else {
            return res[n - 2] == res[0];
        }
    } else {
        if(res[n - 1]) {
            return res[n - 2] == res[0];
        } else {
            return res[n - 2] != res[0];
        }
    }
}
void pr() {
    for (int i = 0; i < n; i++) {
        if(res[i]) cout << 'W';
        else cout << 'S';
    }
    cout << endl;
}
void solve() {
    string s;
    while(cin >> n) {
        cin >> s;
        res.clear();
        res.resize(n);
        res[0] = res[1] = 0;
        bool f = work(s);
        if(f) {
            pr();
            continue;
        }
        res[0] = res[1] = 1;
        f = work(s);
        if(f) {
            pr();
            continue;
        }
        res[0] = 1; res[1] = 0;
        f = work(s);
        if(f) {
            pr();
            continue;
        }
        res[0] = 0; res[1] = 1;
        f = work(s);
        if(f) {
            pr();
            continue;
        }
        cout << -1 << endl;
    }
}
int main() {
