bool dp[5010][5010];
bool check(int in)
{
    int copy = a[in];
    a[in] = 0;
    for(int i = 0; i < k; i++){
        if(i == a[0]){
            dp[0][i] = true;
        } else {
            dp[0][i] = false;
        }
    }
    for(int i = 1; i < a.size(); i++){
        for(int j = 0; j < k; j++){
            if(a[i] > j){
                dp[i][j] = dp[i - 1][j];
            } else {
                dp[i][j] = (dp[i - 1][j] || dp[i - 1][j - a[i]]);
            }
        }
    }
    a[in] = copy;
    for(int i = k - copy; i < k; i++){
        if(dp[a.size() - 1][i] == true){
            return true;
        }
    }
    return false;
}

