bool fichk(vector<bool> &f, string s){
  if((s.at(0) == 'x') ^ f.at(0)){
    return f.at(1) == f.at(f.size()-2);
  }else{
    return f.at(1) != f.at(f.size()-2);
  }
}

bool fc(vector<bool> &f, string s){
  int n = s.size();
  rep2(i, 1, n){
    bool c = (s.at(i) == 'x');
    if((f.at(i) ^ c) == true){
      f.at(i+1) = f.at(i-1);
    }else{
      f.at(i+1) = !f.at(i-1);
    }
  }
  // rep(i, f.size()) cerr << f.at(i);
  // cerr << endl;
  if(f.at(0) == f.at(n) && fichk(f, s)) return true;
  return false;
}

