using namespace std;
typedef vector<int> vec;

struct disjoint{
	vec p;
	disjoint(){}
	disjoint(int n):p(n+1){
		for(int i=1;i<=n;i++)
			p[i]=i;
	}

	int find(int x){
		if(p[x]==x)return x;
		return p[x]=find(p[x]);
	}

	bool merge(int x,int y){
		x=find(x),y=find(y);
		if(x==y)return 0;
		p[x]=y;
		return 1;
	}

	bool chk(int x,int y){
		return find(x)==find(y);
	}
}z[2][2];

int N;
const int MAX_N = 100010;

char a[MAX_N];

int main(){
	scanf("%d",&N);
	scanf("%s",a+1);

	for(int i=0;i<2;i++){
		for(int j=0;j<2;j++){
			z[i][j]=disjoint(N*2);
			if(i==j){
				z[i][j].merge(1,2);
				z[i][j].merge(1+N,2+N);
			}else{
				z[i][j].merge(1,2+N);
				z[i][j].merge(2,1+N);
			}
			for(int k=1;k<=N;k++){
				int cnt=0;
				if(a[k]=='o')cnt++;
				if(i==0)cnt++;
				if(z[i][j].chk(1,k))cnt++;
				int l=(k-1>=1?k-1:N),r=(k+1<=N?k+1:1);
				if(cnt&1){
					z[i][j].merge(l,r);
					z[i][j].merge(l+N,r+N);
				}else{
					z[i][j].merge(l,r+N);
					z[i][j].merge(r,l+N);
				}
			}
			bool ok=true;
			for(int k=1;k<=N;k++){
				if(z[i][j].chk(k,k+N))ok=false;
			}
			if(ok){
				for(int k=1;k<=N;k++){
					int cnt=(i==0);
					if(z[i][j].chk(1,k))cnt++;
					if(cnt&1)putchar('W');
					else putchar('S');
				}
				puts("");
				return 0;
			}
		}
	}

