			sw[1] = 1;
		} else if (k == 2) {
			sw[0] = 1;
			sw[1] = 0;
		}
		else sw[0] = sw[1] = 1;

		for (int i = 1; i < n-1; i++) {
			if (sw[i] == 0) {
				if (s[i] == 'o') {
					sw[i+1] = 1 - sw[i-1];
				} else {
					sw[i+1] = sw[i-1];
				}
			} else {
				if (s[i] == 'o') {
					sw[i+1] = sw[i-1];
				} else {
					sw[i+1] = 1 - sw[i-1];
				}
			}
		}

		bool b = true;
		if (sw[n-1] == 0) {
			if (s[n-1] == 'o') {
				if (sw[n-2] == sw[0]) b = false;
			} else {
				if (sw[n-2] != sw[0]) b = false;
			}
		} else {
			if (s[n-1] == 'o') {
				if (sw[n-2] != sw[0]) b = false;
			} else {
				if (sw[n-2] == sw[0]) b = false;
			}
		}
		if (b) {
			string ans = "";
			rep(i,n) ans += (sw[i] ? 'S': 'W');
			cout << ans << endl;
			return 0;
		}
	}
	cout << -1 << endl;
}

