		if (ans[N - 1] == 'S' && s[N - 1] == 1 && ans[N - 2] == ans[0]) OK = false;
		if (ans[N - 1] == 'W' && s[N - 1] == 0 && ans[N - 2] == ans[0]) OK = false;
