				ans[i] ^= (s[(i + 3 * j) % N] ^ s[(i + 1 + 3 * j) % N]);
			}
			ans[i] ^= s[(i + 3 * l) % N];
		}
		for (int i = 2; i < N; i++) {
			if (N % 3 == 1) ans[i] = s[(i - 1 + N) % N] ^ ans[i - 1] ^ ans[i - 2];
			else ans[i] = s[(i + 2) % N] ^ ans[i - 1] ^ ans[i - 2];
		}
