using namespace std;

char GetNext(char c, char p, char s) {
  static constexpr char var[][2][2] = {
    {{'S', 'W'}, {'W', 'S'}}, {{'W', 'S'}, {'S', 'W'}},
  };
  c = (c == 'S') ? 0 : 1;
  p = (p == 'S') ? 0 : 1;
  s = (s == 'o') ? 0 : 1;
  return var[c][p][s];
}

string Solve(const string& s) {
  const int N = s.size();

  for (string r : {"SS", "SW", "WS", "WW"}) {
    for (int i = 1; i < N; ++i) {
      r.push_back(GetNext(r[i], r[i - 1], s[i]));
    }
    r.push_back(GetNext(r[N], r[N - 1], s[0]));
    if (r[N] == r[0] && r[N + 1] == r[1])
      return r.substr(0, N);
  }
  return "-1";
}

int main() {
  int N;
  string s;
  cin >> N >> s;
  cout << Solve(s) << "\n";
  return 0;
}

