void solve(){
  for(int i=1;i<N-1;i++){
    if(s[i]=='o'){
      if(a[i]==1) a[i+1]=a[i-1];
      else a[i+1]= a[i-1]==1?2:1;
    }else{
      if(a[i]==1) a[i+1]= a[i-1]==1?2:1;
      else a[i+1]=a[i-1];
    }
  }
  return;
}

bool judge(){
  for(int i=0;i<N;i++){
    int prev,next;
    if(i==0) prev=N-1;
    else prev=i-1;
    if(i==N-1) next=0;
    else next=i+1;
    if(s[i]=='o'){
      if(a[i]==1){
        if(a[prev]!=a[next]) return 0;
      }else{
        if(a[prev]==a[next]) return 0;
      }
    }else{
      if(a[i]==1){
        if(a[prev]==a[next]) return 0;
      }else{
        if(a[prev]!=a[next]) return 0;
      }
    }
  }
  return 1;
}

