#include <bits/stdc++.h>
using namespace std;
typedef long long ll;

int N;
string s;
bool zoo[100007];

bool check(char ch, bool a, bool b, bool c)
{
    if (b) {
        if (ch == 'o') {
            return a == c;
        } else {
            return a != c;
        }
    } else {
        if (s[N - 1] == 'o') {
            return a != c;
        } else {
            return a == c;
        }
    }
}

bool solve(bool first, bool second)
{
    zoo[0] = first;
    zoo[1] = second;
    for (int i = 2; i < N; i++) {
        if (zoo[i - 1]) {
            if (s[i - 1] == 'o') {
                zoo[i] = zoo[i - 2];
            } else {
                zoo[i] = !zoo[i - 2];
            }
        } else {
            if (s[i - 1] == 'o') {
                zoo[i] = !zoo[i - 2];
            } else {
                zoo[i] = zoo[i - 2];
            }
        }
    }

    return check(s[N - 1], zoo[N - 2], zoo[N - 1], zoo[0]) &&
           check(s[0], zoo[N - 1], zoo[0], zoo[1]);
}

void display()
{
    for (int i = 0; i < N; i++) {
        cout << (zoo[i] ? 'S' : 'W');
    }
    cout << endl;
}

int main()
{
    ios::sync_with_stdio(false);
    cin.tie(0);

    cin >> N >> s;

    if (solve(1, 1)) {
        display();
        return 0;
    }
    if (solve(1, 0)) {
        display();
        return 0;
    }
    if (solve(0, 1)) {
        display();
        return 0;
    }
    if (solve(0, 0)) {
        display();
        return 0;
    }

    cout << -1 << endl;

    return 0;
}

