void bfs(int n) {

    if (flag) return;

    if (n == N-2) {

        if (t[n] == 'o') {
            if (ans[n] == 'S') {
                if (ans[n-1] == 'S' && ans[n+1] == 'S') flag = true;
                else if (ans[n-1] == 'W' && ans[n+1] == 'W') flag = true;
            }
            else {
                if (ans[n-1] == 'S' && ans[n+1] == 'W') flag = true;
                else if (ans[n-1] == 'W' && ans[n+1] == 'S') flag = true;
            }
        }
        else {
            if (ans[n] == 'S') {
                if (ans[n-1] == 'S' && ans[n+1] == 'W') flag = true;
                else if (ans[n-1] == 'W' && ans[n+1] == 'S') flag = true;
            }
            else {
