            ans[N-1]='W'; ans[1]='W'; bfs(n+1);

            ans[0]='W';
            ans[N-1]='W'; ans[1]='S'; bfs(n+1);
            ans[N-1]='S'; ans[1]='W'; bfs(n+1);
