            ans[N-1]='W'; ans[1]='S'; bfs(n+1);

            ans[0]='W';
            ans[N-1]='W'; ans[1]='W'; bfs(n+1);
            ans[N-1]='S'; ans[1]='S'; bfs(n+1);
        }
    }
    else {

        if (ans[n] == 'S') {
            if (t[n] == 'o') {
                if (ans[n-1] == 'S') {
                    ans[n+1]='S';
                    bfs(n+1);
                }
                else if (ans[n-1] == 'W'){
                    ans[n+1]='W';
                    bfs(n+1);
                }
            }
            else {
                if (ans[n-1] == 'S') {
                    ans[n+1]='W';
                    bfs(n+1);
                }
                else if (ans[n-1] == 'W') {
                    ans[n+1]='S';
                    bfs(n+1);
                }
            }
        }
        else if (ans[n] == 'W'){
            if (t[n] == 'o') {
                if (ans[n-1] == 'S') {
                    ans[n+1] = 'W';
                    bfs(n+1);
                }
                else if (ans[n-1] == 'W') {
                    ans[n+1] = 'S';
                    bfs(n+1);
                }
            }
            else {
                if (ans[n-1] == 'S') {
                    ans[n+1] = 'S';
                    bfs(n+1);
                }
                else if (ans[n-1] == 'W'){
                    ans[n+1] = 'W';
                    bfs(n+1);
                }
            }
        }
    }

}

