			if (nxt(A[n-2], A[n-1], T[n-1]) != A[0]) continue;

			FOR (i, 0, n)
			{
				if (A[i] == 0) printf("S");
				else printf("W");
			}
			printf("\n");
			return 0;
		}
	}

