inline bool check(const string &s, const string &ans, int p){
  int n = s.size();
  if( (s[p]=='x') xor (ans[p]=='S') ) return ans[(p+n-1)%n] == ans[(p+1)%n];
  else return ans[(p+n-1)%n] != ans[(p+1)%n];
}

inline string solve(const string &s, int start){
  string ans = "";
  ans += (start%2 ? "S" : "W");
  ans += (start/2 ? "S" : "W");

  for(int i=1;i<(int)s.size()-1;i++){
    if( (s[i]=='x') xor (ans[i]=='S') ) ans += ans[i-1];
    else if(ans[i-1] == 'S') ans += 'W';
    else ans += 'S';
  }

  if( check(s,ans,0) and check(s,ans,s.size()-1) ) return ans;
  return "-1";
}

