  int n;
  cin >> n;
  string s;
  cin >> s;

  rep(i,4){
    string tmp = solve(s,i);
    if(tmp != "-1"){
      cout << tmp << endl;
      return 0;
    }
  }
  cout << -1 << endl;
}

