class DMenagerie {
public:
  static void solve(istream &cin, ostream &cout) {
    int N;
    string S;
    cin >> N >> S;
    rep(i, bpm(2, 2)) {
      vector<int> check(N + 2, 0);
      rep(j, 2) {
        if ((i >> j) & 1) {
          check[j + 1] = 1;
        } else {
          check[j + 1] = -1;
        }
      }
      if (check[1] == 1) {
        if (S[0] == 'o') {
          check[0] = check[2];
        } else {
          check[0] = check[2] * -1;
        }
      } else {
        if (S[0] == 'o') {
          check[0] = check[2] * -1;
        } else {
          check[0] = check[2];
        }
      }
      FOR(j, 1, N) {
        if (check[j + 1] == 1) {
          if (S[j] == 'o') {
            check[j + 2] = check[j];
          } else {
            check[j + 2] = check[j] * -1;
          }
        } else {
          if (S[j] == 'o') {
            check[j + 2] = check[j] * -1;
          } else {
            check[j + 2] = check[j];
          }
        }
      }
      if (!(check[0] == check[N] and check[1] == check[N + 1])) goto label;
      rep(j, N) {
        if (check[j + 1] == 1) {
          cout << "S";
        } else {
          cout << "W";
        }
      }
      cout << endl;
      return;
    label:;
    }
    cout << -1 << endl;
  }
};


