    vector<char> ans(N, '-');


    ans[0] = x, ans[N - 1] = y;

    rep(i, N){
        if(ans[i] == 'W') S[i] = S[i] == 'o' ? 'x' : 'o';

        bool flag = ans[(i + 1) % N] == '-';

        if(S[i] == 'o'){
            if(!flag) if(ans[(i + 1) % N] != ans[(i - 1 + N) % N]) return {ans, false};
