        if (A[N-2][c[i]] == 'S' && A[N-1][c[i]] == 'S' && A[0][c[i]] == 'S') flag = true;
        if (A[N-2][c[i]] == 'S' && A[N-1][c[i]] == 'W' && A[0][c[i]] == 'W') flag = true;
        if (A[N-2][c[i]] == 'W' && A[N-1][c[i]] == 'S' && A[0][c[i]] == 'W') flag = true;
        if (A[N-2][c[i]] == 'W' && A[N-1][c[i]] == 'W' && A[0][c[i]] == 'S') flag = true;
      } else {
        if (A[N-2][c[i]] == 'S' && A[N-1][c[i]] == 'S' && A[0][c[i]] == 'W') flag = true;
        if (A[N-2][c[i]] == 'S' && A[N-1][c[i]] == 'W' && A[0][c[i]] == 'S') flag = true;
        if (A[N-2][c[i]] == 'W' && A[N-1][c[i]] == 'S' && A[0][c[i]] == 'S') flag = true;
        if (A[N-2][c[i]] == 'W' && A[N-1][c[i]] == 'W' && A[0][c[i]] == 'W') flag = true;
      }
      if (flag) k = c[i];
    }
  }

  if (k == -1) cout << -1 << endl;
  else {
    rep(i,N) cout << A[i][k];
    cout << endl;
  }
}

