#include <bits/stdc++.h>

#define MAXN (100010)

int n;
char str[MAXN];
char ans[MAXN];

bool check(char fst, char snd){
	for(int i = 0; i < MAXN; ++ i) ans[i] = 2;
	ans[0] = fst;
	ans[1] = snd;
	if((ans[0] == 0 && str[0] == 'o') || (ans[0] == 1 && str[0] == 'x')) ans[n - 1] = ans[1];
	else ans[n - 1] = !ans[1];
	for(int i = 1; i < n; ++ i){
		int pre = i - 1, sec = (i + 1) % n;
		if((ans[i] == 0 && str[i] == 'o') || (ans[i] == 1 && str[i] == 'x')){
			if(ans[sec] != 2 && ans[sec] != ans[pre]) return false;
			ans[sec] = ans[pre];
		}
		else{
			if(ans[sec] != 2 && ans[sec] == ans[pre]) return false;
			ans[sec] = !ans[pre];
		}
	}
	for(int i = 0; i < n; ++ i){
		ans[i] = ans[i] ? 'W' : 'S';
	}
	ans[n] = 0;
	return true;
}

int main(){
	scanf("%d%s", &n, str);
	if(check(0, 0)) return printf("%s\n", ans), 0;
	if(check(0, 1)) return printf("%s\n", ans), 0;
	if(check(1, 0)) return printf("%s\n", ans), 0;
	if(check(1, 1)) return printf("%s\n", ans), 0;
	printf("-1\n");
	return 0;
}

