bool put_nums(int flag[], int now, string s, int n)
{
    if(now==n-2 || now==n-1){
        if(s[now]=='x' && flag[now+2]==flag[now+1]*(-flag[now])) return true;
        else if(s[now]=='o' && flag[now+2]==flag[now+1]*flag[now]) return true;
        else return false;
    }else{
        if(s[now]=='x'){
            flag[now+2]=flag[now+1]*(-flag[now]);
        }else{
            flag[now+2]=flag[now+1]*flag[now];
        }
    }
    return true;
}

