int main() {
	int N; cin >> N;
	string s; cin >> s;
	bool flag = false;
	// 0 is sheep, 1 is wolf
	for (int p = 0; p < 4 && !flag; p++) {
		vector<int> ani(N, 2);
		int temp = p;
		ani[N - 1] = temp % 2;
		temp /= 2;
		ani[1] = temp % 2;
		if (ani[N - 1] == ani[1])
			ani[0] = (s[0] == 'o' ? 0 : 1);
		else
			ani[0] = (s[0] == 'x' ? 0 : 1);
		for (int i = 1; i < N - 1; i++) {
			if (ani[i] == 0 )
				ani[i + 1] = (s[i] == 'o' ? ani[i - 1] : (ani[i - 1] + 1) % 2);
			else if (ani[i] == 1)
				ani[i + 1] = (s[i] == 'o' ? (ani[i - 1] + 1) % 2 : ani[i - 1]);
		}
		if (ani[N - 1] == 0) {
			if (s[N - 1] == 'o' && ani[N - 2] == ani[0])
				flag = true;
			else if (s[N - 1] == 'x' && ani[N - 2] != ani[0])
				flag = true;
		}
		else if (ani[N - 1] == 1) {
			if (s[N - 1] == 'o' && ani[N - 2] != ani[0])
				flag = true;
			else if (s[N - 1] == 'x' && ani[N - 2] == ani[0])
				flag = true;
		}
		/*
		for (int i = 0; i < N; i++) {
			cout << ani[i];
		}
		*/
		cout << endl;
		if (flag) {
			for (int i = 0; i < N; i++)
				cout << (ani[i] == 0 ? 'S' : 'W');
			cout << endl;
		}
	}
	if (!flag) cout << -1 << endl;
}

