char flip(char i) {
  if (i == 's') return 'w';
  else return 's';
}

char s_next(char op, char prev) {
  if (op == 'o') return prev;
  if (op == 'x') return flip(prev);
}

char w_next(char op, char prev) {
  if (op == 'o') return flip(prev);
  if (op == 'x') return prev;
}

int main() {
  int n;
  string input;
  cin >> n >> input;
  auto x = vector<string>({"ss", "sw", "ws", "ww"});

  string shin = "-1";
  for (auto start : x) {
    auto ans = start;
    int ansIdx = 1;    
    for(int i = 0; i < n; i++) {
      if (ans[ansIdx] == 's') {
        ans += s_next(input[i], ans[ansIdx - 1]);
      } else {
        ans += w_next(input[i], ans[ansIdx - 1]);
      }
      ansIdx++;
    }
    if (ans[0] == ans[ans.length() - 1] &&
        ans[1] == ans[ans.length() - 2]) {
      shin = ans.substr(1, n);
    }
  }
  cout << shin << endl;
}

