		}
		else{
			if(s[i]=='o'&&ans[l]==ans[r])return 0;
			if(s[i]=='x'&&ans[l]!=ans[r])return 0;
		}
	}
	return 1;
}
void work(){
	for(int i=2;i<n;i++){
		if(ans[i]==1){
			if(s[i]=='o')ans[i+1]=ans[i-1];
			else ans[i+1]=(ans[i-1]==1?2:1);
		}
		else{
			if(s[i]=='o')ans[i+1]=(ans[i-1]==1?2:1);
			else ans[i+1]=ans[i-1];
		}
	}
}
