using namespace std;

int main() {
	int N;
	cin >> N;

	string s;
	cin >> s;

	for (int mask = 0; mask < 4; mask++) {
		// 0が羊, 1が狼
		int st0 = (mask >> 0) & 1,
			st1 = (mask >> 1) & 1;
		cerr << "(0, 1) " << st0 << ", " << st1 << endl;
		vector<int> states(N, -1);
		states[0] = st0;
		states[1] = st1;

		bool complete = true;

		for (int i = 1; i < N; i++) {
			// i,i-1を利用して次の状態を決定する。
			int nxt = (i + 1) % N;
			int prv = (i - 1 + N) % N;
			int nxtstate = -1;

			if (states[i] == 0) { // 羊
				if (s[i] == 'o') nxtstate = states[prv];
				else nxtstate = states[prv] ^ 1;
			} else {	// 狼
				if (s[i] == 'o') nxtstate = states[prv] ^ 1;
				else nxtstate = states[prv];
			}
			if (states[nxt] >= 0 && states[nxt] != nxtstate) complete = false;

			states[nxt] = nxtstate;
		}

		if (!complete) continue;

		for (int i = 0; i < N; i++) {
			cout << "SW"[states[i]];
		}
		cout << endl;

		return 0;
	}

	cout << -1 << endl;

	return 0;
}

