      if(X[l]!='#'&&X[r]!='#') {
        ok&=f(X[i],X[l],S[i])==X[r]&&f(X[i],X[r],S[i])==X[l];
      } else if(X[l]=='#') X[l]=f(X[i],X[r],S[i]);
      else X[r]=f(X[i],X[l],S[i]);
    }
    if(ok) {
      // assertion
