void solve() {
  map<char,int> F={{'o',1},{'0',0}};
  const char A[2]={wo,sh};
  VI X(N,0);
  REP(mask,4) {
    X[0]=mask&1,X[1]=(mask>>1)&1;
    FOR(i,1,N-1) X[i+1]=(F[S[i]]+X[i-1]+X[i])%2;
    if(X[0]==(X[N-2]+X[N-1]+F[S[N-1]])%2) {
