char next_char(char pre, char cur, char tf) {
  string SW = "WS", OX = "xo";
  int x1 = SW.find(pre);
  int x2 = SW.find(cur);
  int x3 = OX.find(tf);
  int x4 = !(x2 ^ x3);
  int x5 = (x4) ? x1 : (1 - x1);
  return SW[x5];
}

string mkstr(string sw, string ox) {
  string x;
  int m = sw.size(), n = ox.size();
  x = sw;
  for (int i = m - 1; i < n - 1; i++) {
    char y = next_char(x[i - 1], x[i], ox[i]);
    x.push_back(y);
  }
  return x;
}

