void f(const string &s, char sw0, char sw1)
{
    ll n = s.size();
    char swlist[n];
    memset(swlist, 0, sizeof(swlist));
    swlist[0] = sw0;
    swlist[1] = sw1;

    rep (i, n-2) {
        assert(swlist[i+1] == 'S' || swlist[i+1] == 'W');
        if (swlist[i+1] == 'S' && s[i+1] == 'o') {
            swlist[i+2] = swlist[i] == 'S' ? 'S' : 'W';
        }
        else if (swlist[i+1] == 'W' && s[i+1] == 'x') {
            swlist[i+2] = swlist[i] == 'S' ? 'S' : 'W';
        }
        else {
            swlist[i+2] = swlist[i] == 'W' ? 'S' : 'W';
        }
    }

    assert(swlist[0] == 'S' || swlist[0] == 'W');
    assert(swlist[1] == 'S' || swlist[1] == 'W');
    assert(swlist[n-2] == 'S' || swlist[n-2] == 'W');
    assert(swlist[n-1] == 'S' || swlist[n-1] == 'W');

    bool ok = true;

    if (swlist[0] == 'S' && s[0] == 'o') {
        if (swlist[1] != swlist[n-1]) ok = false;
    }
    else if (swlist[0] == 'W' && s[0] == 'x') {
        if (swlist[1] != swlist[n-1]) ok = false;
    }
    else {
        if (swlist[1] == swlist[n-1]) ok = false;
    }

    if (swlist[n-1] == 'S' && s[n-1] == 'o') {
        if (swlist[n-2] != swlist[0]) ok = false;
    }
    else if (swlist[n-1] == 'W' && s[n-1] == 'x') {
        if (swlist[n-2] != swlist[0]) ok = false;
    }
    else {
        if (swlist[n-2] == swlist[0]) ok = false;
    }

    if (ok) print_result(swlist, n);
}

