            print(A, N);
            flg = true;
        } else {
            flg =  false; 
        }

    } else {
        if (A[0] * A[1] == -A[N-1] && A[N] == A[0]){
            print(A, N);
            flg =  true;
        } else {
            flg =  false; 
        }
    }
    return flg;
}

