bool check(int n, const string &s, vector<char> &ans) {

    auto set = [&](int i, char a) {
        i = i % n;
        if (ans[i] == ' ') {
            ans[i] = a;
            return true;
        }
        if (ans[i] == a) {
            return true;
        }
        return false;
    };

    rep(i, n) {
        char c = s[i];
        char a = ans[i];
        char pa = ans[(n + i - 1) % n];
        if (a == 'S') {
            if (c == 'o') {
                if (pa == 'S') {
                    bool b = set(i + 1, 'S');
                    if (!b) return false;
                } else {
                    bool b = set(i + 1, 'W');
                    if (!b) return false;
                }
            } else {
                if (pa == 'S') {
                    bool b = set(i + 1, 'W');
                    if (!b) return false;
                } else {
                    bool b = set(i + 1, 'S');
                    if (!b) return false;
                }
            }
        } else {
            if (c == 'o') {
                if (pa == 'S') {
                    bool b = set(i + 1, 'W');
                    if (!b) return false;
                } else {
                    bool b = set(i + 1, 'S');
                    if (!b) return false;
                }
            } else {
                if (pa == 'S') {
                    bool b = set(i + 1, 'S');
                    if (!b) return false;
                } else {
                    bool b = set(i + 1, 'W');
                    if (!b) return false;
                }
            }
        }
    }
    return true;
}

