void flip(string &s, int i) {
	int N = s.size();
	for (int j = -1; j <= 1; j++) {
		if (s[(j + i+N) % N] == 'x') {
			s[(j + i+N) % N] = 'o';
		}
		else {
			s[(j + i+N) % N] = 'x';
		}
	}
}
