	for (int i = 0; i < N; i++) {
		if (i == 0) {
			res.push_back('S');
		}
		else {
			if (s[i - 1] == 'x') {
				res.push_back('W');
				flip(s, i);

			}
			else {
				res.push_back('S');
			}
		}

	}
	if (s[0] == 'o' &&s[N - 1] == 'o') {
		cout << res << endl;
		return 0;
	}
	s = a;
	res.clear();
	for (int i = 0; i < N; i++) {
		if (i == 0) {
			res.push_back('W');
