using i64=int64_t;

void solve(){
    int n;
    string s;
    cin >> n >> s;
    vector<int> ans(n);
    rep(i,0,2){
        rep(j,0,2){
            ans[0]=i;
            ans[1]=j;
            rep(k,1,n-1){
                if(s[k]=='o') ans[k+1]=ans[k-1];
                if(s[k]=='x') ans[k+1]=1-ans[k-1];
                if(ans[k]==1) ans[k+1]=1-ans[k+1];
            }

            auto ok=[&](int k){
                bool ok_;
                if(s[k]=='o') ok_=ans[(k+1)%n]==ans[(k-1+n)%n];
                if(s[k]=='x') ok_=ans[(k+1)%n]!=ans[(k-1+n)%n];
                if(ans[k]==1) ok_=!ok_;
                return ok_;
            };
            if(ok(0) and ok(n-1)){         
                rep(k,0,n) cout << (ans[k]==0?'S':'W');
                cout << endl;
                return;
            }
        }
    }
    cout << -1 << endl;
}

int main(){
    std::cin.tie(0);
    std::ios::sync_with_stdio(false);
    cout.setf(ios::fixed);
    cout.precision(10);
    solve();
    return 0;
}

