bool process(int n, char str[], char code[],int pos){
	if( pos == n ){
		return checker(n,str,code);
	}
	code[pos] = 's';
	if(process(n,str,code,pos+1))
		return true;
	code[pos] = 'w';
	if(process(n,str,code,pos+1))
		return true;

	return false;
}
bool checker(int n, char str[], char code[]){
	int i;
	int a,b;

	a = n - 1;
	b = 1;
	for(i=0; i<n; i++, a++, b++){
		if( code[i] == 's' ){
			if( str[i]  == 'o'){
				if( code[a%n] != code[b%n] )
					return false;
			}else{
				if( code[a%n] == code[b%n] )
					return false;
			}
		}else{
			if( str[i]  == 'o'){
				if( code[a%n] == code[b%n] )
					return false;
			}else{
				if( code[a%n] != code[b%n] )
					return false;
			}
		}
	}

	return true;
}

