char is_same(const int pattern) {
	auto same = ((pattern >> 2) & pattern & 1) == (((pattern >> 2) | pattern) & 1);
	if ((pattern & 2) == 0) {
		return same ? 'o' : 'x';
	}
	else {
		return same ? 'x' : 'o';
	}
}
std::unique_ptr<std::string> make_str(const std::vector<std::vector<bool>> can_make) {
	auto last = std::distance(can_make[1].begin(), std::find(can_make[1].begin(), can_make[1].end(), true));
	if (last == can_make[1].size()) return nullptr;
	last >>= 1;
	for (int j = 0; j < 2; ++j) {
		if (can_make[0][(j << 1) + last]) {
			last = j;
			break;
		}
	}
	std::string result; result.push_back(last == 0 ? 'S' : 'W');
	for (int i = can_make.size() - 1; i > 0; --i) {
		for (int j = 0; j < 2; ++j) {
			if (can_make[i][(j << 1) + last]) {
				result.push_back(j == 0 ? 'S' : 'W');
				last = j;
				break;
			}
		}
	}
	std::reverse(result.begin(), result.end());
	return std::make_unique<std::string>(std::move(result));
}
std::unique_ptr<std::string> make_pattern(const std::string& str, const int first_two) {
	std::vector<std::vector<bool>> can_make(str.size(), std::vector<bool>(4, false));
	can_make[1][first_two] = true;
	for (auto i = 2; i <= str.size(); ++i) {
		for (auto prev = 0; prev < 4; ++prev) if (can_make[i - 1][prev]) {
			for (auto j = 0; j < 2; ++j) {
				can_make[i % str.size()][((prev << 1) + j) & 3] = can_make[i % str.size()][((prev << 1) + j) & 3] || (str[i - 1] == is_same((prev << 1) + j));
			}
		}
	}
	can_make[1][first_two] = false;
	for (auto j = 0; j < 2; ++j) if (can_make[0][(j << 1) + (first_two >> 1)]) {
		can_make[1][first_two] = can_make[1][first_two] || is_same((j << 2) + first_two) == str[0];
	}
	return make_str(std::move(can_make));
}

int main() {
	int n; std::cin >> n;
	std::string str; std::cin >> str;
	std::unique_ptr<std::string> result{ nullptr };
	for (auto i = 0; i < 4; ++i) {
		result = make_pattern(str, i);
		if (result != nullptr) break;
	}
	if (result == nullptr) {
		std::cout << "-1\n";
	}
	else {
		std::cout << *result << '\n';
	}
}

