using namespace std;

#define MAX_N 100005
int N;
string S;

void input()
{
  cin >> N;
  cin >> S;
}

int kind[MAX_N];

void calc(int pos = 1)
{
  int left, right;
  if(pos == 0){
    left = N-1;
  }
  else{
    left = pos-1;
  }
  right = (pos+1)%N;

  int k = kind[left];
  if(kind[pos] == 1){
    if(S[pos] == 'x'){
      if(k == 1){
        k = 2;
      }
      else{
        k = 1;
      }
    }

  }
  else{
    if(S[pos] == 'o'){
      if(k == 1){
        k = 2;
      }
      else{
        k = 1;
      }
    }
  }

  if(kind[right] != 0){
    return;
  }
  else{
    kind[right] = k;
    calc((pos+1)%N);
  }
}

