#define INT(n) int n;scanf("%d",&n)
#define STR(s) string s;cin>>s

int main(){
  INT(n); STR(s);
  vector<string> init = {"SS", "SW", "WS", "WW"};
  string ans;
  auto check = [&](string s, string ans, int i){
    if ((ans[i] == 'S' && s[i] == 'o') || (ans[i] == 'W' && s[i] == 'x')){
      return (ans[(i + 1) % n] == ans[(i + n - 1) % n]);
    }
    else {
      return (ans[(i + 1) % n] != ans[(i + n - 1) % n]);
    }
  };

  REP(i, 0, 4){
    string tmp = init[i];
    REP(j, 1, n - 1){
      if ((tmp[j] == 'S' && s[j] == 'o') || (tmp[j] == 'W' && s[j] == 'x')){
        tmp += tmp[j - 1];
      }
      else if (tmp[j - 1] == 'S'){
        tmp += 'W';
      }
      else {
        tmp += 'S';
      }
    }
    if (check(s, tmp, 0) && check(s, tmp, n - 1)){
      ans = tmp;
      break;
    }
  }
  if(SZ(ans) == n){
    cout << ans << endl;
  }
  else {
    cout << -1 << endl;
  }
  return 0;
}

