    std::cin >> s;

    std::vector<int> kinds(N);   // 0:羊, 1:狼

    for (int mask = 0; mask < (1 << 2); mask++) {
        std::fill(kinds.begin(), kinds.end(), -1);

        kinds[0] = (mask >> 0) & 1;
        kinds[1] = (mask >> 1) & 1;

        bool ok = true;
        for (int i = 1; i <= N; i++) {
