ll GCD(ll a, ll b){
    if(a < b) swap(a, b);
    if(b == 0) return a;
    return GCD(b, a%b);
}

bool cmp(const pii& a, const pii& b){
    if(a.first == b.first){
        return a.second < b.second;
    }
    return a.first < b.first;
}

bool isPalindrome(string s) {

    bool isPalindrome = true;
    int i = 0, j = s.size() - 1;
    while(isPalindrome && i <= j) {
        isPalindrome &= s[i] == s[j];
        i++;
        j--;
    }
    return isPalindrome;
}

