	int N = s.size();
	for (int i = 0; i < N; i++) {
		int b = (i+N-1)%N;
		int a = (i+1)%N;
		if (t[a] == t[b]) {
			if (t[i] == 'S' && s[i] == 'x') return false;
			if (t[i] == 'W' && s[i] == 'o') return false;
