            if((s[t]=='o'&&a[n-2]!=a[0])||(s[t]=='x'&&a[n-2]==a[0]))
            {
                if(a[0]==1)
                {
                    if((s[0]=='o'&&a[1]!=a[t])||(s[0]=='x'&&a[1]==a[t]))
                        flag1=1;
                }
                else
                {
                    if((s[0]=='o'&&a[1]==a[t])||(s[0]=='x'&&a[1]!=a[t]))
                        flag1=1;
                }
            }
        }
        else
        {
            if((s[t]=='o'&&a[n-2]==a[0])||(s[t]=='x'&&a[n-2]!=a[0]))
            {
                if(a[0]==1)
                {
                    if((s[0]=='o'&&a[1]!=a[t])||(s[0]=='x'&&a[1]==a[t]))
                        flag1=1;
                }
                else
                {
                    if((s[0]=='o'&&a[1]==a[t])||(s[0]=='x'&&a[1]!=a[t]))
                        flag1=1;
                }
            }
        }
        if(flag1)
        {
            for(int i=0;i<n;i++)
            {
                if(a[i]==0) printf("S");
                else    printf("W");
            }
            printf("\n");
            flag=0;
        }
        return;
    }
    if(a[t]==0)
    {
        if(s[t]=='o')
            a[t+1]=a[t-1];
        else
            a[t+1]=1-a[t-1];
    }
    else
    {
        if(s[t]=='o')
            a[t+1]=1-a[t-1];
        else
            a[t+1]=a[t-1];
    }
    dfs(t+1);
}

