int slv(int now,int b1,int b2,int fir,string t){
	//cout<<now<<" "<<b1<<" "<<b2<<" "<<fir<<endl;

	if(f==1)return(1);
	if(now>1){
		if(dp[now][b1][b2][fir]!=-1)return(dp[now][b1][b2][fir]);
	}

	if(now==n){
		//cout<<t<<endl;
		//cout<<b2<<" "<<b1<<" "<<fir<<endl;
		if(s[now-1]=='o'){
			if(b1==0){
					if((b2==0 && fir==0) || (b2==1 && fir==1)){
					if(fir==0){
						if(s[0]=='o' && t[1]=='S'){a=t;f=1;return(1);}
						if(s[0]=='x' && t[1]=='W'){a=t;f=1;return(1);}
					}
					else{
						if(s[0]=='o' && t[1]=='W'){a=t;f=1;return(1);}
						if(s[0]=='x' && t[1]=='S'){a=t;f=1;return(1);}
					}
				}
				return(0);
			}	
			else{
				if((b2==0 && fir==1) || (b2==1 && fir==0)){
					if(fir==0){
						if(s[0]=='o' && t[1]=='W'){a=t;f=1;return(1);}
						if(s[0]=='x' && t[1]=='S'){a=t;f=1;return(1);}
					}
					else{
						if(s[0]=='o' && t[1]=='S'){a=t;f=1;return(1);}
						if(s[0]=='x' && t[1]=='W'){a=t;f=1;return(1);}
					}
				}
				return(0);
			}
		}
		if(s[now-1]=='x'){
			if(b1==0){
				if((b2==0 && fir==1) || (b2==1 && fir==0)){
					if(fir==0){
						if(s[0]=='o' && t[1]=='S'){a=t;f=1;return(1);}
						if(s[0]=='x' && t[1]=='W'){a=t;f=1;return(1);}
					}
					else{
						if(s[0]=='o' && t[1]=='W'){a=t;f=1;return(1);}
						if(s[0]=='x' && t[1]=='S'){a=t;f=1;return(1);}
					}
				}
				return(0);
			}
			else{
				if((b2==0 && fir==0) || (b2==1 && fir==1)){
					if(fir==0){
						if(s[0]=='o' && t[1]=='S'){a=t;f=1;return(1);}
						if(s[0]=='x' && t[1]=='W'){a=t;f=1;return(1);}
					}
					else{
						if(s[0]=='o' && t[1]=='W'){a=t;f=1;return(1);}
						if(s[0]=='x' && t[1]=='S'){a=t;f=1;return(1);}
					}
				}
				return(0);
			}

		}
		return(0);
	}
	int r=0;
	if(now==0){
		r=max(slv(now+1,0,-1,0,t+'S'),slv(now+1,1,-1,1,t+'W'));
	}
	if(now==1){
		r=max(slv(now+1,0,b1,fir,t+'S'),slv(now+1,1,b1,fir,t+'W'));
	}
	if(b2==0 && b1==0){
		if(s[now-1]=='o')r=max(r,slv(now+1,0,0,fir,t+'S'));
		else r=max(r,slv(now+1,1,0,fir,t+'W'));
	}
	if(b2==1 && b1==1){
		if(s[now-1]=='o'){r=max(r,slv(now+1,0,1,fir,t+'S'));}
		else r=max(r,slv(now+1,1,1,fir,t+'W'));
	}
	if(b2==0 && b1==1){
		if(s[now-1]=='o')r=max(r,slv(now+1,1,1,fir,t+'W'));
		else r=max(r,slv(now+1,0,1,fir,t+'S'));
	}
	if(b2==1 && b1==0){
		if(s[now-1]=='o')r=max(r,slv(now+1,1,0,fir,t+'W'));
		else r=max(r,slv(now+1,0,0,fir,t+'S'));
	}

	if(now>1)return(dp[now][b1][b2][fir]=r);
	else return(r);
}

