vector<bool> solve(int n, vector<bool> const & s){
  rep(i,2){
    rep(j,2){
      vector<bool> t(n);
      t[0] = i;
      t[1] = j;

      srep(k,2,n){
        t[k]= t[k-2]^t[k-1]^s[k-1];
      }
      if(s[n-1] == (t[n-2]^t[n-1]^t[0]) && s[0] == (t[n-1]^t[0]^t[1])) return t;
    }
  }
  return vector<bool>();
}

