      //        xs[N - 2], xs[N - 1], xs[0], S[N - 1]);
      if (S[N - 1] == 'o') {
        if ((xs[N - 1] == 0 && xs[N - 2] == xs[0]) ||
            (xs[N - 1] == 1 && xs[N - 2] != xs[0])) {
          ;  // ok so far
