        }
      }
      if (S[0] == 'o') {
        if ((xs[0] == 0 && xs[N - 1] == xs[1]) ||
            (xs[0] == 1 && xs[N - 1] != xs[1])) {
          ;  // ok so far
        } else {
          continue;  // inconsistent
        }
      } else {
