bool bfs(int a, int m, int c) {
	memset(b, -1, sizeof(b));
	if (m) {
		if (s[0] == 'o') {
			if (a != c)return false;
		}
		if (s[0] == 'x') {
			if (a == c)return false;
		}
	}
	else {
		if (s[0] == 'o') {
			if (a == c)return false;
		}
		if (s[0] == 'x') {
			if (a != c)return false;
		}
	}
	b[prv(0)] = a; b[0] = m; b[nxt(0)] = c;
	queue<int>que; que.push(prv(0)); que.push(nxt(0));
	while (!que.empty()) {
		int p = que.front(); que.pop();
		if (b[p]) {//本当
			if (b[prv(p)] && !~b[nxt(p)]) {
				if (s[p] == 'o')b[nxt(p)] = b[prv(p)];
				else b[nxt(p)] = !b[prv(p)];
				que.push(nxt(p));
			}
			if (b[nxt(p)] && !~b[prv(p)]) {
