				if (s[p] == 'o')b[prv(p)] = !b[nxt(p)];
				else b[prv(p)] = b[nxt(p)];
				que.push(prv(p));
			}
		}
	}
	rep(i, n) {
		if (b[i]) {
			if (!((s[i] == 'o'&&b[prv(i)] == b[nxt(i)]) || (s[i] == 'x'&&b[prv(i)] != b[nxt(i)])))return false;
