int n;
string s;
vector<char> r;

void chain() {
  rep(i, 1, n-2) {
    if(s[i] == 'o') {
      if(r[i] == 'S') {
        r[i+1] = r[i-1];
      }
      else {
        r[i+1] = r[i-1]=='S' ? 'W' : 'S';
      }
    }
    else {
      if(r[i] == 'S') {
        r[i+1] = r[i-1]=='S' ? 'W' : 'S';
      }
      else {
        r[i+1] = r[i-1];
      }
    }
  }

  if (r[n-2] == 'S') {
    if(s[n-2] == 'o') {
      if(r[n-3] != r[n-1]) return;
    }
    else {
      if(r[n-3] == r[n-1]) return;
    }
  }
  else {
    if(s[n-2] == 'o') {
      if(r[n-3] == r[n-1]) return;
    }
    else {
      if(r[n-3] != r[n-1]) return;
    }
  }

  if (r[n-1] == 'S') {
    if(s[n-1] == 'o') {
      if(r[n-2] != r[0]) return;
    }
    else {
      if(r[n-2] == r[0]) return;
    }
  }
  else {
    if(s[n-1] == 'o') {
      if(r[n-2] == r[0]) return;
    }
    else {
      if(r[n-2] != r[0]) return;
    }
  }

  rep(i,n) cout << r[i];
  cout << endl;
  exit(0);
}

