int main()
{
	int N;
	string s;
	cin >> N >> s;
	string ans = "";
	for (int i = 0; i < N; i++) {
		ans += "-";
	}
	for (int pattern = 0; pattern < 4; pattern++) {
		//ansクリア
		for (int i = 0; i < N; i++) {
			ans[i] = '-';
		}
		//patternに合わせてans初期化
		switch (pattern) {
		case 0:
			ans[0] = 'S';
			if (s[0] == 'o') {
				ans[N - 1] = 'S';
				ans[1] = 'S';
			} else {
				ans[N - 1] = 'S';
				ans[1] = 'W';
			}
			break;
		case 1:
			ans[0] = 'S';
			if (s[0] == 'o') {
				ans[N - 1] = 'W';
				ans[1] = 'W';
			} else {
				ans[N - 1] = 'W';
				ans[1] = 'S';
			}
			break;
		case 2:
			ans[0] = 'W';
			if (s[0] == 'o') {
				ans[N - 1] = 'S';
				ans[1] = 'S';
			} else {
				ans[N - 1] = 'S';
				ans[1] = 'W';
			}
			break;
		case 3:
			ans[0] = 'W';
			if (s[0] == 'o') {
				ans[N - 1] = 'W';
				ans[1] = 'W';
			} else {
				ans[N - 1] = 'W';
				ans[1] = 'S';
			}
			break;
		}
		for (int i = 1; i <= N - 3; i++) {
			//ans[i]までは埋めてあるのでs[i]の情報と合わせてans[i + 1]を埋める
			if (ans[i] == 'S' && s[i] == 'o') {
				ans[i + 1] = ans[i - 1];
