bool cal(vector<bool> ans,vector<bool> ani,int N,int start){
	vector< int > chan(N,0);
	int pos = start;
	int L,R;
	int loop = 0;
	int Count = 0;
	const int Limit = 3;
	bool flag = true;
	while( loop<N ){
		loop++;
		Count++;
		L = (pos+N-1)%N;
		R = (pos+1)%N;
		if( ani[pos] == true){//s
			if( ans[pos] == true ){//両側同じ
				if( ani[L] != ani[R] ){
					ani[R] = ani[L];
					loop = 0;
					chan[R]++;
					if( chan[R] >= Limit ){
						flag = false;
						break;
					}
				}
			}else{//false//両側異なる
				if( ani[L] == ani[R] ){
					ani[R] = !ani[L];
					loop = 0;
					chan[R]++;
					if( chan[R] >= Limit ){
						flag = false;
						break;
					}
				}
			}
		}else{//w
			if( ans[pos] == false ){//両側同じ
				if( ani[L] != ani[R] ){
					ani[R] = ani[L];
					loop = 0;
					chan[R]++;
					if( chan[R] >= Limit ){
						flag = false;
						break;
					}
				}
			}else{//false//両側異なる
				if( ani[L] == ani[R] ){
					ani[R] = !ani[L];
					loop = 0;
					chan[R]++;
					if( chan[R] >= Limit ){
						flag = false;
						break;
					}
				}
			}
		}
		pos = (pos+1)%N;
	}

	if( loop == N ){
		for(int i=0;i<N;++i){
			if( ani[i] ){
				cout << "S";
			}else{
				cout << "W";
			}
		}cout << endl;
		return true;
	}
	return false;
}

inline void solve(){
	int N;
	string str;
	cin >> N >> str;
	vector< bool > ans(N);//false:x true:o
	vector< bool > ani(N,true);//false:w true:s

	for(int i=0;i<N;++i){
		if( str[i] == 'o'){
			ans[i] = true;
		}else{
			ans[i] = false;
		}
	}

	if( cal(ans,ani,N,0) ){
		return;
	}
	if( cal(ans,ani,N,1) ){
		return;
	}
	if( cal(ans,ani,N,2) ){
		return;
	}
	cout << -1 << endl;
}

