{
	if(s.find("o") == -1)
		return true;
	bool flag = true;
	for(int i=0; i<n; i++)
		flag ^= true;

	bool tmp = false;
	for(int i=0; i<s.length(); i++) 
		tmp ^= (translate(s[i]));
	return tmp ^ flag;
}

