		s1 = retstr.substr(retstr.length()-num1, num1) + retstr.substr(0, retstr.length()-num1);
	else {
		reverse(retstr.begin(), retstr.end());
		s1 = retstr.substr(retstr.length()-num1-2, num1+2) + retstr.substr(0, retstr.length()-num1-2);
