void proc() {
    for (int i = 2; i < S.size(); i++) {
        if (tmp[i-1] == 0) {
            if (S[i-1] == 'o') {
                tmp[i] = tmp[i-2];
            } else {
                tmp[i] = 1 - tmp[i-2];
            }
        } else {
            if (S[i-1] == 'o') {
                tmp[i] = 1 - tmp[i-2];
            } else {
                tmp[i] = tmp[i-2];
            }
        }
    }
}

void out() {
    std::string ret;
    for (int i = 0; i < S.size(); i++) {
        if (tmp[i] == 0) {
            ret.push_back('S');
