                }
            }
        }
        bool ok = true;
        for(int i=0;i<2;i++){
            int t = (N-1+i)%N;
            int next = (N+i)%N;
            int prev = (N-2+i)%N;
        if(isSheep[t]){
            if(S[t] == 'o'){
                if(isSheep[next] != isSheep[prev]){
                   ok = false;
                }
            }else{
                if(isSheep[next] == isSheep[prev]){
                    ok = false;
                }
            }
        }else{
            if(S[t] == 'o'){
                if(isSheep[next] == isSheep[prev]){
                    ok = false;
                }
            }else{
                if(isSheep[next] != isSheep[prev]){
                    ok = false;
                }
            }
        }
        }
