		if( str[i] == 'o'){
			ans[i] = true;
		}else{
			ans[i] = false;
		}
	}
	ans[N] = ans[0];

	int pos = 0;
	int L,R;
	int loop = 0;
	int Count = 0;
	bool flag = true;
