		loop++;
		Count++;
		L = (pos+N-1)%N;
		R = (pos+1)%N;
		if( ani[pos] == true){//s
			if( ans[pos] == true ){
				if( ani[L] != ani[R] ){
					ani[R] = ani[L];
					loop = 0;
				}
			}else{//false
				if( ani[L] == ani[R] ){
					ani[R] = !ani[L];
					loop = 0;
				}
			}
		}else{//w
