char func(char cur, char nbr, char info) {
  if (cur == 'S') {
    if (info == 'o') {
      return nbr;
    } else {
      return 'W' + 'S' - nbr;
    }
  } else {
    if (info == 'o') {
      return 'W' + 'S' - nbr;
    } else {
      return nbr;
    }
  }
}
