	for (int i = 0; i < 2; ++i) {
		//ans[0]が羊か狼か
		for (int j = 0; j < 2; ++j) {
		//ans[1]が羊か狼か
			ans[0] = i;
			ans[1] = j;
			for (int k = 2; k < N; ++k) {
				if (ans[k-1] == 1) {
					if (s[k-1]=='o') {
						ans[k] = ans[k-2];
					}
					else {
						ans[k] = 1 - ans[k-2];
					}
				}
				else {
					if (s[k-1]=='o') {
						ans[k] = 1 - ans[k-2];
					}
					else {
						ans[k] = ans[k - 2];
					}
				}
			}
			if (s[0]=='o') {
				if (ans[0] == 1) {
					if (ans[N - 1] != ans[1])continue;
				}
				else {
					if (ans[N - 1] == ans[1])continue;
				}
			}
			else {
				if (ans[0] == 1) {
					if (ans[1] == ans[N - 1])continue;
				}
				else {
					if (ans[1] != ans[N - 1])continue;
				}
			}
			if (s[N - 1] == 'o') {
				if (ans[N - 1] == 1) {
					if (ans[0] != ans[N - 2])continue;
				}
				else {
					if (ans[0] == ans[N - 2])continue;
				}
			}
			else {
				if (ans[N - 1] == 1) {
					if (ans[0] == ans[N - 2])continue;
				}
				else {
					if (ans[0] != ans[N - 2])continue;
				}
