					else if (ans[nxt] == '?') {
						ans[nxt] = ans[pre];
					}
					else {
						ans[pre] = ans[nxt];
					}
				}
			}
			idx = (idx + 1) % n;
		}
		if (ok) {
			printf("%s\n", ans.c_str());
