#include <stdio.h>

void intpl(int N, int* buf, char* str) {
    int i=1;
    while(i<N) {
        if(str[i] == 'o') {
            if(buf[i] == 0) {
                buf[i+1] = buf[i-1];
            } else {
                buf[i+1] = 1 - buf[i-1];
            }
        } else {
            if(buf[i] == 0) {
                buf[i+1] = 1 - buf[i-1];
            } else {
                buf[i+1] = buf[i-1];
            }
        }
        i++;
    }
}

int check(int N, int* buf, char* str) {
    int res = 0;

    if(buf[N-1] == 0) {
        if(str[N-1] == 'o') {
            res = (buf[N-2] == buf[0]);
        } else {
            res = (buf[N-2] != buf[0]);
        }
    } else {
        if(str[N-1] != 'o') {
            res = (buf[N-2] == buf[0]);
        } else {
            res = (buf[N-2] != buf[0]);
        }
    }

    return res;
}

void printAnimal(int N, int* buf) {
    for(int i=0;i<N;i++) {
        if(buf[i]) {
            printf("W");
        } else {
            printf("S");
        }
    }
    printf("\n");
}

