bool check(int a, int b) {
    ans[0] = a;
    ans[1] = b;
    for(int i = 2; i < n; ++i) {
        if(ans[i - 1] == 0) { // おおかみ
            if(v[i - 1] == 0)ans[i] = ans[i - 2];
            else ans[i] = 1 - ans[i - 2];
        } else { // 羊
            if(v[i - 1] == 0)ans[i] = 1 - ans[i - 2];
            else ans[i] = ans[i - 2];
        }
    }

    rep(i, n) {
        int same = v[i];
        if(ans[i] == 0)same = 1 - same;
        int p = ans[(n + i - 1) % n], q = ans[(i + 1) % n];
        if(same&&p!=q)return false;
        if(!same&&p==q)return false;
    }

    return true;
}

