				if(ans[n-1]==1&&ans[0]!=ans[n-2]) ok=false;
			}

			if(s[0]=='o'){
				if(ans[0]==0&&ans[n-1]!=ans[1]) ok=false;
				if(ans[0]==1&&ans[n-1]==ans[1]) ok=false;
			}
			else{
				if(ans[0]==0&&ans[n-1]==ans[1]) ok=false;
				if(ans[0]==1&&ans[n-1]!=ans[1]) ok=false;
			}
			if(ok){
				rep(k,n){
					cout<<"SW"[ans[k]];
				}
				// cout<<s[n-1]<<" "<<ans[0]<<" "<<ans[n-2]<<endl;
				cout<<endl;
				return;
			}
		}
	}
	cout<<-1<<endl;
}


