char same(char c) {
	return c == 'S' ? 'S' : 'W';
}
char diff(char c) {
	return c == 'S' ? 'W' : 'S';
}

void assign(int i) {
	if (out[i] == 'S' && ans[i] == 'o') {
		out[i + 1] = same(out[i - 1]);
	}
	else if (out[i] == 'S' && ans[i] == 'x') {
		out[i + 1] = diff(out[i - 1]);
	}
	else if (out[i] == 'W' && ans[i] == 'o') {
		out[i + 1] = diff(out[i - 1]);
	}
	else {
		out[i + 1] = same(out[i - 1]);
	}
}

bool check(int i) {
	char ret;
	if (out[i] == 'S' && ans[i] == 'o') {
		ret = same(out[(i - 1 + n) % n]);
	}
	else if (out[i] == 'S' && ans[i] == 'x') {
		ret = diff(out[(i - 1 + n) % n]);
	}
	else if (out[i] == 'W' && ans[i] == 'o') {
		ret = diff(out[(i - 1 + n) % n]);
	}
	else {
		ret = same(out[(i - 1 + n) % n]);
	}
	return out[(i + 1) % n] == ret;
}

