typedef long long ll;
int n;
string s;

int dx[] = {0,0,1,1};
int dy[] = {0,1,0,1};
bool visit[111111][2][2][2][2];
bool dp[111111][2][2][2][2];
bool solve(int k,int p,int pp,int f,int ff){
  if (visit[k][p][pp][f][ff]) return dp[k][p][pp][f][ff];
  visit[k][p][pp][f][ff] = true;

  bool ret = false;
  if(k==0){
    for(int i = 0; i < 4; i++){
      ret |= solve(2,dx[i],dy[i],dy[i],dx[i]);
    }
    return dp[k][p][pp][f][ff] = ret;
  }

  ret = false;
  if(k==n){
    if(p==0){
      if(s[k-1]=='o'){
	ret |= (pp==f);
      }else{
	ret |= (pp!=f);
      }
    }else{
      if(s[k-1]=='x'){
	ret |= (pp==f);
      }else{
	ret |= (pp!=f);
      }
    }


    if(ret){
      //cout << p << " " << pp << " " << f << " " << ff << endl;
      ret = false;
      if(f==0){
	if(s[0]=='o'){
	  ret |= (ff==p);
	}else{
	  ret |= (ff!=p);
	}
      }else{
	if(s[0]=='x'){
	  ret |= (ff==p);
	}else{
	  ret |= (ff!=p);
	}
      }

      return dp[k][p][pp][f][ff] = ret;
    }
    return false;
  }

  ret = false;
  if(p==0){
    if(s[k-1]=='o'){
      ret |= solve(k+1,pp,p,f,ff);
    }else{
      ret |= solve(k+1,(pp+1)&1,p,f,ff);
    }
  }else{
    if(s[k-1]=='x'){
      ret |= solve(k+1,pp,p,f,ff);
    }else{
      ret |= solve(k+1,(pp+1)&1,p,f,ff);
    }
  }
  return dp[k][p][pp][f][ff] = ret;
}

string sw = "SW";
void ss(int k,int p,int pp,int f,int ff){
  if(k==n){
    cout << endl;
    return;
  }

  if(k==0){
    for(int i = 0; i < 4; i++){
      if(solve(2,dx[i],dy[i],dx[i],dy[i])){
	cout << sw[dx[i]] << sw[dy[i]];
	ss(2,dx[i],dy[i],dy[i],dx[i]);
	return;
      }
    }
  }else{
    for(int i = 0; i < 2; i++){
      if(solve(k+1,i,p,f,ff)){
	cout << sw[i];
	ss(k+1,i,p,f,ff);
	return;
      }
    }
  }
}

