                ans+=ans[i-2];
            else
            {
                if(ans[i-2]=='S')
                    ans+='W';
                else
                    ans+='S';
            }
        }
        else
        {
            if(a[i-1]=='x')
                ans+=ans[i-2];
            else
            {
                if(ans[i-2]=='S')
                    ans+='W';
                else
                    ans+='S';
            }
        }
    }
}
bool check()
{
    if(ans[0]=='S')
    {
        if(a[0]=='o'&&ans[num-1]!=ans[1])
            return false;
        else if(a[0]=='x'&&ans[num-1]==ans[1])
            return false;
    }
    if(ans[0]=='W')
    {
        if(a[0]=='x'&&ans[num-1]!=ans[1])
            return false;
        else if(a[0]=='o'&&ans[num-1]==ans[1])
            return false;
    }
    if(ans[num-1]=='S')
    {
        if(a[num-1]=='o'&&ans[num-2]!=ans[0])
            return false;
        else if(a[num-1]=='x'&&ans[num-2]==ans[0])
            return false;
    }
    if(ans[num-1]=='W')
    {
//        cout<<ans[num-2]<<ans[1]<<endl;
        if(a[num-1]=='x'&&ans[num-2]!=ans[0])
            return false;
        else if(a[num-1]=='o'&&ans[num-2]==ans[0])
            return false;
    }
    return true;
}
