	}
	ans[0] = 1;
	if (solve(1)) {
		result();
		return 0;
	}
	else {
		zero();
	}
	ans[0] = 1;
	if (solve(-1)) {
		result();
		return 0;
	}
	else {
		zero();
	}
	ans[0] = -1;
	if (solve(1)) {
		result();
		return 0;
	}
	else {
		zero();
	}
	ans[0] = -1;
	if (solve(-1)) {
		result();
		return 0;
	}
	else {
