	for(auto i = 0; i < 2 && flag == false; ++i) {
		result[0] = ini[i];
		for(auto j = 0; j < 2 && flag == false; ++j) {
			result[1] = ini[j];
			flag = judge(result, input);
		}
	}

	if(flag) {
		cout << result.substr(0, n) << endl;
	}
	else {
		cout << -1 << endl;
	}
}

