        if (a[0] != a[N-1]) {
            return false;
        }

        for (size_t i = 0; i < N; ++i) {
            bool same;
            if ((a[i] == 'S' && S[i] == 'o') ||
                (a[i] == 'W' && S[i] == 'x'))
            {
                same = true;
            }
            else {
                same = false;
            }

            if (same && a[(i+N-1)%N] != a[(i+1)%N]) {
                return false;
            }

            if (!same && a[(i+N-1)%N] == a[(i+1)%N]) {
                return false;
            }
        }

        return true;
    };

    auto a = f("SS");
    if (check(a)) {
        a.resize(N);
        std::cout << a << std::endl;
        return 0;
    }
