        return 0;
    }
    a = f("WS");
    if (check(a)) {
        a.resize(N);
        std::cout << a << std::endl;
        return 0;
    }
    a = f("WW");
    if (check(a)) {
        a.resize(N);
        std::cout << a << std::endl;
        return 0;
    }

    std::cout << "-1" << std::endl;

    return 0;
}

