bool solve(vector<pair<int,int> >&v){
    while(v.size() < s.size()){

        int prev = v[v.size()-2].second;
        if(s[v.back().first] == 'x' ){
                if(v.back().second == S)
                    v.push_back(make_pair((v.back().first+1)%s.size(),1-prev));
                else
                    v.push_back(make_pair((v.back().first+1)%s.size(),prev));
        }else{
             if(v.back().second == S)
                    v.push_back(make_pair((v.back().first+1)%s.size(),prev));
                else
                    v.push_back(make_pair((v.back().first+1)%s.size(),1-prev));
        }
    }

    vector<char>ans(v.size(),-1);
