bool traverse(bool a1, bool a2) {
  FORN(i, n) animals[i] = -1;

  int idx, left, right;
  // start from position 0
  idx = 0;
  left = n - 1;
  right = idx + 1;

  animals[idx] = a1;

  // a1 = wolf  = 1, answers = 1, left = a2, right = ~a2
  // a1 = wolf  = 1, answers = 0, left = right = a2
  // a1 = sheep = 0, answers = 1, left = right = a2
  // a1 = sheep = 0, answers = 0, left = a2, right = ~a2
  if (a1 ^ answers[idx]) {
    animals[left] = animals[right] = a2;
  } else {
    assert(a1 == answers[idx]);
    animals[left] = a2;
    animals[right] = !a2;
  }

  right++;

  while (right < n - 1) {
//    printf("  left[%d] %d, answer %d\n", right-2, animals[right-2], answers[right-2]);
//    printf("center[%d] %d, answer %d\n", right-1, animals[right-1], answers[right-1]);
//    printf(" right[%d] %d, answer %d\n", right, animals[right], answers[right]);
    if (animals[right-1] ^ answers[right-1]) {
      animals[right] = animals[right-2];
    } else {
      animals[right] = !animals[right-2];
    }
    right++;
  }

  bool ret = true;
//  pr();
  FORN(i, n) {
    if (i==0) {left = n-1; right = i + 1;}
    else if (i==n-1) {left = i-1; right = 0;}
    else {left = i-1; right = i+1;}
    if (animals[i] ^ answers[i]) {
      ret &= (animals[left] == animals[right]);
//      printf("comparing [%d]%d, [%d]%d\n", left, animals[left], right, animals[right]);
    } else {
      ret &= (animals[left] == !animals[right]);
//      printf("comparing [%d]%d, [%d]%d\n", left, animals[left], right, !animals[right]);
    }
  }
  return ret;

//  printf("checking predicted last[%d] %d with animals[%d]: %d\n", right, last, n-1, animals[n-1]);
//  if (last == animals[n-1]) return true;
//  else return false;

}

