bool check(int start) {
    a[start] = 0;
    int i = start;
    while (true) {
        int j = (i + 3) % n;
        if (b[(i + 1) % n] == b[(i + 2) % n])
            a[j] = a[i];
        else
            a[j] = 1 - a[i];

        if (j == start)
            break;
        i = j;
    }
    return a[start] == 0;
}

string get_str() {
    string t;
    bool rev = false;
    if ((a[0] + a[1] + a[2]) % 2 != b[1])
        rev = true;
    for (int i = 0; i < n; i++)
        t += (a[i] ^ rev) ? 'W' : 'S';
    return t;
}

