    cin >> n >> s;
    for (int i = 0; i < n; i++)
        b[i] = (s[i] == 'x' ? 1 : 0);

    if (n % 3 == 0) {
        if (check(0) && check(1) && check(2)) {
            cout << get_str() << endl;
        }
        else {
            cout << -1 << endl;
            return 0;
        }
    }
    else {
        if (check(0)) {
            cout << get_str() << endl;
        }
