int main() {
    int N;
    cin >> N;
    vector<char> S(N);
    rep(i, N) cin >> S[i];

    vector<char> animal = {'S', 'W'};
    vector<char> ans(N);
    rep(i, 4) {
        ans[0] = animal[i & (1 << 1)];
        ans[1] = animal[i & (1 << 2)];
        for (int j = 2; j < N; ++j) {
            if (ans[j - 1] == 'S') {
                if (S[j - 1] == 'o') ans[j] = ans[j - 2];
                else ans[j] = 'S' + 'W' - ans[j - 2];
            } else {
                if (S[j - 1] == 'o') ans[j] = 'S' + 'W' - ans[j - 2];
                else ans[j] = ans[j - 2];
            }
        }

        bool judge = true;
        if (ans[0] == 'S') {
            if (S[0] == 'o' && ans[1] != ans[N - 1]) judge = false;
            if (S[0] == 'x' && ans[1] == ans[N - 1]) judge = false;
        } else {
            if (S[0] == 'o' && ans[1] == ans[N - 1]) judge = false;
            if (S[0] == 'x' && ans[1] != ans[N - 1]) judge = false;
        }
        if (ans[N - 1] == 'S') {
            if (S[N - 1] == 'o' && ans[0] != ans[N - 2]) judge = false;
            if (S[N - 1] == 'x' && ans[0] == ans[N - 2]) judge = false;
        } else {
            if (S[N - 1] == 'o' && ans[0] == ans[N - 2]) judge = false;
            if (S[N - 1] == 'x' && ans[0] != ans[N - 2]) judge = false;
        }
        if (judge) {
            rep(i, N) cout << ans[i];
            cout << endl;
            return 0;
        }
    }
    cout << -1 << endl;
    return 0;
}

