using namespace std;

#define forn(i, n) for (int i = 0; i < int(n); ++i)
#define for1(i, n) for (int i = 1; i < int(n); ++i)

int n;
string s;

void turn(vector<char>& a, int i) {
	if (a[i - 1] == 'S')
		a[i + 1] = 'W';
	else
		a[i + 1] = 'S';
}

bool sim(vector<char>& a) {
	for1(i, n - 1) {
		if (a[i] == 'S') {
			if (s[i] == 'o')
				a[i + 1] = a[i - 1];
			else
				turn(a, i);
		}
		else {
			if (s[i] == 'x')
				a[i + 1] = a[i - 1];
			else
				turn(a, i);
		}
	}

	if (a.back() == 'S')
		if (s.back() == 'o' && a[0] != a[n - 2] || s.back() == 'x' && a[0] == a[n - 2])
			return false;

	if (a.back() == 'W')
		if (s.back() == 'x' && a[0] != a[n - 2] || s.back() == 'o' && a[0] == a[n - 2])
			return false;

	return true;
}

void print(vector<char>& a) {
	forn(i, n)
		cout << a[i];
	cout << endl;
}

int main() {
	cin >> n;

	cin >> s;

	vector<char> a(n);
	vector<char> b(n);
	vector<char> c(n);
	vector<char> d(n);
	a[0] = 'S', a[1] = 'S';
	b[0] = 'W', b[1] = 'W';
	c[0] = 'S', c[1] = 'W';
	d[0] = 'W', d[1] = 'S';

	if (sim(a)) {
		print(a);
		return 0;
	}

	if (sim(b)) {
		print(b);
		return 0;
	}

	if (sim(c)) {
		print(c);
		return 0;
	}

	if (sim(d)) {
		print(d);
		return 0;
	}

	cout << -1 << endl;
}

