bool zoo[100007];

bool solve(bool first, bool second)
{
    zoo[0] = first;
    zoo[1] = second;
    for (int i = 2; i < N; i++) {
        if (zoo[i - 1]) {
            if (s[i - 1] == 'o') {
                zoo[i] = zoo[i - 2];
            } else {
                zoo[i] = !zoo[i - 2];
            }
        } else {
            if (s[i - 1] == 'o') {
                zoo[i] = !zoo[i - 2];
            } else {
                zoo[i] = zoo[i - 2];
            }
        }
    }

    if (zoo[N - 1]) {
        if (s[N - 1] == 'o') {
            return zoo[N - 2] == zoo[0];
        } else {
            return zoo[N - 2] != zoo[0];
        }
    } else {
        if (s[N - 1] == 'o') {
            return zoo[N - 2] != zoo[0];
        } else {
            return zoo[N - 2] == zoo[0];
        }
    }
}

void display()
{
    for (int i = 0; i < N; i++) {
        cout << (zoo[i] ? 'S' : 'W');
    }
    cout << endl;
}

