      if(s[i] == 'o')t += t[i-1];
      else t += (t[i-1] == 'S' ? 'W' : 'S');
    }else{
      if(s[i] == 'o')t += (t[i-1] == 'S' ? 'W' : 'S');
      else t += t[i-1];
    }
  }
  return t;
}
bool check(string t,bool is){
  if(is){
    if(t[0] == 'S' && s[0] == 'o')return t[1] == t.back() ? true : false;
    else if(t[0] == 'S' && s[0] == 'x')return t[1] == t.back() ? false : true;
