		}
		else {
			if (s[i] == 'o')
				t[(i + 1) % n] = !t[i - 1];
			else
				t[(i + 1) % n] = t[i - 1];
		}
	}
	for (int i = 0; i < n; ++i) {
		int l = t[(i + n - 1) % n];
		int r = t[(i + 1) % n];
		if (t[i] == false) {
			if (s[i] == 'o' && l != r)
				return false;
			if (s[i] == 'x' && l == r)
