        vector<int> v(n, 0);
        v[0] = a; v[1] = b; v[2] = c;

        if (v[1] == 1) {
            if (s[1] == same && v[0] != v[2]) return false;
            else if (s[1] == diff && v[0] == v[2]) return false;
        } else {
            if (s[1] == same && v[0] == v[2]) return false;
            else if (s[1] == diff && v[0] != v[2]) return false;
        }

        for (int i = 2; i < n-1; i++) {
            if (v[i] == 1) {
                if (s[i] == same) v[i+1] = v[i-1];
                else v[i+1] = -v[i-1];
            } else {
                if (s[i] == same) v[i+1] = -v[i-1];
                else v[i+1] = v[i-1];
            }
        }
        if (v[n-1] == 1) {
            if (s[n-1] == same) return v[0] == v[n-2];
            else return v[0] != v[n-2];
        } else {
            if (s[n-1] == same) return v[0] != v[n-2];
            else return v[0] == v[n-2];
        }
    };

    string ans = "-1";
    auto make_ans = [&](int a, int b, int c)->string {
        vector<int> v(n, 0);
        v[0] = a; v[1] = b; v[2] = c;
        for (int i = 2; i < n-1; i++) {
            if (v[i] == 1) {
                if (s[i] == same) v[i+1] = v[i-1];
                else v[i+1] = -v[i-1];
            } else {
                if (s[i] == same) v[i+1] = -v[i-1];
                else v[i+1] = v[i-1];
            }
        }
        string ret = "";
        for (int i = 0; i < n; i++) {
            if (v[i] == 1) ret = ret + "S";
            else ret = ret + "W";
        }
        return ret;
    };

    for (int bit = 0; bit < (1<<3); bit++) {
        int m[3];
        for (int i = 0; i < 3; i++) {
            if (bit&(1<<i)) m[i] = 1;
            else m[i] = -1;
        }
        if (judge(m[0], m[1], m[2])) {
            ans = make_ans(m[0], m[1], m[2]);
            break;
        }
    }

    cout << ans << endl;
    return 0;
}

