        {
            if (getNext(ans.back(), ans.front(), s.front()) == ans.substr(1, 1))
            {
                cout << ans.substr(0, ans.size() - 1) << endl;
                flag = true;
                break;
            }
        }
    }

    if (!flag)
    {
        cout << -1 << endl;
    }
}

