	for(int i=1;i<n-1;i++)
	{
		if(a[i]=='o')
		{
			if(b[i]==1)
			{
				b[i+1]=b[i-1];
			}
			else
			    b[i+1]=-1*b[i-1];
		}
		else
		{
			if(b[i]==1)
			{
				b[i+1]=-1*b[i-1];
			}
			else
			    b[i+1]=b[i-1];
		}
	}
	if(a[0]=='o')
	{
		if(b[0]==1&&b[n-1]==b[1])
		return 1;
		if(b[0]==-1&&b[n-1]!=b[1])
		return 1;
	}
	else if(a[0]=='x')
	{
		if(b[0]==1&&b[n-1]!=b[1])
		return 1;
		if(b[0]==-1&&b[n-1]==b[1])
		return 1;
	}
	if(a[n-1]=='o')
	{
		if(b[n-1]==1&&b[n-2]==b[0])
		return 1;
		if(b[n-1]==-1&&b[n-2]!=b[0])
		return 1;
	}
	else  if(a[n-1]=='x')
	{
		if(b[n-1]==1&&b[n-2]!=b[0])
		return 1;
		if(b[n-1]==-1&&b[n-2]==b[0])
		return 1;
	}
	return 0;
}
