      (ani[0] == 0 && str[0] == 'x')){
        if(ani[n-1] == ani[1]) return true;
        else return false;
      }else{
        if(ani[n-1] == ani[1]) return false;
        else return true;
      }
    }
  }else{
    if(ani[n-2] == ani[0]) return false;
    else{
      if((ani[0] == 1 && str[0] == 'o') ||
