string assignment(int n, string s)
{
	if(s.length() != n || n < 3)
		return "-1";
	string str1 = "ox";
	string str2 = "xo";
	string ret = "";
	string s1;
	int num1, num2;
	num1 = s.find(str1);
	num2 = s.find(str2);
	if(num1 == -1 && num2 == -1) {
		if(s[0] == 'o')
			for(int i=0; i<n; i++) 
				ret = ret + "S";
		else
			for(int i=0; i<n; i++) 
				ret = ret + "W";
		return ret;
	}
	s1 = s.substr(num1, s.length()-num1) + s.substr(0, num1);
	//if(num1 >= 0) {
		ret = "SS";
		for(int i=1; i<n-1; i++) {
			if(ret[i] == 'S') {
				if(s1[i] == 'o')
					ret = ret + ret[i-1];
				else {
					char ch = ('W' ^ 'S') ^ ret[i-1] ;
					ret = ret + ch;
				}
			}
			else {
				if(s1[i] == 'o') {
					char ch = ('W' ^ 'S') ^ ret[i-1] ;
					ret = ret + ch;
				}
				else
					ret = ret + ret[i-1];
			}
		}
		if(s1[n-1] == 'o') {
			switch(ret[n-1]) {
			case 'S':
				if(ret[n-2] != ret[0])
					return "-1";
				break;
			default:
				if(ret[n-2] == ret[0])
					return "-1";
				break;
			}
		}
		else {
			switch(ret[n-1]) {
			case 'S':
				if(ret[n-2] == ret[0])
					return "-1";
				break;
			default:
				if(ret[n-2] != ret[0])
					return "-1";
				break;
			}
		}
		if(s1[0] == 'o') {
			switch(ret[0]) {
			case 'S':
				if(ret[1] != ret[n-1])
					return "-1";
				break;
			default:
				if(ret[n-1] == ret[0])
					return "-1";
				break;
			}
		}
		else {
			switch(ret[0]) {
			case 'S':
				if(ret[n-2] == ret[0])
					return "-1";
				break;
			default:
				if(ret[n-2] != ret[0])
					return "-1";
				break;
			}
		}
		s1 = ret.substr(ret.length()-num1, num1) + ret.substr(0, ret.length()-num1);
		return s1;
}

