inline void solve(){
	int N;
	string str;
	cin >> N >> str;
	vector< bool > ans(N+1);//false:x true:o
	vector< bool > ani(N+1,true);//false:w true:s
	vector< int > chan(N+1,0);
	for(int i=0;i<N;++i){
		if( str[i] == 'o'){
			ans[i] = true;
		}else{
			ans[i] = false;
		}
	}
	ans[N] = ans[0];

	int pos = 0;
	int L,R;
	int loop = 0;
	int Count = 0;
	bool flag = true;
	while( loop<N ){
		loop++;
		Count++;
		L = (pos+N-1)%N;
		R = (pos+1)%N;
		if( ani[pos] == true){//s
			if( ans[pos] == true ){
				if( ani[L] != ani[R] ){
					ani[R] = ani[L];
					loop = 0;
					chan[R]++;
					if( chan[R] >= 3 ){
						flag = false;
						break;
					}
				}
			}else{//false
				if( ani[L] == ani[R] ){
					ani[R] = !ani[L];
					loop = 0;
					chan[R]++;
					if( chan[R] >= 3 ){
						flag = false;
						break;
					}
				}
			}
		}else{//w
			if( ans[pos] == false ){
				if( ani[L] != ani[R] ){
					ani[R] = ani[L];
					loop = 0;
					chan[R]++;
					if( chan[R] >= 3 ){
						flag = false;
						break;
					}
				}
			}else{//false
				if( ani[L] == ani[R] ){
					ani[R] = !ani[L];
					loop = 0;
					chan[R]++;
					if( chan[R] >= 3 ){
						flag = false;
						break;
					}
				}
			}
		}
		//ani[0] = ani[N];
		pos = (pos+1)%N;
	}
	if( flag == false ){
		cout << -1 << endl;
		return;
	}
	if( loop == N ){
		for(int i=0;i<N;++i){
			if( ani[i] ){
				cout << "S";
			}else{
				cout << "W";
			}
		}cout << endl;
	}else{
		cout << -1 << endl;
	}
}

