			if (c == 'S')
			{
				if (S[i] == 'o')
					res[i+1] = res[i-1];
				else
				{
					if (res[i-1] == 'S')
						res[i+1] = 'W';
					else
						res[i+1] = 'S';
				}
			}
			else // wolf
