				if (S[i] == 'x')
					res[i+1] = res[i-1];
				else
				{
					if (res[i-1] == 'S')
						res[i+1] = 'W';
					else
						res[i+1] = 'S';
				}
			}
		}

		char c = res[N-1];
		if (c == 'S')
		{
			if (S[N-1] == 'o')
			{
				if (res[N-2] == res[0])
				{
					is = true;
				}
			}
			else
			{
				if (res[N-2] != res[0])
				{
					is = true;
				}
			}
		}
		else // wolf
		{
			if (S[N-1] == 'o')
			{
				if (res[N-2] != res[0])
				{
					is = true;
				}
			}
			else
			{
				if (res[N-2] == res[0])
				{
					is = true;
				}
			}
		}

		if (!is) continue;
		c = res[0];
		if (c == 'S')
		{
			if (S[0] == 'o')
			{
				if (res[N-1] == res[1])
				{
					goto exit;
				}
			}
			else
			{
				if (res[N-1] != res[1])
				{
					goto exit;
				}
			}
		}
		else // wolf
		{
			if (S[0] == 'o')
			{
				if (res[N-1] != res[1])
				{
					goto exit;
				}
			}
			else
			{
				if (res[N-1] == res[1])
				{
					goto exit;
				}
			}
		}

	}

 exit:

	if (is)
		std::cout << res << std::endl;
	else
		std::cout << -1 << std::endl;
}

