            cout << 'S';
        }
        else
        {
            cout << 'W';
        }
    }
    cout << endl;
    return;
}

signed main()
{
    int n;
    string s;
    cin >> n >> s;

    for (int j = 0; j < 4; j++)
    {
        vector<int> u(n,0);
        u[0] = j % 2;
        u[1] = j / 2;

        for (int i = 1; i < n; i++)
        {
            if ((s.at(i) == 'o' && u[i] == 0) || (s[i] == 'x' && u[i] == 1))
            {
                if(i==n-1 && u[0]!=u[n-2]){
                    cout<<-1<<endl;
                    return 0;
                }
                u.at((i+1)%n) = u[i - 1];
            }
            else
            {
                if(i==n-1 && u[0]!=1-u[n-2]){
                    cout<<-1<<endl;
                    return 0;
                }
                u.at((i+1)%n) = (1 - u[i - 1]);
            }
        }

        if(u[1]==u[n-1] && ((s[0]=='o'&&u[0]==0) || (s[0]=='x'&&u[0]==1))){
            solve(u);
            return 0;
        }else if(u[1]!=u[n-1]){
            solve(u);
            return 0;
        }
    }

    cout << -1 << endl;
}

