bool CheckOK(int N, const string& S, const vector<int>& v)
{
    auto vv = [&](int i)
    {
        while (i < 0) i += N;
        while (i >= N) i -= N;
        return v[i];
    };

    rep(i, 0, N)
    {
        if (v[i] == 0)
        {
            if (S[i] == 'o')
            {
                if (vv(i - 1) != vv(i + 1)) return false;
            }
            else
            {
                if (vv(i - 1) == vv(i + 1)) return false;
            }
        }
        else
        {
            if (S[i] == 'o')
            {
                if (vv(i - 1) == vv(i + 1)) return false;
            }
            else
            {
                if (vv(i - 1) != vv(i + 1)) return false;
            }
        }
    }
    return true;
}

