using namespace std;

char *search(char a, char b, char *s, int N) {
  char *ans = (char *)malloc(N + 1);
  ans[0] = a;
  ans[1] = b;
  for (int i = 0; i < N - 1; i++) {
    if (s[i + 1] == 'o' && ans[i + 1] == 'S') {
      ans[i + 2] = ans[i];
    } else if (s[i + 1] == 'x' && ans[i + 1] == 'W') {
      ans[i + 2] = ans[i];
    } else {
      if (ans[i] == 'S') {
        ans[i + 2] = 'W';
      } else {
        ans[i + 2] = 'S';
      }
    }
  }
  if (ans[0] == ans[N]) {
    ans[N] = '\0';
    return ans;
  } else {
    return NULL;
  }
  free(ans);
}

int main() {
  int N;
  char *s = (char *)malloc(N + 1);
  cin >> N >> s;

  char *epoch0 = search('S', 'S', s, N);
  char *epoch1 = search('S', 'W', s, N);
  char *epoch2 = search('W', 'S', s, N);
  char *epoch3 = search('W', 'W', s, N);

  if (search('S', 'S', s, N) != NULL) {
    cout << epoch0 << endl;
  } else if (epoch1 != NULL) {
    cout << epoch1 << endl;
  } else if (epoch2 != NULL) {
    cout << epoch1 << endl;
  } else if (epoch3 != NULL) {
    cout << epoch3 << endl;
  } else {
    cout << -1 << endl;
  }

  return 0;
}

