inline bool is_correct(int n, int idx, const bool* tolds, const bool* is_sheep) {
    // idx番目の動物の発言が矛盾するかチェック
    int left = (idx == 0) ? n-1 : idx-1;
    int right = (idx == n-1) ? 0 : idx+1;

    // if (is_sheep[idx] && tolds[idx]) {
    //     return (is_sheep[left] == is_sheep[right]);
    // }

    // if (is_sheep[idx] && !tolds[idx]) {
    //     return (is_sheep[left] != is_sheep[right]);
    // }

    // if (!is_sheep[idx] && tolds[idx]) {
    //     return (is_sheep[left] != is_sheep[right]);
    // }

    // if (!is_sheep[idx] && !tolds[idx]) {
    //     return (is_sheep[left] == is_sheep[right]);
    // }

    return (is_sheep[left] == is_sheep[right]) ^ is_sheep[idx] ^ tolds[idx];
}

void eval(int n, const bool* tolds) {
    bool* is_sheep = new bool[n];
    std::memset(is_sheep, 0, n);

    std::stack<int> stack;
    stack.push(0);
    stack.push(1);

    while (stack.size()) {
        int val = stack.top();
        int idx = val >> 1;
        bool sheep = val&1;
        stack.pop();

        // std::cout << "idx: " << idx << ", sheep: " << sheep << std::endl;

        is_sheep[idx] = sheep;

        // 終了判定
        if (idx == n-1) {
            if (is_correct(n, n-1, tolds, is_sheep) && is_correct(n, 0, tolds, is_sheep)) {
                display(n, is_sheep);
                return;
            }
            continue;
        }

        // 羊としてテスト
        is_sheep[idx+1] = false;
        if (idx < 2 || is_correct(n, idx-1, tolds, is_sheep)) {
            stack.push(((idx+1) << 1) | 1);
        }

        // 狼としてテスト
        is_sheep[idx+1] = false;
        if (idx < 2 || is_correct(n, idx-1, tolds, is_sheep)) {
            stack.push((idx+1) << 1);
        }
    }

    std::cout << "-1" << std::endl;
}

