struct Solver {
  long n;
  std::string xs;
  Solver() {
    S002 reader;
    reader >= n >= xs;
  }
  void solve() {
    std::string ys(n, ' ');
    for(char c0 : {'S', 'W'}) {
      for(char c1 : {'S', 'W'}) {
        ys[0] = c0, ys[1] = c1;
        for(long i = 2; i < n; ++i) {
          if( ( xs[i-1] == 'o' and ys[i-1] == 'S' ) or
              ( xs[i-1] == 'x' and ys[i-1] == 'W' )    ) {
            ys[i] = ys[i-2];
          }
          else {
            ys[i] = 'S' + 'W' - ys[i-2];
          }
        }
        bool res = true;
        if( ys[n-1] == 'S' and xs[n-1] == 'o' and ys[n-2] != ys[0] ) res = false;
        if( ys[n-1] == 'S' and xs[n-1] == 'x' and ys[n-2] == ys[0] ) res = false;
        if( ys[n-1] == 'W' and xs[n-1] == 'o' and ys[n-2] == ys[0] ) res = false;
        if( ys[n-1] == 'W' and xs[n-1] == 'x' and ys[n-2] != ys[0] ) res = false;
        if( ys[0] == 'S' and xs[0] == 'o' and ys[n-1] != ys[1] ) res = false;
        if( ys[0] == 'S' and xs[0] == 'x' and ys[n-1] == ys[1] ) res = false;
        if( ys[0] == 'W' and xs[0] == 'o' and ys[n-1] == ys[1] ) res = false;
        if( ys[0] == 'W' and xs[0] == 'x' and ys[n-1] != ys[1] ) res = false;
        if( res ) {
          printf("%s\n", ys.c_str());
          return;
        }
      }
    }
    puts("-1");
  }
  ~Solver() { fprintf(stderr, "--end--\n"); }
};

int main() {
  loop std::unique_ptr<Solver>(new Solver())->solve();
  return 0;
}

