void result() {
	for (int j = 0; j < N; j++) {
		if (ans[j] == 1) {
			std::cout << "S";
		}
		else if(ans[j]==-1){
			std::cout << "W";
		}
	}
	std::cout << std::endl;
}
bool solve(int one) {
	ans[i] = one;
	if (i == N-1) {
		if (ans[0] == 1) {
			if (s[0] == 'o') {
				i = 1;
				return ans[1] == ans[N];

			}
			else {
				i = 1;
				return ans[1] != ans[N];
			}
		}
		else if(ans[i]==-1){
			if (s[0] == 'o') {
				i = 1;
				return ans[1] != ans[N];
			}
			else {
				i = 1;
				return ans[1] == ans[N];
			}
		}
	}
	if (one == 1) {
		if (s[i] == 'o') {
			ans[i + 1] = ans[i - 1];
			i++;
			solve(ans[i]);
		}
		else {
			ans[i + 1] = -ans[i - 1];
			i++;
			solve(ans[i]);
		}
	}
	else if(one==-1){
		if (s[i] == 'o') {
			ans[i + 1] = -ans[i - 1];
			i++;
			solve(ans[i]);
		}
		else {
			ans[i + 1] = ans[i - 1];
			i++;
			solve(ans[i]);
		}
	}
}
void zero() {
	for (int q = 0; q < N; q++) {
		ans[q] = 0;
	}
}
