	std::cin >> N;
	for (int j = 0; j < N; j++) {
		std::cin >> s[j];
	}
	ans[0] = 1;
	if (solve(1)) {
		result();
		return 0;
	}
	else {
		zero();
	}
	ans[0] = 1;
	if (solve(-1)) {
		result();
		return 0;
	}
	else {
		zero();
	}
	ans[0] = -1;
	if (solve(1)) {
		result();
		return 0;
	}
	else {
		zero();
	}
	ans[0] = -1;
	if (solve(-1)) {
		result();
		return 0;
	}
	else {
		zero();
	}
	std::cout << -1 << std::endl;
	return 0;
}

