vector<pair<char, int>> run_length_compress(string S)
{
    vector<pair<char, int>> res;
    int n = S.size(), cnt = 1;
    for (int i = 0; i < n - 1; i++)
    {
        if (S[i] == S[i + 1])
        {
            cnt++;
        }
        else
        {
            res.push_back({S[i], cnt});
            cnt = 1;
        }
    }
    res.push_back({S.back(), cnt});
    return res;
}
