                ans[(i + 1) % N] = ans[i - 1];
            }
            else
            {
                ans[(i + 1) % N] = x xor ans[i - 1];
            }
        }
    }
    for (size_t i = 0; i < N; i++)
    {
        if (i == N - 1)
        {
            if (s[i] == 'o' and (ans[i] == 'S' and ans[i - 1] != ans[0]) or (ans[i] == 'W' and ans[i - 1] == ans[0]))
            {
