bool dfs(int x) {
  int prev, next;
  if (x == 0) {
    prev = n-1;
    next = 1;
  } else if (x == n-1) {
    prev = n-2;
    next = 0;
  } else {
    prev = x-1;
    next = x+1;
  }

  bool same;
  if (anim[x] == 1 && s[x] == 'o') {
    same = true;
  } else if (anim[x] == -1 && s[x] == 'x') {
    same = true;
  } else {
    same = false;
  }

  if (same) {
    if (anim[prev] && anim[next] && (anim[prev] != anim[next])) {
      return false;
    } else if (anim[prev] && anim[next]) {
      return true;
    } else if (anim[prev]) {
      anim[next] = anim[prev];
      return dfs(next);
    } else {
      anim[prev] = anim[next];
      return dfs(prev);
    }
  } else {
    if (anim[prev] && anim[next] && (anim[prev] == anim[next])) {
      return false;
    } else if (anim[prev] && anim[next]) {
      return true;
    } else if (anim[prev]) {
      anim[next] = -anim[prev];
      return dfs(next);
    } else {
      anim[prev] = -anim[next];
      return dfs(prev);
    }
  }
}

