using namespace std;

int n;
string s;

char inv(char c) {
  return (c == 'S') ? 'W' : 'S';
}

bool solve(string& t, char fir, char sec) {
  t[0] = fir; t[1] = sec;
  for (int i = 1; i < n; i++) {
    if (s[i] == 'o') {
      if (t[i] == 'S') t[i + 1] = t[i - 1];
      else t[i + 1] = inv(t[i - 1]);
    } else {
      if (t[i] == 'S') t[i + 1] = inv(t[i - 1]);
      else t[i + 1] = t[i - 1];
    }
  }

  if (t[0] != t[n]) return false;

  if (s[0] == 'o') {
    if (t[0] == 'S') return t[n - 1] == t[1];
    else return t[n - 1] != t[1];
  } else {
    if (t[0] == 'S') return t[n - 1] != t[1];
    else return t[n - 1] == t[1];
  }
}

int main(void) {
  cin >> n >> s;

  string ans = "-1", cs = s + s[0];
  char c[2] = {'S', 'W'};
  for (int i = 0; i < 2; i++) {
    for (int j = 0; j < 2; j++) {
      if (solve(cs, c[i], c[j])) {
        ans = cs.substr(0, n);
      }
    }
  }

  cout << ans << endl;

  return 0;
}

