  is_sheep[0] = s1;
  is_sheep[1] = s2;
  for (int i=1; i<n-1; i++) {
    if (is_sheep[i]) {
      if (s[i] == 'o') {
        is_sheep[i+1] = is_sheep[i-1];
      } else {
        is_sheep[i+1] = !is_sheep[i-1];
      }
    } else {
      if (s[i] == 'o') {
        is_sheep[i+1] = !is_sheep[i-1];
      } else {
        is_sheep[i+1] = is_sheep[i-1];
      }
    }
  }
  if (is_sheep[n-1]) {
    if (s[n-1] == 'o' ^ is_sheep[0] == is_sheep[n-2]) {
      return false;
    }
  } else {
    if (s[n-1] == 'x' ^ is_sheep[0] == is_sheep[n-2]) {
      return false;
    }
  }
  if (is_sheep[0]) {
    return s[0] == 'o' ^ is_sheep[n-1] != is_sheep[1];
  } else {
    return s[0] == 'x' ^ is_sheep[n-1] != is_sheep[1];
  }
}
