						if(check(ans[l - 1], ans[l], 0) == s[l]) ans[l + 1] = 0;
						else ans[l + 1] = 1;
					}
					if(check(ans[N - 2], ans[N - 1], ans[0]) == s[N - 1] &&
					   check(ans[N - 1], ans[0], ans[1]) == s[0]) {
						for(int l = 0; l < N; l++) {
							if(ans[l] == 0) cout << 'S';
							else cout << 'W';
						}
						cout << endl;
						return 0;
					}
				}

			}
		}
	}
	cout << -1 << endl;
}

