char reverse(char c) {
  if(c == 'S')
    return 'W';
  else
    return 'S';
}



bool possible(int N, string S, char first, char second, char* s) {
  s[0] = first;
  s[1] = second;
  for(int i = 1; i < N - 1; i++) {
    bool same = false;
    if(s[i] == 'S' && S[i] == 'o') 
      same = true;

    if(s[i] == 'W' && S[i] == 'x')
      same = true;

    if(same)
      s[i + 1] = s[i - 1];
    else
      s[i + 1] = reverse(s[i - 1]);
  }

  bool same = false;

  if(s[N - 1] == 'S' && S[N - 1] == 'o')  same = true;
  if(s[N - 1] == 'W' && S[N - 1] == 'x')  same = true;

  if(same) {
    if(s[0] == s[N - 2])
      return true;
    else
      return false;
  }else {
    if(s[0] == s[N - 2])
      return false;
    else
      return true;
  }
}

int main() {
  int N;
  string S;
  cin >> N >> S;

  char ans[N];
  if(possible(N, S, 'S', 'S', ans))
    cout << ans << endl;
  else if(possible(N, S, 'S', 'W', ans))
    cout << ans << endl;
  else if(possible(N, S, 'W', 'S', ans))
    cout << ans << endl;
  else if(possible(N, S, 'W', 'W', ans))
    cout << ans << endl;
  else
    cout << -1 << endl;


}

