                buf[i+1] = buf[i-1];
            }
        }
        i++;
    }
}

int check(int N, int* buf, char* str) {
    int res = 0;

    if(buf[N-1] == 0) {
        if(str[N-1] == 'o') {
            res = (buf[N-2] == buf[0]);
        } else {
            res = (buf[N-2] != buf[0]);
        }
    } else {
        if(str[N-1] != 'o') {
            res = (buf[N-2] == buf[0]);
        } else {
            res = (buf[N-2] != buf[0]);
        }
    }

    if(res == 0) return 0;

    if(buf[0] == 0) {
        if(str[0] == 'o') {
            res = (buf[N-1] == buf[1]);
        } else {
            res = (buf[N-1] != buf[1]);
        }
    } else {
        if(str[0] != 'o') {
            res = (buf[N-1] == buf[1]);
        } else {
            res = (buf[N-1] != buf[1]);
        }
    }

    return res;
}



void printAnimal(int N, int* buf) {
    for(int i=0;i<N;i++) {
        if(buf[i]) {
            printf("W");
        } else {
            printf("S");
        }
    }
    printf("\n");
}


