string make_str(vector<int> &v) {
	int n = v.size() - 1;
	string s(n, '?');
	for (int i = 0; i < n; i++) {
		s[i] = v[i] == 0 ? 'S' : 'W';
	}
	return s;
}

int main() {
	int n;
	string s;
	cin >> n >> s;

	for (int i = 0; i < 4; i++) {
		vector<int> animal(n + 1, -1);
		switch (i) {
			case 0: animal[0] = 0; animal[1] = 0; break;
			case 1: animal[0] = 0; animal[1] = 1; break;
			case 2: animal[0] = 1; animal[1] = 0; break;
			case 3: animal[0] = 1; animal[1] = 1; break;
			default: break;
		}

		for (int i = 1; i < n; i++) {
