            ans += ans[i - 1];
        }
        else if ((s[i % N] == 'o' && ans[i] == 'W') || (s[i % N] == 'x' && ans[i] == 'S'))
        {
            ans += ans[i - 1] == 'S' ? 'W' : 'S';
        }
    }

    if(s12 == ans.substr(N, 2))
    {
        return ans.substr(0, N);
    }
    else
