	FOR(i, 1, s.size()) {
		if (state[i] == 'S') {
			if (s[i] == 'o') {
				state = state + state[state.size() - 2];
			}
			else {
				if (state[state.size() - 2] == 'W') {
					state = state + 'S';
				}
				else {
