char neg(char x) {
  if (x == 'S') return 'W';
  else return 'S';
}

string construct(const int n, const string &s, const char fir, const char sec) {
  string ret;
  ret += fir;
  ret += sec;

  rep(i, 1, n-1) {
    bool sheep = ret[i] == 'S';

    if (s[i] == 'o') {
      if (sheep) ret += ret[i-1];
      else       ret += neg(ret[i-1]);
    }
    else {
      if (sheep) ret += neg(ret[i-1]);
      else       ret += ret[i-1];
    }
  }
  return ret;
};

bool check(int i, const string &cand, const string &s) {
  int n = sz(s);
  int nex = (i + 1) % n;
  int pre = (i - 1 + n) % n;

  bool sheep = cand[i] == 'S';
  bool ans = s[i] == 'o';

  if (sheep) {
    if (ans) return cand[nex] == cand[pre];
    else return cand[nex] != cand[pre];
  }
  else {
    if (ans) return cand[nex] != cand[pre];
    else return cand[nex] == cand[pre];
  }
}

bool checkall(const string &cand, const string &s) {
  int n = sz(s);
  rep(i, n) {
    if (!check(i, cand, s)) return false;
  }
  return true;
}

string solve() {
  int n = read<int>();
  string s = read<decltype(s)>();

  {
    string a = construct(n, s, 'S', 'S');
    if (checkall(a, s)) return a;
  }

  {
    string a = construct(n, s, 'S', 'W');
    if (checkall(a, s)) return a;
  }

  {
    string a = construct(n, s, 'W', 'S');
    if (checkall(a, s)) return a;
  }

  {
    string a = construct(n, s, 'W', 'W');
    if (checkall(a, s)) return a;
  }

  return "-1";
}
void Main() {
  cout << solve() << endl;
}
