}

string assignment(int n, string s) 
{
	if(n != s.size())
		return "-1";
	string ss;
	ss = "SS";
	translate(n, s, ss);
	if(isvalid(n, s, ss))
		return ss;
	ss = "SW";
	translate(n, s, ss);
	if(isvalid(n, s, ss))
		return ss;
	ss = "WS";
	translate(n, s, ss);
	if(isvalid(n, s, ss))
		return ss;
	ss = "WW";
	translate(n, s, ss);
	if(isvalid(n, s, ss))
		return ss;
	return "-1";
}

void translate(int n, string s, string& ss)
{
	for(int i=1; i<n-1; i++) {
		if(ss[i] == 'S') {
			if(s[i] == 'o')
				ss = ss + ss[i-1];
			else {
				char ch = 'W' ^ 'S' ^ ss[i-1];
				ss = ss + ch;
			}
		}
		else {
			if(s[i] == 'o') {
				char ch = 'W' ^ 'S' ^ ss[i-1];
				ss = ss + ch;
			}
			else
				ss = ss + ss[i-1];
		}
	}
}

bool isvalid(int n, string s, string ss)
{
	switch(s[0]) {
	case 'o':
		if(ss[0] == 'S') {
			if(ss[1] != ss[n-1])
				return false;
		}
		else {
			if(ss[1] == ss[n-1])
				return false;
		}
		break;
	case 'x':
		if(ss[0] == 'S') {
			if(ss[1] == ss[n-1])
				return false;
		}
		else {
			if(ss[1] != ss[n-1])
				return false;
		}
		break;
	default:
		return false;
		break;
	}
	switch(s[n-1]) {
	case 'o':
		if(ss[n-1] == 'S') {
			if(ss[0] != ss[n-2])
				return false;
		}
		else {
			if(ss[0] == ss[n-2])
				return false;
		}
		break;
	case 'x':
		if(ss[n-1] == 'S') {
			if(ss[0] == ss[n-2])
				return false;
		}
		else {
			if(ss[0] != ss[n-2])
				return false;
		}
		break;
	default:
		return false;
		break;
	}
	return true;
}

