using namespace std;

int n;
string s;

void solve(int first, int second) {
    vector<int> ans(n);
    ans[0] = first;
    ans[1] = second;
    for (int i = 1; i < n - 1; ++i) {
        if (ans[i] ^ (s[i] == 'x')) {
            ans[i + 1] = ans[i - 1];
        } else {
            ans[i + 1] = ans[i - 1] ^ 1;
        }
    }
    if (ans[n - 1] ^ (s[n - 1] == 'x')) {
        if (ans[0] != ans[n - 2]) return;
    } else {
        if (ans[0] == ans[n - 2]) return;
    }
    if (ans[0] ^ (s[0] == 'x')) {
        if (ans[n - 1] != ans[1]) return;
    } else {
        if (ans[n - 1] == ans[1]) return;
    }
    for (int i = 0; i < n; ++i) {
        if (ans[i]) cout << 'S';
        else cout << 'W';
    }
    exit(0);
}

signed main() {
    ios_base::sync_with_stdio(false); cin.tie(0);

    cin >> n >> s;
    for (int i = 0; i < 2; ++i) {
        for (int j = 0; j < 2; ++j) {
            solve(i, j);
        }
    }
    cout << "-1\n";
}

