	string y;
	cin >> y;
	int x[N+5];
	for(int i=0;i<(1<<3);i++){
		if(1 & i) x[N] = 0;
		else x[N] = 1;
		if(2 & i) x[1] = 0;
		else x[1] = 1;
		if(4 & i) x[2] = 0;
		else x[2] = 1;
		if(x[1] == 1){ // 1 harus sama 
			if(y[0] == 'o'){
				if(x[N] != x[2]) {
					continue;
				//	break;
				}
			}
			else{
				if(x[N] == x[2]) {
					continue;
				}
			}
		}
		else{
			if(y[0] == 'o')
			if(x[N] == x[2]){ // 0 harus beda
			//	break;
				continue;
			}
			else{
				if(x[N] != x[2]) continue;
			}
		}
		bool ok = 0;
		for(int j=2;j<=N;j++){
			int a;
			if(y[j-1] == 'o'){
				if(x[j] == 0){
					a = x[j-1] ^ 1;
				}
				else{
					a = x[j-1];
				}
			}
			else{
				if(x[j] == 1){
					a = x[j-1] ^ 1;
				}
				else{
					a = x[j-1];
				}	
			}
			if(j == N-1){
				if(a != x[N]){
					ok = 1;
					break;
				}
			}
			if(j == N){
				if(a != x[1]){
					ok = 1;
					break;
				}
			}
			x[j+1] = a;
		}
		if(!ok){
			for(int j=1;j<=N;j++){
