char rev(char a) {
  if (a == 'S') {
    return 'W';
  }
  return 'S';
}

int main(int argc, char* argv[])
{
  ll N;
  std::cin >> N;

  std::string s;
  std::string::iterator it;
  std::cin >> s;

  char a0[4] = { 'S', 'S', 'W', 'W' };
  char a1[4] = { 'S', 'W', 'S', 'W' };
  std::string sa(N, 'X');
  bool is_ok = false;

  for (int a = 0; a < 4; a++) {
    char first_animal;
    char last_animal;

    fill(sa.begin(), sa.end(), 'X');
    sa[0] = a0[a];
    sa[1] = a1[a];

    if ((s[0] ==  'o' && sa[0] == 'S') || (s[0] == 'x' && sa[0] == 'W')) {
      last_animal = sa[1];
    } else {
      last_animal = rev(sa[1]);
    }

    if ((s[N-1] ==  'o' && last_animal == 'S') || (s[N-1] == 'x' && last_animal == 'W')) {
      first_animal = sa[N-2];
    } else {
      first_animal = rev(sa[N-2]);
    }

    for (ll i = 1; i < N-1; i++) {
      if ((s[i] ==  'o' && sa[i] == 'S') || (s[i] == 'x' && sa[i] == 'W')) {
	sa[i+1] = sa[i-1];
      } else {
	sa[i+1] = rev(sa[i-1]);
      }
    }

    if (sa[N-1] == last_animal && sa[0] == first_animal) {
      is_ok = true;
      break;
    }
  }

  if (is_ok) {
    std::cout << sa << std::endl;
  } else {
    std::cout << -1 << std::endl;
  }

  return 0;
}

