                    return !(assignar[i-1] ^ assignar[1]);
                }
            }else{
                return false;
            }
        }else{
            if(!(assignar[i-2] ^ assignar[0])){
                bool v = (s[0] == 'o');
                if(v ^ assignar[0]){
