string getNext(char before, char current, char say)
{
    string ret[2] = {"S", "W"};
    int index = say == 'o' ? 0 : 1;
    index = (index + (before == 'S' ? 0 : 1)) % 2;
    index = (index + (current == 'S' ? 0 : 1)) % 2;

    return ret[index];
}

int main()
{
    int N;
    string s;
    bool flag = false;

    cin >> N >> s;
    string start = "SSWWS";

    for (int i = 0; i < 4; i++)
    {
        string ans = start.substr(i,2);
        for (int j = 1; j < N; j++)
        {
            ans = ans + getNext(ans[j-1], ans[j], s[j]);
        }
        if (ans.front() == ans.back())
        {
            cout << ans.substr(0, ans.size() - 1) << endl;
            flag = true;
            break;
        }
    }

    if (!flag)
    {
        cout << -1 << endl;
    }
}

