using namespace std;

char s[100005];

int a[100005], n;

inline bool ok(int p) {
    int l = (p + n - 1) % n;
    int r = (p + 1) % n;
    if(a[p]) {
        if(s[p] == 'o')
            return a[l] != a[r];
        else
            return a[l] == a[r];
    } else {
        if(s[p] == 'o')
            return a[l] == a[r];
        else
            return a[l] != a[r];
    }
}

bool check() {
    for(int i = 2; i < n; ++ i) {
        if(a[i - 1]) {
            if(s[i - 1] == 'o')
                a[i] = a[i - 2] ^ 1;
            else
                a[i] = a[i - 2];
        } else {
            if(s[i - 1] == 'o')
                a[i] = a[i - 2];
            else
                a[i] = a[i - 2] ^ 1;
        }
    }
    return ok(0) && ok(n - 1);
}

void output() {
    for(int i = 0; i < n; ++ i)
        putchar(a[i] ? 'W' : 'S');
    exit(0);
}

int main() {
    scanf("%d%s", &n, s);
    for(a[0] = 0; a[0] < 2; ++ a[0]) {
        for(a[1] = 0; a[1] < 2; ++ a[1]) {
            if(check())
                output();
        }
    }
    puts("-1");
    return 0;
}

