rep(i,1<<3){
    if((i&1)^((i>>1)&1)^((i>>2)&1)!=table[1])continue;
    ans[0]=i&1;
    ans[1]=(i>>1)&1;
    ans[2]=(i>>2)&1;
    rep2(i,3,N){
        ans[i]=ans[i-3]^table[i-1]^table[i-2];
    }
    if((ans[N-2]^ans[N-1]^ans[0]==table[N-1])&&(ans[N-1]^ans[0]^ans[1]==table[0])){judge=true;break;}

}
