bool judge(char a,char b,char c,int p){
	if(a=='S'){
		if(str[p]=='o'){
			if(b==c)return true;
		}else{
			if(b!=c)return true;
		}
	}
	if(a=='W'){
		if(str[p]=='o'){
			if(b!=c)return true;
		}else{
			if(b==c)return true;
		}
	}
	return false;
}
int main(int argc, char** argv) {
	cin>>n>>str;int flag=0;
	for(int i=0;i<4;i++){
		char ans[N];
