		for(int j=2;j<n;j++){
			if(ans[j-1]=='S'){
				if(str[j-1]=='o'){
					if(ans[j-2]=='S')ans[j]='S';
					else ans[j]='W';
				}else{
					if(ans[j-2]=='S')ans[j]='W';
					else ans[j]='S';
