// 0 S truth
// 1 W lie

void solve(bool a, bool b) {
	ans[0] = a;
	ans[1] = b;

	FOR(i, 1, n) {
		if (ans[i] == 0) {
			if (s[i] == 'o') ans[i + 1] = ans[i - 1];
			if (s[i] == 'x') ans[i + 1] = 1 - ans[i - 1];
		}
		if (ans[i] == 1) {
			if (s[i] == 'x') ans[i + 1] = ans[i - 1];
			if (s[i] == 'o') ans[i + 1] = 1 - ans[i - 1];
		}
	}

	if (ans[n] == ans[0]) {
		FOR(i, 0, n) printf("%c", ans[i] ? 'W' : 'S');
		printf("\n");
		exit(0);
	}
}

int main () {

