                if(ans[(i-1+N)%N]==ans[(i+1)%N])return false;
            }
        }else{
            if(ans[i]=='S'){
                if(ans[(i-1+N)%N]==ans[(i+1)%N])return false;
            }else{
                if(ans[(i-1+N)%N]!=ans[(i+1)%N])return false;
            }
        }
    }
