    ios::sync_with_stdio(false);
    cin.tie(0);
    int n;
    string s;
    cin >> n >> s;
    solve(n, s, 0, 0);
    solve(n, s, 0, 1);
    solve(n, s, 1, 0);
    solve(n, s, 1, 1);
    cout << "-1\n";
}

