{
    for (int i = 2; i < s.size() * 2; i++)
    {
        if (S[i - 1])
        {
            if (s[i - 1] == 'o')
            {
                S[i] = S[i - 2];
            }
            else
            {
                S[i] = !S[i - 2];
            }
        }
        else
        {
            if (s[i - 1] == 'o')
            {
                S[i] = !S[i - 2];
            }
            else
            {
                S[i] = S[i - 2];
            }
        }
    }
    return S;
}

bool correct(string s, vector<bool> S, ll N)
{
    if (S[0] != S[N])
        return false;
    if (S[0])
    {
        if ((s[0] == 'o' && S[1] == S[N - 1]) || (s[0] == 'x' && S[1] != S[N - 1]))
        {
            return true;
        }
    }
    else
    {
        if ((s[0] == 'o' && S[1] != S[N - 1]) || (s[0] == 'x' && S[1] == S[N - 1]))
        {
            return false;
        }
    }
    return false;
}
vector<bool> solve(long long N, std::string s)
{
    vector<bool> S(2 * N, false);
    S[0] = true;
    S[1] = true;
    S = check(s, S);

    if (correct(s, S, N))
    {
        return S;
    }
    S[0] = true;
    S[1] = false;
    S = check(s, S);
    if (correct(s, S, N))
    {
        return S;
    }

    S[0] = false;
    S[1] = true;
    S = check(s, S);
    if (correct(s, S, N))
    {
        return S;
    }

    S[0] = false;
    S[1] = false;
    S = check(s, S);
    if (correct(s, S, N))
    {
        return S;
    }
    vector<bool> emtpy;
    return emtpy;
}

