bool f(ll N, vector<int> &v, string &s) {
  for(ll i=1; i+1<N; i++) {
    if(v[i]==1) {
      if(s[i]=='o') {
	v[i+1] = v[i-1];
      } else {
	v[i+1] = 1-v[i-1];
      }
    } else {
      if(s[i]=='o') {
	v[i+1] = 1-v[i-1];
      } else
	v[i+1] = v[i-1];
    }
  }
  bool x, y;
  if((v[0]==1 and s[0]=='o') or (v[0]==0 and s[0]=='x')) x = v[N-1] == v[1];
  else x = v[N-1] != v[1];
  if((v[N-1]==1 and s[N-1]=='o') or (v[N-1]==0 and s[N-1]=='x')) y = v[N-2] == v[0];
  else y = v[N-2]!=v[0];
  return x and y;
}

void solve(long long N, std::string s){
  vector<int> v(N);
  for(int i=0; i<2; i++) {
    for(int j=0; j<2; j++) {
      v[0] = i; v[1] = j;
      if(f(N, v, s)) {
