int main() {
  int n;
  string s;
  Read(n);
  Read(s);

  vector<char> animal(n + 1);

  for (int i = 0; i < 4; i++) {
    if (i == 0) {
      animal[0] = 'S'; animal[1] = 'S';
    } else if (i == 1) {
      animal[0] = 'S'; animal[1] = 'W';
    } else if (i == 2) {
      animal[0] = 'W'; animal[1] = 'S';
    } else {
      animal[0] = 'W'; animal[1] = 'W';
    }

    for (int j = 1; j < n; j++) {
      if (animal[j] == 'S') {
        if (s[j] == 'o') {
          animal[j + 1] = animal[j - 1];
        } else {
          if (animal[j - 1] == 'S') {
            animal[j + 1] = 'W';
          } else {
            animal[j + 1] = 'S';
          }
        }
      } else {
        if (s[j] == 'x') {
          animal[j + 1] = animal[j - 1];
        } else {
          if (animal[j - 1] == 'S') {
            animal[j + 1] = 'W';
          } else {
            animal[j + 1] = 'S';
          }
        }
      }
    }

    if (animal[0] != animal[n]) {
      continue;
    }

    if (animal[0] == 'S') {
      if (s[0] == 'o') {
        if (animal[n - 1] != animal[1]) {
          continue;
        }
      } else {
        if (animal[n - 1] == animal[1]) {
          continue;
        }
      }
    } else {
      if (s[0] == 'x') {
        if (animal[n - 1] != animal[1]) {
          continue;
        }
      } else {
        if (animal[n - 1] == animal[1]) {
          continue;
        }
      }
    }

    for (int i = 0; i < n; i++) {
      cout << animal[i];
    }
    cout << endl;
    return 0;

  }

  Print(-1);

  return 0;
}
