const char ANIMALS[2] = {'S', 'W'};

int N;
string S;

bool consistent(char claim, char first, char middle, char second) {
    if (claim == 'o' ^ middle == ANIMALS[0])
        return first != second;
    else
        return first == second;
}

int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);

    cin >> N >> S;
    string answer(N, '.');

    for (int first = 0; first < 2; first++)
        for (int second = 0; second < 2; second++) {
            answer[0] = ANIMALS[first];
            answer[1] = ANIMALS[second];

            for (int i = 1; i < N - 1; i++) {
                bool different = (answer[i] == ANIMALS[0]) ^ (S[i] == 'o');
                answer[i + 1] = different ? ANIMALS[0] + ANIMALS[1] - answer[i - 1] : answer[i - 1];
            }

            if (consistent(S[0], answer[N - 1], answer[0], answer[1]) && consistent(S[N - 1], answer[N - 2], answer[N - 1], answer[0])) {
                cout << answer << '\n';
                return 0;
            }
        }

    cout << -1 << '\n';
}

