char conv(char c) {
	if (c == 'S') return 'W';
	else return 'S';
}

string solve() {
	string res = str;
	for (int bit = 0; bit < 4; ++bit) {
		if (bit & (1 << 0)) res[0] = 'S';
		else res[0] = 'W';
		if (bit & (1 << 1)) res[N - 1] = 'S';
		else res[N - 1] = 'W';
		string tmp = res;

		bool ok = true;
		for (int i = 0; i < N; ++i) {
			if ((tmp[i] == 'S' && str[i] == 'o') || (tmp[i] == 'W' && str[i] == 'x')) tmp[(i + 1) % N] = tmp[(i - 1 + N) % N];
			else tmp[(i + 1) % N] = conv(tmp[(i - 1 + N) % N]);
		}
		if (tmp[0] != res[0] || tmp[N - 1] != res[N - 1]) {
			ok = false;
		}
		if (ok) {
			res = tmp;
			return res;
		}
	}
	return "-1";
}

