    ok &= check(0, anim[0], anim[N-1], anim[1]);
    for (int i=1; i<N-1; i++) {
        ok &= check(i, anim[i], anim[i-1], anim[i+1]);
    }
    ok &= check(N-1, anim[N-1], anim[N-2], anim[0]);
    return ok;
}

