bool f(vector<bool>& isS, const vector<bool>& field) {
	FOR(i, 1, isS.size()-1) {
		isS[i + 1] = ((field[i] ^ isS[i]) ^ isS[i - 1]);
	}
	REP(i, isS.size()){
		if (isS[(i + 1) % isS.size()] != ((field[i] ^ isS[i]) ^ isS[(i - 1 + isS.size()) % isS.size()])) return false;
	}
	return true;
}

