  } else {
    tb[n - 1][0] = 1;
    tb[n - 1][1] = 0;
    tb[n - 1][2] = 0;
    tb[n - 1][3] = 1;
  }

  FOR(i, 1, n - 1) {
    if (s[i] == 'o') {
      REP(j, 4) {
        if (out[i][j] == 0) {
          out[i + 1][j] = out[i - 1][j];
        } else {
          out[i + 1][j] == !out[i - 1][j];
        }
      }
    } else {
      REP(j, 4) {
        if (out[i][j] == 0) {
          out[i + 1][j] = !out[i - 1][j];
        } else {
          out[i + 1][j] = out[i - 1][j];
        }
      }
    }
  }
  int sol = -1;

  int i = n - 1;
  if (s[i] == 'o') {
    REP(j, 4) {
      if (out[i][j] == 0) {
        if (out[0][j] == out[i - 1][j] && out[i][j] == tb[i][j]) {
          sol = j;
          break;
        }
      } else {
        if (out[0][j] == !out[i - 1][j] && out[i][j] == tb[i][j]) {
          sol = j;
          break;
        }
      }
    }
  } else {
    REP(j, 4) {
      if (out[i][j] == 0) {
        if (out[0][j] == !out[i - 1][j] && out[i][j] == tb[i][j]) {
          sol = j;
          break;
        }
      } else {
        if (out[0][j] == out[i - 1][j] && out[i][j] == tb[i][j]) {
          sol = j;
          break;
        }
      }
    }
  }
  if (sol == -1) {
    cout << "-1\n";
    return 0;
  }
  REP(i, n) {
    if (out[i][sol] == 0) cout << "S";
    else                  cout << "W";
  }


  return 0;
}

