std::string str;
bool status[100010];
bool is_sheep[100010];

inline
bool calc(int idx) {
	bool is = status[idx] ^ (!is_sheep[idx]);

	return is == is_sheep[(str.size() + idx - 1) % str.size()];
}

bool check(int idx) {
	if(idx == str.size() - 1) {
		return calc(idx) == is_sheep[0] && calc(0) == is_sheep[1];
	}

	is_sheep[idx + 1] = calc(idx);

	return check(idx + 1);
}

int main() {
	std::cin >> str >> str;

	for(int i = 0; i < str.size(); ++i) {
		status[i] = str[i] == 'o';
	}

	for(int i = 0; i < 2; ++i) {
		for(int j = 0; j < 2; ++j) {
			is_sheep[0] = i;
			is_sheep[1] = j;

			if(check(1)) {
				for(int i = 0; i < str.size(); ++i) {
					std::cout << (is_sheep[i] ? 'S' : 'W');
				}
				std::cout << std::endl;

