//  S o: 左右がW W or S S; x;　W　S　or 　S　W 
//  S o: 

string solve(string& s, char c0, char c1) {
	int n = s.size();
	string ans(n,' ');
	ans[0] = c0;
	ans[1] = c1;
	for(int i = 2; i < n; i++) {

		bool is_same = (s[i - 1] == 'o');
		//cout << "i:" << i << " is_same:" << is_same << endl;

		if (ans[i - 1] == 'W') {
			is_same = !is_same;
		}
		//cout << "i:" << i << " is_same:" << is_same << endl;


		if (is_same) {
			ans[i] = ans[i - 2];

		} else {
			ans[i] = ans[i - 2] == 'W' ? 'S' : 'W'; 
		}
	}

	bool is_same = s[n - 1] == 'o';
	if (ans[n - 1] == 'W') {
		is_same = !is_same;
	}
	if ((ans[0] == ans[n - 2]) != is_same) {
		return "";
	}


	return ans;
}

int main() {
	int n;
	string s;
	cin >> n >> s;


	string ans = solve(s, 'S', 'S' );
	if (ans != "") {
		cout << ans << endl;
		return 0;
	}
	ans = solve(s, 'W', 'W' );
	if (ans != "") {
		cout << ans << endl;
		return 0;
	}
	ans = solve(s, 'W', 'S' );
	if (ans != "") {
		cout << ans << endl;
		return 0;
	}
	ans = solve(s, 'S', 'W' );
	if (ans != "") {
		cout << ans << endl;
		return 0;
	}

	cout << -1 << endl;
	return 0;
}

