    for (int bit = 0; bit < 4; bit++) {
        vector<int> a(N, -1);
        for (int i = 0; i < 2; i++) {
            if (bit & (1 << i)) a[i] = 1;
            else a[i] = 0;
        }
        for (int i = 1; i < N - 1; i++) {
            if (s[i] == 'o' and a[i] == 0) a[i + 1] = a[i - 1];
            if (s[i] == 'o' and a[i] == 1) a[i + 1] = !a[i - 1];
            if (s[i] == 'x' and a[i] == 0) a[i + 1] = !a[i - 1];
            if (s[i] == 'x' and a[i] == 1) a[i + 1] = a[i - 1];
        }
        string T = "";
        for (int i = 0; i < N; i++) {
            int b = (i - 1 + N) % N;
            int f = (i + 1 + N) % N;
            if (!a[i]) {
                if (a[b] == a[f]) T += 'o';
                else T += 'x';
            }
            if (a[i]) {
                if (a[b] != a[f]) T += 'o';
                else T += 'x';
            }
        }
        if (s == T) {
            for (int i = 0; i < N; i++) {
                if (a[i] == 0) cout << 'S';
                else cout << 'W';
