void check()
{
    bool lft = f[n - 1];
    rep(i, n - 2)
    {
        if(ans[i])
        {
            if(f[i]) f[i + 1] = lft;
            else f[i + 1] = lft ^ 1;
        }
        else
        {
            lft ^= 1;
            if(f[i]) f[i + 1] = lft;
            else f[i + 1] = lft ^ 1;
        }
        lft = f[i];
    }
    int i = n - 2;
    if(ans[i])
    {
        if(f[i])
        {
            if(f[i - 1] != f[i + 1]) return;
        }
        else
        {
            if(f[i - 1] == f[i + 1]) return;
        }
    }
    else
    {
        if(!f[i])
        {
            if(f[i - 1] != f[i + 1]) return;
        }
        else
        {
            if(f[i - 1] == f[i + 1]) return;
        }
