bool find(int n, vector<bool> &s_data, bool first, bool second){
  vector<bool> Data(n + 1);
  Data.at(0) = first; Data.at(1) = second;
  for(int i = 1; i < n; i++) Data.at(i + 1) = Data.at(i - 1)^Data.at(i)^s_data.at(i);
  if(Data.at(n) == first) if((first == s_data.at(0)) == (second == Data.at(n-1))){
    REP(i, n) putchar(Data.at(i) ? 'S' : 'W');
    putchar('\n');
    return true;
  }
  return false;
}

