using namespace std;

bool solve(int N, vector<int> &s, vector<int> &ans){
    for(int i=2; i<N; i++){
        ans[i] = s[i-1] * ans[i-1] * ans[i-2];
    }

    if(ans[0] != s[N-1] * ans[N-1] * ans[N-2])
        return false;
    if(ans[1] != s[0] * ans[0] * ans[N-1])
        return false;
    return true;
}

int main(){
    cin.tie(0);
    ios::sync_with_stdio(false);
    int N;
    cin >> N;
    string str;
    cin >> str;
    vector<int> s(N);
    for(int i=0; i<N; i++) {
        if(str[i] == 'o')
            s[i] = 1;
        else
            s[i] = -1;
    }

    vector<int> ans(N);
    for(int i=-1; i<=1; i+=2){
        for(int j=-1; j<=1; j+=2){
            ans[0] = i; ans[1] = j;
            if(solve(N, s, ans)){
                for(int i=0; i<N; i++){
                    if(ans[i]==1) cout << "S";
                    else cout << "W";
                }
                cout << endl;
                return 0;
            }
        }
    }
    cout << -1 << endl;

    return 0;
}

