static void ARC069D_Menagerie()
{
	int N;
	get1int(N);

	auto seq = new char[N + 1];
	getstring(seq);
	auto ans = new char[N + 1];
	ans[N] = 0;

	const char* first = "SSWW";
	const char* second = "SWSW";
	bool success = true;
	for (int i = 0; i < 4; i++) {
		ans[0] = first[i];
		ans[1] = second[i];

		for (int j = 1; j < (N - 1); j++) {
			int next = j + 1;
			int bfr = j - 1;

			if (ans[j] == 'S') {
				if (seq[j] == 'o') {
					ans[next] = ans[bfr];
				}
				else {
					if (ans[bfr] == 'S') ans[next] = 'W';
					else ans[next] = 'S';
				}
			}
			else {
				if (seq[j] == 'o') {
					if (ans[bfr] == 'S') ans[next] = 'W';
					else ans[next] = 'S';
				}
				else {
					ans[next] = ans[bfr];
				}
			}
		}

		success = true;
		for (int j = 0; j < N; j++) {
			int next = j + 1;
			int bfr = j - 1;
			if (next >= N) next = 0;
			if (bfr < 0) bfr = N - 1;

			if (ans[j] == 'S') {
				if (seq[j] == 'o') {
					if (ans[bfr] != ans[next]) {
						success = false;
						break;
					}
				}
				else {
					if (ans[bfr] == ans[next]) {
						success = false;
						break;
					}
				}
			}
			else {
				if (seq[j] == 'o') {
					if (ans[bfr] == ans[next]) {
						success = false;
						break;
					}
				}
				else {
					if (ans[bfr] != ans[next]) {
						success = false;
						break;
					}
				}
			}
		}
		if (success) break;
	}
	if (success) printf("%s\n", ans);
	else printf("-1\n");

	delete[] seq;
	delete[] ans;
}

