const int mod = 1000000007;
const int MAX_V = 100005;

int anim[MAX_V];
int n;
string s;

bool dfs(int x) {
  int prev, next;
  if (x == 0) {
    prev = n-1;
    next = 1;
  } else if (x == n-1) {
    prev = n-2;
    next = 0;
  } else {
    prev = x-1;
    next = x+1;
  }

  bool same;
  if (anim[x] == 1 && s[x] == 'o') {
    same = true;
  } else if (anim[x] == -1 && s[x] == 'x') {
    same = true;
  } else {
    same = false;
  }

  // 羊
  if (same) {
    if (anim[prev] && anim[next] && anim[prev] != anim[next]) {
      return false;
    } else if (anim[prev] && anim[next]) {
      return true;
    } else if (anim[prev]) {
      anim[next] = anim[prev];
      return dfs(next);
    } else {
      anim[prev] = anim[next];
      return dfs(prev);
    }
  } else {
    if (anim[prev] && anim[next] && anim[prev] == anim[next]) {
      return false;
    } else if (anim[prev] && anim[next]) {
      return true;
    } else if (anim[prev]) {
      anim[next] = -anim[prev];
      return dfs(next);
    } else {
      anim[prev] = -anim[next];
      return dfs(prev);
    }
  }
}

void init() {
  rep(i, n) {
    anim[i] = 0;
  }
}

int main()
{
  cin.tie(0);
  ios::sync_with_stdio(false);

  cin >> n;
  cin >> s;

  bool res = false;

  for(int i : {1, -1}) for(int j : {1, -1}) {
    init();
    anim[0] = i;
    anim[1] = j;
    res = dfs(1);
    if(res) break;
  }

  if (res) {
    rep(i, n) {
      if (anim[i] == 1) {
        cout << "S";
      } else {
        cout << "W";
      }
    }
