bool out(string S, string s){
    int N = S.size();
    if (s[N-1] == 'o'){
        if (S[N-1] == 'S' && S[0] == S[N-2]){
            return true;
        }
        else if (S[N-1] == 'W' && S[0] != S[N-2]){
            return true;
        }
    }
    else {
        if (S[N-1] == 'S' && S[0] != S[N-2]){
            return true;
        }
        else if (S[N-1] == 'W' && S[0] == S[N-2]){
            return true;
        }
    }
    return false;
}

