const int N = 200010;

int n,first,last;
string s;

int dp[N][2][2];

int calc(int idx , int prev,int cur){
	if(idx == n)
		return (cur == first);
	int &ret = dp[idx][prev][cur];
	if(ret != -1)
		return ret;
	ret = 0;
	// sheep
	if(cur == 0){
		if(s[idx] == 'o'){
			ret = ret || calc(idx + 1 , cur,prev);
		}else{
			ret = ret || calc(idx + 1 , cur,!prev);
		}
	}else{
		// wolf
		if(s[idx] == 'o'){
			ret = ret || calc(idx + 1 , cur,!prev);
		}else{
			ret = ret || calc(idx + 1 , cur,prev);
		}
	}
	return ret;
}

string ans = "";

void build(int idx , int prev , int cur){
	if(idx == n)
		return;
	ans += (cur == 0 ? "S" : "W");
	if(cur == 0){
		if(s[idx] == 'o'){
			build(idx + 1 , cur,prev);
		}else{
			build(idx + 1 , cur,!prev);
		}
	}else{
		// wolf
		if(s[idx] == 'o'){
			build(idx + 1 , cur,!prev);
		}else{
			build(idx + 1 , cur,prev);
		}
	}
}
int main(){
