bool guess(int first, int second) {
    is_sheep[0] = first;
    is_sheep[1] = second;

    for(int i=1;i<n-1;i++) {
        if( (is_sheep[i] && s[i] == 'o') || (!is_sheep[i] && s[i] == 'x') ){
