using namespace std;

int N;
string s;

bool last_check(vector<char> &t) {
    if (t[N-1] == 'S' && s[N-1] == 'o') {
        if (t[0] == t[N-2]) return true;
    } else if (t[N-1] == 'S' && s[N-1] == 'x') {
        if (t[0] != t[N-2]) return true;
    } else if (t[N-1] == 'W' && s[N-1] == 'o') {
        if (t[0] != t[N-2]) return true;
    } else if (t[N-1] == 'W' && s[N-1] == 'x') {
        if (t[0] == t[N-2]) return true;
    }
    return false;
}

bool check(vector<char> &t) {
    for (int i = 1; i < N-2; i++) {
        if (s[i] == 'o') {  // o
            if (t[i] == 'S') {
                t[i+1] = t[i-1];
            } else {
                t[i+1] = (t[i-1] == 'S' ? 'W' : 'S');
            }
        } else {            // x
            if (t[i] == 'S') {
                t[i+1] = (t[i-1] == 'S' ? 'W' : 'S');
            } else {
                t[i+1] = t[i-1];
            }
        }
    }

    if (t[N-2] == 'S') {
        if (s[N-2] == 'o' && t[N-3] == t[N-1]) {
            t[N-1] = t[N-3];
            if (last_check(t)) return true;
        } else if (s[N-2] == 'x' && t[N-3] != t[N-1]) {
            t[N-1] = (t[N-3] == 'S' ? 'W' : 'S');
            if (last_check(t)) return true;
        }
    } else {                    // Wolf
        if (s[N-2] == 'o' && t[N-3] != t[N-1]) {
            t[N-1] = (t[N-3] == 'S' ? 'W' : 'S');
            if (last_check(t)) return true;
        } else if (s[N-2] == 'x' && t[N-3] == t[N-1]) {
            t[N-1] = t[N-3];
            if (last_check(t)) return true;
        }
    }

    return false;
}

int main(void) {

    cin >> N;
