int s[100000];
int N;

int ans[100000]; // 1: sheep, 0: wolf

int sub(int k) {
    int a = ans[k];
    int b = ans[(k - 1 + N) % N];
    if (s[k]) {
        return a ? b : (1 - b);
    } else {
        return a ? (1 - b) : b;
    }
}

int main() {
    cin >> N;
    string S;
    cin >> S;
    for(int i = 0; i < N; i++) {
        s[i] = S[i] == 'o';
    }
    for(int i = 0; i < 2; i++) {
        for(int j = 0; j < 2; j++) {
            ans[0] = i;
            ans[1] = j;
            for(int k = 1; k < N - 1; k++) {
                ans[k + 1] = sub(k);
            }
            if(sub(N - 1) == ans[0] && sub(0) == ans[1]) {
                for (int k = 0; k < N; k++) {
                    cout << (ans[k] ? 'S' : 'W');
                }
                cout << endl;
                return 0;
            }
        }
    }
    cout << -1 << endl;
    return 0;
}

