bool work(const string &s) {
    for (int i = 1; i < n - 1; i++) {
        if(s[i] == 'o') {
            if(res[i]) {
                res[i + 1] = !res[i - 1];
            } else {
                res[i + 1] = res[i - 1];
            }
        } else {
            if(res[i]) {
                res[i + 1] = res[i - 1];
            } else {
                res[i + 1] = !res[i - 1];
            }
        }
    }
    bool f1, f2;
    f1 = f2 = 0;
    if(s[n - 1] == 'o') {
        if(res[n - 1]) {
            f1 =  res[n - 2] != res[0];
        } else {
            f1 =  res[n - 2] == res[0];
        }
    } else {
        if(res[n - 1]) {
            f1 =  res[n - 2] == res[0];
        } else {
            f1 =  res[n - 2] != res[0];
        }
    }

    if(s[0] == 'o') {
        if(res[0]) {
            f2 =  res[n - 1] != res[1];
        } else {
            f2 =  res[n - 1] == res[1];
        }
    } else {
        if(res[0]) {
            f2 =  res[n - 1] == res[1];
        } else {
            f2 =  res[n - 1] != res[1];
        }
    }
    return f1 && f2;
}
void pr() {
    for (int i = 0; i < n; i++) {
        if(res[i]) cout << 'W';
        else cout << 'S';
    }
    cout << endl;
}
void solve() {
    string s;
    while(cin >> n) {
        cin >> s;
        res.clear();
        res.resize(n);
        res[0] = res[1] = 0;
        bool f = work(s);
        if(f) {
            pr();
            continue;
        }
        res[0] = res[1] = 1;
        f = work(s);
        if(f) {
            pr();
            continue;
        }
        res[0] = 1; res[1] = 0;
        f = work(s);
        if(f) {
            pr();
            continue;
        }
        res[0] = 0; res[1] = 1;
        f = work(s);
        if(f) {
            pr();
            continue;
        }
        cout << -1 << endl;
    }
}
