            v = { -a, +b, +c }; solver.addClause(v);
        }
        else {
            v = { +a, +b, +c }; solver.addClause(v);
            v = { -a, +b, -c }; solver.addClause(v);
            v = { -a, -b, +c }; solver.addClause(v);
            v = { +a, -b, -c }; solver.addClause(v);
        }
    }

    if (solver.solve()) {
        cout << -1 << endl;
