char s[100010];
int ans[100010];
int n;

bool check (int id) {
        if (id + 1 == n) {
                if (ans[id] == 0) {
                        if (s[id] == 'o') {
                                if (ans[id - 1] != ans[id] || ans[0] != ans[id])        return false;
                        } else {
                                if (ans[id - 1] == ans[id] && ans[0] == ans[id])        return false;
                        }
                } else {
                        if (s[id] == 'o') {
                                if (ans[id - 1] == ans[id] && ans[0] == ans[id])        return false;
                        } else {
                                if (ans[id - 1] != ans[id] || ans[0] != ans[id])        return false;
                        }
                }
                if (ans[0] == 0) {
                        if (s[0] == 'o') {
                                if (ans[1] != ans[0] || ans[n - 1] != ans[0])   return false;
                        } else {
                                if (ans[1] == ans[0] && ans[n - 1] == ans[0])   return false;
                        }
                } else {
                        if (s[0] == 'o') {
                                if (ans[1] == ans[0] && ans[0] == ans[n - 1])   return false;
                        } else {
                                if (ans[1] != ans[0] && ans[0] != ans[n - 1])   return false;
                        }
                }
                return true;
        } else {
                if (ans[id] == 0) {
                        if (s[id] == 'o') {
                                if (id - 1 >= 0) {
                                        if (ans[id - 1] != ans[id])     return false;
                                }
                                ans[id + 1] = ans[id];
                                if (check (id + 1)) {
                                        return true;
                                } else {
                                        return false;
                                }
                        } else {
                                if (id - 1 < 0) {
                                        ans[id + 1] = ans[id];
                                        if (check (id + 1)) {
                                                return true;
                                        }
                                        ans[id + 1] = 1 - ans[id];
                                        if (check (id + 1)) {
                                                return true;
                                        }
                                        return false;
                                } else {
                                        if (ans[id - 1] != ans[id]) {
                                                ans[id + 1] = ans[id];
                                                if (check (id + 1))     return true;
                                                ans[id + 1] = 1 - ans[id];
                                                if (check (id + 1))     return true;
                                                else    return false;
                                        } else {
                                                ans[id + 1] = 1 - ans[id];
                                                if (check (id + 1))     return true;
                                                else    return false;
                                        }
                                }
                        }
                } else {
                        if (s[id] == 'o') {
                                if (id - 1 >= 0) {
                                        if (ans[id - 1] == ans[id]) {
                                                ans[id + 1] = 1 - ans[id];
                                                if (check (id + 1))     return true;
                                                else    return false;
                                        } else {
                                                ans[id + 1] = ans[id];
                                                if (check (id + 1))     return true;
                                                ans[id + 1] = 1 - ans[id];
                                                if (check (id + 1))     return true;
                                                else    return false;
                                        }
                                } else {
                                        ans[id + 1] = ans[id];
                                        if (check (id + 1))     return true;
                                        ans[id + 1] = 1 - ans[id];
                                        if (check (id + 1))     return true;
                                        else    return false;
                                }
                        } else {
                                if (id - 1 >= 0) {
                                        if (ans[id] != ans[id - 1]) {
                                                return false;
                                        }
                                }
                                ans[id + 1] = ans[id];
                                if (check (id + 1)) {
                                        return true;
                                } else {
                                        return false;
                                }
                        }
                }
        }
}

