void fill(vector<bool>& b, int n, string s) {
  repeat(i,2,n) {
    if(b[i-2]&&b[i-1]) { // ss
      if(s[i-1]=='o') {
        b[i]=true;
      } else {
        b[i]=false;
      }
    }
    if(!b[i-2]&&b[i-1]) { // ws
      if(s[i-1]=='o') {
        b[i]=false;
      } else {
        b[i]=true;
      }
    }
    if(b[i-2]&&!b[i-1]) { // sw
      if(s[i-1]=='o') {
        b[i]=false;
      } else {
        b[i]=true;
      }
    }
    if(!b[i-2]&&!b[i-1]) { // ww
      if(s[i-1]=='o') {
        b[i]=true;
      } else {
        b[i]=false;
      }
    }
  }
}

