  rep(i,n) {
    if(b[i]&&s[i]=='o') {
      if(b[(i-1+n)%n]!=b[(i+1)%n])
        return false;
    }
    if(b[i]&&s[i]=='x') {
      if(b[(i-1+n)%n]==b[(i+1)%n])
        return false;
    }
    if(!b[i]&&s[i]=='o') {
      if(b[(i-1+n)%n]==b[(i+1)%n])
        return false;
    }
    if(!b[i]&&s[i]=='x') {
      if(b[(i-1+n)%n]!=b[(i+1)%n])
        return false;
    }
  }
  return true;
}

