  if (visit[k][p][pp][f][ff]) return dp[k][p][pp][f][ff];
  visit[k][p][pp][f][ff] = true;

  bool ret = false;
  if(k==0){
    for(int i = 0; i < 4; i++){
      ret |= solve(2,dx[i],dy[i],dy[i],dx[i]);
    }
    return dp[k][p][pp][f][ff] = ret;
  }

  ret = false;
  if(k==n){
    if(p==0){
      if(s[k-1]=='o'){
	ret |= (pp==f);
      }else{
	ret |= (pp!=f);
      }
    }else{
      if(s[k-1]=='x'){
	ret |= (pp==f);
      }else{
	ret |= (pp!=f);
      }
    }


    if(ret){
