      if(f==0){
	if(s[0]=='o'){
	  ret |= (ff==p);
	}else{
	  ret |= (ff!=p);
	}
      }else{
	if(s[0]=='x'){
	  ret |= (ff==p);
	}else{
	  ret |= (ff!=p);
	}
      }

      return dp[k][p][pp][f][ff] = ret;
    }
    return false;
  }

  ret = false;
  if(p==0){
    if(s[k-1]=='o'){
      ret |= solve(k+1,pp,p,f,ff);
    }else{
      ret |= solve(k+1,(pp+1)&1,p,f,ff);
    }
  }else{
