//ture == sheep
vector<bool> next(bool fir, bool sec, string& s)
{
  vector<bool> res = {fir, sec};

  ll N = s.size();
  for (ll i = 0; i < N; ++i)
  {
    if (sec)
    {
      if (s[i] == 'o')
      {
        res.push_back(fir);
      }
      else
      {
        res.push_back(!fir);
      }
    }
    else
    {
      if (s[i] == 'o')
      {
        res.push_back(!fir);
      }
      else
      {
        res.push_back(fir);
      }
    }
    fir = sec;
    sec = *(res.end() - 1);
  }
  return res;
}


