bool print_if_valid(const vector<int> &ans, const string &s) {
    if (s.front() == 'o') {
        if (ans.front() == 0) {
            if (ans[1] != ans.back())
                return false;
        } else {
            if (ans[1] == ans.back())
                return false;
        }
    } else {
        if (ans.front() == 0) {
            if (ans[1] == ans.back())
                return false;
        } else {
            if (ans[1] != ans.back())
                return false;
        }
    }

    if (s.back() == 'o') {
        if (ans.back() == 0) {
            if (ans[0] != ans[ans.size() - 2])
                return false;
        } else {
            if (ans[0] == ans[ans.size() - 2])
                return false;
        }
    } else {
        if (ans.back() == 0) {
            if (ans[0] == ans[ans.size() - 2])
                return false;
        } else {
            if (ans[0] != ans[ans.size() - 2])
                return false;
        }
    }

    for (int k : ans) {
        cout << (k == 0 ? 'S' : 'W');
    }
    cout << endl;
    return true;
}

