bool make_line(int first, int last) {
	for (int i = 0; i <= N+1; i++) ans[i] = 0;

	ans[1] = ans[N+1] = first;
	ans[0] = ans[N] = last;

	for (int i = 1; i <= N; i++) {
		char rep = s[i-1];
		if ((ans[i] == 1 && rep == 'o') || (ans[i] == -1 && rep == 'x')) {
			if (ans[i+1] == 0) ans[i+1] = ans[i-1];
			if (ans[i+1] != ans[i-1]) return false;

		} else {
			if (ans[i+1] == 0) ans[i+1] = -ans[i-1];
			if (ans[i+1] == ans[i-1]) return false;
		}
	}
	return true;
}

void output_ans(void) {
	for (int i = 1; i <= N; i++) {
		if (ans[i] == 1) cout << 'S';
		else cout << 'W';
	}
	cout << endl;
}

