bool good_triple(char a, char b, char c, char ans) {
  if ((b == 'S' && ans == 'o') || (b == 'W' && ans == 'x'))
    return a == c;
  return a != c;
}

bool check(vector<char>& vc, const string& s) {
  for (size_t i = 1; i + 1 < s.length(); ++i) {
    if (good_triple(vc[i - 1], vc[i], 'W', s[i]))
      vc[i + 1] = 'W';
    else
      vc[i + 1] = 'S';
  }
  return good_triple(vc[vc.size() - 2], vc[vc.size() - 1], vc[0], s.back()) &&
         good_triple(vc.back(), vc[0], vc[1], s[0]);
}

