bool valid(vec<bool>& sheep, vector<bool>& same)
{
    int len = SZ(sheep);
    REP(i, len){
        bool s = sheep[(i + len - 1) % len] == sheep[(i + 1) % len];
        if (sheep[i] && s != same[i] || !sheep[i] && s == same[i]){
            return false;
        }
    }
    return true;
}

bool is_sheep(bool same, bool neighbor, bool opposite)
{
    return (same ^ neighbor) ? !opposite : opposite;
}

