int main(){
	int N; string S;
	while(cin >> N >> S){
		vector<int> v(N);
		bool find = false;
		for(int i=0;i<2;i++){
			if(find) break;
			for(int j=0;j<2;j++){
				if(find) break;
				v[0] = i;
				v[1] = j;
				v[2] = ((j==0 && S[1]=='o')||(j==1&&S[1]=='x')) ? i : 1-i;
				for(int k=2;k<N;k++){
					v[k] = (v[k-1]==0 ? S[k-1]=='o' : S[k-1]=='x') ? v[k-2] : 1-v[k-2];
				}
				bool valid = true;
				for(int k=N-1;k<=N;k++){
					if(v[k%N]==0){
						valid &= (S[k%N] == (v[(k-1)%N]==v[(k+1)%N] ? 'o' : 'x'));
					} else {
						valid &= (S[k%N] == (v[(k-1)%N]==v[(k+1)%N] ? 'x' : 'o'));
					}
				}
				if(valid){
					for(int k=0;k<N;k++){
						cout << char(v[k]==0 ? 'S' : 'W');
					}
					cout << endl;
					find = true;
				}
			}
		}
		if(!find) cout << -1 << endl;
	}
}

