string find(string s, string s12, int N)
{
    bool f = true;
    string ans = s12;
    for (int i = 1; i < N; i++)
    {
        if ((s[i] == 'o' && ans[i] == 'S') || (s[i] == 'x' && ans[i] == 'W'))
        {
            ans += ans[i - 1];
        }
        else if ((s[i] == 'o' && ans[i] == 'W') || (s[i] == 'x' && ans[i] == 'S'))
        {
            ans += ans[i-1] == 'S' ? 'W' : 'S';
        }
    }

    if(s12[0] == ans[N])
    {
        return ans.substr(0, N);
    }
    else
    {
        return "-1";
    }
}

int main()
{
    int N;
    string s;
    string ret;

    cin >> N;
    cin >> s;

    string s12;

    s12 = "SS";
    ret = find(s, s12, N);
    if(ret != "-1")
    {
        cout << ret << endl;
        return 0;
    }
    s12 = "SW";
    ret = find(s, s12, N);
    if (ret != "-1")
    {
        cout << ret << endl;
        return 0;
    }

    s12 = "WS";
    ret = find(s, s12, N);
    if (ret != "-1")
    {
        cout << ret << endl;
        return 0;
    }

    s12 = "WW";
    ret = find(s, s12, N);
    cout << ret << endl;

    return 0;
}

