std::string sim(const std::string& t0, const std::string& s) {
  size_t n = s.length();
  std::string res = t0;
  for (size_t i = 1; i <= n; ++i) {
    size_t pi = i-1;
    size_t ci = (i<n? i:0);

    char cur;
    if (res[ci] == 'S') {
      if (s[ci] == 'o') {
        cur = res[pi];
      } else {
        cur = res[pi] ^ 'S' ^ 'W';
      }
    } else {
      if (s[ci] == 'o') {
        cur = res[pi] ^ 'S' ^ 'W';
      } else {
        cur = res[pi];
      }
    }
    res += cur;
  }

  if (res[1] != res[n+1]) return {};
  if (res[0] != res[n]) return {};
  res.pop_back();
  res.pop_back();
  return res;
}

