bool assign(int i){
   if(i==0 || i==1){
        assignar[i] = true;
        if(assign(i+1)){
            return true;
        }
        assignar[i] = false;
        if(assign(i+1)){
            return true;
        }
        return false;
    }
    //割り当てた条件がクリアかどうかを確認する
    else if(i==N){
        bool t = (s[i-1] == 'o');
        if(t ^ assignar[i-1]){
            if(assignar[i-2] ^ assignar[0]){
                bool u = (s[0] == 'o');
                if(u ^ assignar[0]){
                    return assignar[i-1] ^ assignar[1];
                }else{
                    return !(assignar[i-1] ^ assignar[1]);
                }
            }else{
                return false;
            }
        }else{
            if(!(assignar[i-2] ^ assignar[0])){
                bool v = (s[0] == 'o');
                if(v ^ assignar[0]){
                    return assignar[i-1] ^ assignar[1];
                }else{
                    return !(assignar[i-1] ^ assignar[1]);
                }
            }else{
                return false;
            }
        }
    }else{
        bool t = (s[i-1] == 'o');
        if(t ^ assignar[i-1]){
            assignar[i] = !assignar[i-2];
        }else{
            assignar[i] = assignar[i-2];
        }
        return assign(i+1);
    }
}

