class UnionFind
{
public:
    vector<ll> Parent;

    UnionFind(ll N)
    {
        Parent = vector<ll>(N, -1);
    }
    ll find(ll A)
    {
        if (Parent[A] < 0)
            return A;
        return Parent[A] = find(Parent[A]);
    }

    ll size(ll A)
    {
        return -Parent[find(A)];
    }

    bool Union(ll A, ll B)
    {
        A = find(A);
        B = find(B);
        if (A == B)
        {
            return false;
        }
        if (size(A) < size(B))
            swap(A, B);

        Parent[A] += Parent[B];
        Parent[B] = A;

        return true;
    }
};

ll gcd(ll a, ll b)
{
    if (b == 0)
        return a;
    return gcd(b, a % b);
}

ll lcm(ll a, ll b)
{
    ll g = gcd(a, b);
    return a / g * b;
}

ll mulMod(ll a, ll b)
{
    return (((a % MOD) * (b % MOD)) % MOD);
}

ll powMod(ll a, ll p)
{
    if (p == 0)
    {
        return 1;
    }
    else if (p % 2 == 0)
    {
        ll half = powMod(a, p / 2);
        return mulMod(half, half);
    }
    else
    {
        return mulMod(powMod(a, p - 1), a);
    }
}

ll ceil(ll a, ll b)
{
    return (a + b - 1) / b;
}

vector<ll> tsort(Graph G)
{
    ll N = G.size();
    vector<ll> in(N);
    for (auto &&edges : G)
    {
        for (auto &&edge : edges)
        {
            in[edge]++;
        }
    }

    queue<int> que;

    for (int i = 0; i < N; i++)
    {
        if (in[i] == 0)
        {
            que.push(i);
        }
    }
    int cnt = 0;
    vector<ll> ans;
    while (!que.empty())
    {
        int v = que.front();
        que.pop();
        ans.push_back(v);
        for (auto &&next : G[v])
        {

            in[next]--;
            if (in[next] == 0)
            {
                que.push(next);
            }
        }
    }
    return ans;
}
vector<bool> check(string s, vector<bool> S)
{
    for (int i = 2; i < S.size(); i++)
    {
        if (S[i - 1])
        {
            if (s[i - 1] == 'o')
            {
                S[i] = S[i - 2];
            }
            else
            {
                S[i] = !S[i - 2];
            }
        }
        else
        {
            if (s[i - 1] == 'o')
            {
                S[i] = !S[i - 2];
            }
            else
            {
                S[i] = S[i - 2];
            }
        }
    }
    return S;
}

bool correct(string s, vector<bool> S, ll N)
{
    if (S[0] != S[N])
        return false;
    if (S[0])
    {
        if ((s[0] == 'o' && S[1] == S[N - 1]) || (s[0] == 'x' && S[1] != S[N - 1]))
        {
            return true;
        }
    }
    else
    {
        if ((s[0] == 'o' && S[1] != S[N - 1]) || (s[0] == 'x' && S[1] == S[N - 1]))
        {
            return false;
        }
    }
    return false;
}
vector<bool> solve(long long N, std::string s)
{
    vector<bool> S(2 * N, false);
    S[0] = true;
    S[1] = true;
    S = check(s, S);

    if (correct(s, S, N))
    {
        return S;
    }
    S[0] = true;
    S[1] = false;
    S = check(s, S);
    if (correct(s, S, N))
    {
        return S;
    }

    S[0] = false;
    S[1] = true;
    S = check(s, S);
    if (correct(s, S, N))
    {
        return S;
    }

    S[0] = false;
    S[1] = false;
    S = check(s, S);
    if (correct(s, S, N))
    {
        return S;
    }
    vector<bool> emtpy;
    return emtpy;
}

