        if (str[i] == 'o') {
            if (v[i] == 0) {
                v[r] = v[l];
            } else {
                v[r] = !v[l];
            }
            if (d[i] == 0) {
                d[r] = d[l];
            } else {
                d[r] = !d[l];
            }
        } else {
            if (v[i] == 0) {
                v[r] = !v[l];
            } else {
                v[r] = v[l];
            }
            if (d[i] == 0) {
                d[r] = !d[l];
            } else {
                d[r] = d[l];
            }
        }
    }

    bool ans = true;
    if (str[n-1] == 'o') {
        if (v[n-1] == 0) {
            if (!(v[0] == v[n-2])) ans = false;
        } else {
            if (!(v[0] == !v[n-2])) ans = false;
        }
    } else {
        if (v[n-1] == 0) {
            if (!(v[0] == !v[n-2])) ans = false;
        } else {
            if (!(v[0] == v[n-2])) ans = false;
        }
    }
    bool ans1 = true;
    if (str[n-1] == 'o') {
        if (d[n-1] == 0) {
            if (!(d[0] == d[n-2])) ans1 = false;
        } else {
            if (!(d[0] == !d[n-2])) ans1 = false;
        }
    } else {
        if (d[n-1] == 0) {
            if (!(d[0] == !d[n-2])) ans1 = false;
        } else {
            if (!(d[0] == d[n-2])) ans1 = false;
        }
    }

    if (!ans && !ans1) {
        cout << -1 << endl;
        return 0;
    }

    for (int i = 0; ans && i < n; i++) cout << (v[i] ? 'W' : 'S');
    for (int i = 0; !ans && i < n; i++) cout << (d[i] ? 'W' : 'S');
    cout << endl;

    return 0;
}

