int n;
string s;

bool solve(string &t){
    for(int i = 1; i < n - 1; i++){
        if(s[i] == 'o'){
            if(t[i] == 'W'){
                if(t[i - 1] == 'S') t.pb('W');
                else t.pb('S');
            }
            else{
                if(t[i - 1] == 'S') t.pb('S');
                else t.pb('W');
            }
        }
        else{
            if(t[i] == 'W'){
                if(t[i - 1] == 'S') t.pb('S');
                else t.pb('W');
            }
            else{
                if(t[i - 1] == 'S') t.pb('W');
                else t.pb('S');
            }
        }
    }
    bool ok = false;
    for(int i = 0; i < n; i++){
        int l = i - 1, r = i + 1;
        if(l < 0) l += n;
        if(r >= n) r -= n;
        if(s[i] == 'o'){
            if(t[i] == 'W'){
                if(t[l] == t[r]) ok = true;
            }
            else{
                if(t[l] != t[r]) ok = true;
            }
        }
        else{
            if(t[i] == 'W'){
                if(t[l] != t[r]) ok = true;
            }
            else{
                if(t[l] == t[r]) ok = true;
            }
        }
    }
    return !ok;
}

int main()
{
    ios_base::sync_with_stdio(0);
    cin >> n >> s;

    string tmp = "SW";
    if(solve(tmp)){
        cout << tmp << endl;
        exit(0);
    }

    tmp = "SS";
    if(solve(tmp)){
        cout << tmp << endl;
        exit(0);
    }

    tmp = "WS";
    if(solve(tmp)){
        cout << tmp << endl;
        exit(0);
    }

    tmp = "WW";
    if(solve(tmp)){
        cout << tmp << endl;
        exit(0);
    }

    cout << -1 << endl;
    return 0;
}

