bool f(vector<bool>& isS, const vector<bool>& field) {
	FOR(i, 1, isS.size()-1) {
		isS[i + 1] = ((field[i] ^ isS[i]) ^ isS[i - 1]);
	}
	REP(i, isS.size()){
		if (isS[(i + 1) % isS.size()] != ((field[i] ^ isS[i]) ^ isS[(i - 1 + isS.size()) % isS.size()])) return false;
	}
	return true;
}

void solve() {
	int N; cin >> N;
	string s; cin >> s;
	vector<bool> isS(N);
	vector<bool> field(N);
	REP(i, N) {
		field[i] = (s[i] == 'o');
	}
	for (int i = 0; i < 4; ++i) {
		bitset<2> b(i);
		isS[0] = b[0];
		isS[1] = b[1];
		if (f(isS, field)) {
			for (auto a : isS) {
				cout << (a ? 'S' : 'W');
			}
			cout << endl;
			return;
		}
	}
	cout << -1 << endl;
}

