      if(t[1] == t[N - 1]) continue;
    }
    string ret = "";
    for(int i = 0; i < N; i++) {
      if(t[i])ret.push_back('W'); else ret.push_back('S');
    }
    cout << ret << endl;
    return 0;
  }
