void make_str(string& ans,string& s){

    int now = 1;
    int len = s.length();
    for(int i = 1;i < len-1;i++){
        if(s[i] == 'x'){
            //xが来た
            if(ans[now] == 'S'){
                //今見ている文字がSの場合
                if(ans[now-1] == 'S'){
                    //SSW
                    ans.push_back('W');
                }else{
                    //WSS
                    ans.push_back('S');
                }
            }else{
                //今見ている文字がWの場合
                if(ans[now-1] == 'S'){
                    //SWS
                    ans.push_back('S');
                }else{
                    //WWW
                    ans.push_back('W');
                }
            }
        }else{
            //oが来た
            if(ans[now] == 'S'){
                //今見ている文字がSの場合
                if(ans[now-1] == 'S'){
                    //SSS
                    ans.push_back('S');
                }else{
                    //WSW
                    ans.push_back('W');
                }

            }else{
                //今見ている文字がWの場合
                if(ans[now-1] == 'S'){
                    //SWW
                    ans.push_back('W');
                }else{
                    //WWS
                    ans.push_back('S');
                }

            }
        }
        now++;
    }
}

string check(string& ans){

    string vec;
    int len = ans.length();

    for(int i = 0;i < ans.length();i++){

        if(i == 0){
            if(ans[i] == 'S'){
                if(ans[len-1] == ans[1]){
                    vec.push_back('o');
                }else{
                    vec.push_back('x');
                }
            }else{
                if(ans[len-1] == ans[1]){
                    vec.push_back('x');
                }else{
                    vec.push_back('o');
                }
            }
        }else if(i == len-1){

            if(ans[i] == 'S'){
                if(ans[i-1] == ans[0]){
                    vec.push_back('o');
                }else{
                    vec.push_back('x');
                }
            }else{
                if(ans[i-1] == ans[0]){
                    vec.push_back('x');
                }else{
                    vec.push_back('o');
                }
            }
        }else{
            if(ans[i] == 'S'){
                if(ans[i-1] == ans[i+1]){
                    vec.push_back('o');
                }else{
                    vec.push_back('x');
                }
            }else{
                if(ans[i-1] == ans[i+1]){
                    vec.push_back('x');
                }else{
                    vec.push_back('o');
                }
            }
        }
    }
    return vec;
}

