				result += result[j - 1];
			}
			else if (result[j - 1] == 'S')
			{
				result += "W";
			}
			else
			{
				result += "S";
			}
		}

		isValid = true;
		for (auto j = N - 1; j <= N; ++j)
		{
			auto isSame = false;
			auto current = (j + N) % N;
			auto prev = (j + N - 1) % N;
			auto next = (j + N + 1) % N;
			if (result[current] == 'S')
			{
				if (s[current] == 'o')
				{
					isSame = true;
				}
			}
			else if (s[current] == 'x')
			{
				isSame = true;
			}

			if (isSame)
			{
				if (result[next] != result[prev])
				{
					isValid = false;
					break;
				}
			}
			else
			{
				if (result[next] == result[prev])
				{
					isValid = false;
					break;
				}
			}
		}

		if (isValid)
		{
			cout << result << endl;
			break;
		}
	}

	if (!isValid)
	{
		cout << "-1" << endl;
	}

	return 0;
}

