bool solve()
{
	for (int i = 1; i < n; i++)
	{
		if (ans[i] == 'W')
		{
			if (s[i] == 'x') ans[(i+1)%n] = ans[(i-1)%n];
			else
			{
				if (ans[(i-1)%n] == 'W') ans[(i+1)%n] = 'S';
				else ans[(i+1)%n] = 'W';
			}
		}
		else
		{
			if (s[i] == 'o') ans[(i+1)%n] = ans[(i-1)%n];
			else
			{
				if (ans[(i-1)%n] == 'W') ans[(i+1)%n] = 'S';
				else ans[(i+1)%n] = 'W';
			}
		}
	}

	if (ans[0] != 'S') return false;

	if (s[0] == 'o')
	{
		if (ans[1] != ans[n-1]) return false;
	}
	else
	{
		if (ans[1] == ans[n-1]) return false;
	}
	return true;
}


