	isSheep[1] = b;

	for (int i = 1; i < n - 1; i++) {
		if ((isSheep[i] && s[i] == 'o') || (!isSheep[i] && s[i] == 'x')) {
			isSheep[i + 1] = isSheep[i - 1];
		} else {
			isSheep[i + 1] = (isSheep[i - 1] ^ 1);
		}
	}

	if ((isSheep[n - 1] && s[n - 1] == 'o') || (!isSheep[n - 1] && s[n - 1] == 'x')) {
		return isSheep[0] == isSheep[n - 2];
