}

int main() {
	int N; cin >> N;
	vector<bool> ox(N);
	for (int i = 0; i < N; i++) {
		char c; cin >> c;
		ox[i] = binalize_ox(c);
	}
	vector<bool> ans;
	for (int f = 0; f < 2; f++) {
		for (int s = 0; s < 2; s++) {
			vector<bool> sw(N);
			sw[0] = f;
			sw[1] = s;
			for (int pos = 2; pos < N; pos++) {
				sw[pos] = sw[pos - 2];
