					sw[pos] = !sw[pos];
				}
			}

			bool f_check;
			f_check = sw[N - 2];
			if (!(ox[N - 1] ^ sw[N - 1])) {
				f_check = !f_check;
			}

			if (f_check == f) {
				ans = sw;
				goto endloop;
			}
		}
	}
endloop:
	if (ans.size() > 0) {
		for (bool b: ans) {
			if (b == true) {
				cout << 'W';
			}
			else {
				cout << 'S';
			}
		}
		cout << endl;
	}
	else {
		cout << -1 << endl;
	}
}

