string animals(string res, int& N, string& S){
    for(int i=1;i<N-1;i++){
        if(res[i] == 'S'){
            if(S[i] == 'o'){
                if(res[i-1] == 'S') res += 'S';
                else res += 'W';
            }
            else {
                if(res[i-1] == 'S') res += 'W';
                else res += 'S';
            }
        }
        else {
            if(S[i] == 'o'){
                if(res[i-1] == 'S') res += 'W';
                else res += 'S';
            }
            else{
                if(res[i-1] == 'S') res += 'S';
                res += 'W';
            }
        }
    }

    bool ok = true;
    for(int i=1;i<N;i++){
        if(res[i] == 'S'){
            if(S[i] == 'o' && res[i-1] != res[(i+1)%N]) ok = false;
            if(S[i] == 'x' && res[i-1] == res[(i+1)%N]) ok = false;
        }
        else {
            if(S[i] == 'o' && res[i-1] == res[(i+1)%N]) ok = false;
            if(S[i] == 'x' && res[i-1] != res[(i+1)%N]) ok = false;
        }
    }

    //cout << res << endl;

    if(!ok) return "-1";
    return res;
}

