using namespace std;

char next(char before, char now, char ans)
{
	auto inv = [](char animalType){ return animalType == 'S' ? 'W' : 'S'; };
	char result{ before };

	if(ans != 'o') {
		result = inv(result);
	}

	if(now != 'S') {
		result = inv(result);
	}

	return result;
}

bool judge(string& str, string ans)
{
	for(auto i = 1; i < str.size() - 1; ++i) {
		str[i + 1] = next(str[i - 1], str[i], ans[i]);
	}

	return str[0] == str.back();
}

