bool ok(int i, int j) {
	b[0] = i; b[prv(0)] = j;
	for (int i = 0; nxt(i) != prv(0); i = nxt(i)) {
		if ((b[i] && s[i] == 'o') || (!b[i] && s[i] == 'x'))b[nxt(i)] = b[prv(i)];
		else b[nxt(i)] = !b[prv(i)];
	}
	int a = prv(0), c = prv(prv(0));
	if (b[a]) {
		if ((s[a] == 'o'&&b[0] != b[c]) || (s[a] == 'x'&&b[0] == b[c]))return false;
	}
	else if ((s[a] == 'o'&&b[0] == b[c]) || (s[a] == 'x'&&b[0] != b[c]))return false;
	return true;
}
