bool hoge(vector<bool> &t) {
    FOR(i,1,n) {
        if(i!=n-1) {
            if(t[i]==S) {
                if(s[i]=='o') {
                    t.push_back(t[i-1]);
                }
                else {
                    t.push_back(!t[i-1]);
                }
            }
            else {
                if(s[i]=='o') {
                    t.push_back(!t[i-1]);
                }
                else {
                    t.push_back(t[i-1]);
                }
            }
        }
        else {
            if(t[i]==S) {
                if(s[i]=='o') {
                    return t[i-1]==t[0];
                }
                else {
                    return t[i-1]!=t[0];
                }
            }
            else {
                if(s[i]=='o') {
                    return t[i-1]!=t[0];
                }
                else {
                    return t[i-1]==t[0];
                }
            }
        }
    }
    return true;
}
