  for (int i = 0; i < N; i++){
    scanf(" %c", &(s[i]));
  }
  vector<vector<int> >dp(4, vector<int>(N+1, -1));
  //dp[0][0] = 0, dp[0][1] = 0
  dp[0][0] = 0; dp[0][N] = 0;
  dp[0][1] = 0;
  //dp[1][0] = 0, dp[1][1] = 1
  dp[1][0] = 0; dp[1][N] = 0;
  dp[1][1] = 1;
  //dp[2][0] = 1, dp[2][1] = 0
  dp[2][0] = 1; dp[2][N] = 1;
  dp[2][1] = 0;
  //dp[3][0] = 1, dp[3][1] = 1
  dp[3][0] = 1; dp[3][N] = 1;
  dp[3][1] = 1;  
  for (int x = 0; x < 4 ; x++){
    bool flag = true;
    for (int i = 1; i < N; i++){
      if (dp[x][i+1] == -1){
        if (dp[x][i] == 0){
          if (s[i] == 'o'){
            dp[x][i+1] = dp[x][i-1];
          }else{
            dp[x][i+1] = 1^dp[x][i-1];
          }
        }else{
          if (s[i] == 'o'){
            dp[x][i+1] = 1^dp[x][i-1];
          }else{
            dp[x][i+1] = dp[x][i-1];
          }
        }
      }else{
        if (dp[x][i] == 0){
          if (s[i] == 'o'){
            if (dp[x][i+1] != dp[x][i-1]){
              flag = false;
            }
          }else{
            if (dp[x][i+1] != (1^dp[x][i-1])){
              flag = false;
            }
          }
        }else{
          if (s[i] == 'o'){
            if (dp[x][i+1] != (1^dp[x][i-1])){
              flag = false;
            }
          }else{
            if (dp[x][i+1] != dp[x][i-1]){
              flag = false;
            }
          }
        }
      }
    }
    if (flag){
      if (dp[x][0] != dp[x][N]){
        continue;
      }else if (s[0] == 'o'){
        if (dp[x][0] == 0){
          if (dp[x][N-1] != dp[x][1]){
            continue;
          }
        }else{
          if (dp[x][N-1] != (1^dp[x][1])){
            continue;
          }
        }
      }else{
        if (dp[x][0] == 0){
          if (dp[x][N-1] != (1^dp[x][1])){
            continue;
          }
        }else{
          if (dp[x][N-1] != dp[x][1]){
            continue;
          }
        }
      }
      for (int i = 0; i < N; i++){
        printf("%c", (dp[x][i] == 0)?'S':'W');
      }
      printf("\n");
      return 0;
    }
  }
  printf("-1\n");
  return 0;
}

