void dfs(int pos, int kind){
	if(pos > n){
		return ;
	}
	if(flag) return ;
	ans[pos] = kind;
	if(pos == n){
		if(judge(kind,n)){
			flag = 1;
			return ;
		}
	}
	if(kind){ //当前为狼
		if(s[pos] == 'o'){ //左右两边种类不同
			dfs(pos+1, ans[pos-1]^1);
		}else{
			dfs(pos+1, ans[pos-1]);
		}
	}else{
		if(s[pos] == 'o'){
			dfs(pos+1, ans[pos-1]);
		}else{
			dfs(pos+1, ans[pos-1]^1);
		}
	}
}
