#include <bits/stdc++.h>
using namespace std;

#define REP(i,n) for(int i=0;i<(int)(n);i++)
#define ALL(x) (x).begin(), (x).end()

string solve(int N, const string& s) {
  vector<int> f(N);
  REP(i,N) f[i] = (s[i] == 'x') ? 1 : 0;
  REP(i,4) {
    vector<int> wolf(N);
    wolf[0] = i / 2;
    wolf[1] = i % 2;
    for(int j = 2; j < N; ++j) {
      if(wolf[j - 1] == f[j - 1]) wolf[j] = wolf[j - 2];
      else wolf[j] = 1 - wolf[j - 2];
    }
    if(((wolf[N - 2] == wolf[0]) == wolf[N - 1]) != f[N - 1]) continue;
    if(((wolf[N - 1] == wolf[1]) == wolf[0]) != f[0]) continue;
    string res;
    REP(j,N) res += (wolf[j] == 0) ? 'S' : 'W';
    return res;
  }
  return "-1";
}

int main(){
  int N;
  string s;
  cin >> N >> s;
  cout << solve(N, s) << endl;
  return 0;
}

