        clause.push_back(z);
        solver.addClause(clause);
        clause.clear();

        clause.push_back(x);
        clause.push_back(y);
        clause.push_back(z);
        solver.addClause(clause);
        clause.clear();

        clause.push_back(x);
        clause.push_back(-y);
        clause.push_back(-z);
        solver.addClause(clause);
        clause.clear();

      }else{

        clause.push_back(-x);
        clause.push_back(y);
        clause.push_back(z);
        solver.addClause(clause);
        clause.clear();

        clause.push_back(-x);
        clause.push_back(-y);
        clause.push_back(-z);
        solver.addClause(clause);
        clause.clear();

        clause.push_back(x);
        clause.push_back(y);
        clause.push_back(-z);
        solver.addClause(clause);
        clause.clear();

        clause.push_back(x);
        clause.push_back(-y);
        clause.push_back(z);
        solver.addClause(clause);
        clause.clear();
      }
    }
    int res = solver.solve();
    if (res == 0){
      for (int i = 0; i < N; i++){
