bool get_grundy(std::string& str)
{
	char prev2 = str[0];
	char prev{};
	int index = -1;
	for (auto i : boost::irange(1, static_cast<int>(str.size())))
	{
		if (str[i] == '_')
		{
			continue;
		}
		else if (prev == char())
		{
			prev = str[i];
			index = i;
			continue;
		}
		else if (prev2 != str[i])
		{
			str[index] = '_';
			auto f = get_grundy(str);
			str[index] = prev;
			if (!f)
			{
				return true;
			}
		}
		prev2 = prev;
		prev = str[i];
		index = i;
	}
	return false;
}

