vector<int> solve(int s0, int s1)
{
	// 0 -> 羊　1 -> 狼
	vector<int> ans;
	ans.push_back(s0);
	ans.push_back(s1);
	// cout << ans[0];
	for(int i = 1; i < n - 1; i++){
		if(ans[i] == 0){
			if(s[i] == 'o') ans.push_back(ans[i - 1]);
			else ans.push_back((ans[i - 1] + 1) % 2);
		} else {
			if(s[i] == 'o') ans.push_back((ans[i - 1] + 1) % 2);
			else ans.push_back(ans[i - 1]);
		}
		// cout << ans[i];
	}
	// cout << endl;
	if(ans[0] == 0){
		if((s[0] == 'o' && ans[n - 1] != ans[1]) || (s[0] == 'x' && ans[n - 1] == ans[1])) return vector<int>();
	} else {
		if((s[0] == 'o' && ans[n - 1] == ans[1]) || (s[0] == 'x' && ans[n - 1] != ans[1])) return vector<int>();
	}
	if(ans[n - 1] == 0){
		if((s[n - 1] == 'o' && ans[n - 2] != ans[0]) || (s[n - 1] == 'x' && ans[n - 2] == ans[0])) return vector<int>();
	} else {
		if((s[n - 1] == 'o' && ans[n - 2] == ans[0]) || (s[n - 1] == 'x' && ans[n - 2] != ans[0])) return vector<int>();
	}
	return ans;
}

