using namespace std;

string hitsuji(string s) {
  string t;
  t.push_back('S');
  if (s[0] == 'o') t.push_back('S');
  else t.push_back('W');
  for (int i = 1; i < s.size() - 1; i++) {
    if (t[i] == 'S') {
      if (s[i] == 'o') t.push_back(t[i - 1]);
      else t.push_back((t[i - 1] == 'S') ? 'W' : 'S');
    } else {
      if (s[i] == 'x') t.push_back(t[i - 1]);
      else t.push_back((t[i - 1] == 'S') ? 'W' : 'S');
    }
  }
  //cout << t << endl;
  if (t[s.size() - 1] == 'S' && t[s.size() - 2] == t[0] && s[s.size() - 1] == 'o') {
    return t;
  }
  if (t[s.size() - 1] == 'W' && t[s.size() - 2] == t[0] && s[s.size() - 1] == 'x') {
    return t;
  }
  if (t[s.size() - 1] == 'S' && t[s.size() - 2] != t[0] && s[s.size() - 1] == 'x') {
    return t;
  }
  if (t[s.size() - 1] == 'W' && t[s.size() - 2] != t[0] && s[s.size() - 1] == 'o') {
    return t;
  }
  return "";
}

string ookami(string s) {
  string t;
  t.push_back('W');
  if (s[0] == 'o') t.push_back('S');
  else t.push_back('W');
  for (int i = 1; i < s.size() - 1; i++) {
    if (t[i] == 'S') {
      if (s[i] == 'o') t.push_back(t[i - 1]);
      else t.push_back((t[i - 1] == 'S') ? 'W' : 'S');
    } else {
      if (s[i] == 'x') t.push_back(t[i - 1]);
      else t.push_back((t[i - 1] == 'S') ? 'W' : 'S');
    }
  }
  if (t[s.size() - 1] == 'S' && t[s.size() - 2] == t[0] && s[s.size() - 1] == 'o') {
    return t;
  }
  if (t[s.size() - 1] == 'W' && t[s.size() - 2] == t[0] && s[s.size() - 1] == 'x') {
    return t;
  }
  if (t[s.size() - 1] == 'S' && t[s.size() - 2] != t[0] && s[s.size() - 1] == 'x') {
    return t;
  }
  if (t[s.size() - 1] == 'W' && t[s.size() - 2] != t[0] && s[s.size() - 1] == 'o') {
    return t;
  }
  return "";
}

int main() {
  int n;
  cin >> n;
  string s;
  cin >> s;
  string s1 = hitsuji(s);
  string s2 = ookami(s);
  if (s1.size() == 0 && s2.size() == 0) {
    cout << -1 << endl;
  } else if (s1.size()) {
    cout << s1 << endl;
  } else {
    cout << s2 << endl;
  }
  return 0;
}

