int main() {
    int n;
    string s;
    in(n, s);

    vector<vector<int>> a(4, vector<int>(n + 1));

    for (int k = 0; k < 4; ++k) {
        if (k & 1) {
            a[k][0] = 0;
        } else {
            a[k][0] = 1;
        }

        if (k & 2) {
            a[k][1] = 0;
        } else {
            a[k][1] = 1;
        }

        for (int i : rep(1, n)) {
            if (a[k][i] == 0) {
                if (s[i] == 'o') {
                    a[k][i + 1] = a[k][i - 1];
                } else {
                    a[k][i + 1] = !a[k][i - 1];
                }
            } else if (a[k][i] == 1) {
                if (s[i] == 'o') {
                    a[k][i + 1] = !a[k][i - 1];
                } else {
                    a[k][i + 1] = a[k][i - 1];
                }
            }
        }

        if (a[k][0] == a[k][n]) {
            if (a[k][0] == 0) {
                if (s[0] == 'o') {
                    if (a[k][1] != a[k][n - 1]) {
                        continue;
                    }
                } else {
                    if (a[k][1] != a[k][n - 1]) {
                        continue;
                    }
                }
            } else if (a[k][0] == 1) {
                if (s[0] == 'o') {
                    if (a[k][1] == a[k][n - 1]) {
                        continue;
                    }
                } else {
                    if (a[k][1] != a[k][n - 1]) {
                        continue;
                    }
                }
            }

            string s;
            for (int i : rep(0, n)) {
                s.push_back(a[k][i] == 0 ? 'S' : 'W');
            }

            out(s);
            return 0;
        }
    }

    out(-1);
}

