        }
        else
        {
            return who[(i+1) % A.size()] = who[(i-1+A.size()) % A.size()];
        }
    }
    else
    {
        if (A[i] == 'o')
        {
            return who[(i+1) % A.size()] = who[(i-1+A.size()) % A.size()];
        }
        else
        {
