//S: sheap, W: walf
//ans = 'o' or 'x'
char Next(char ans, char x, char y){
    if(x == 'S' && y == 'S'){
       if(ans == 'o'){
            return 'S';
       }else{
            return 'W';           
       }
    }else if(x == 'W' && y == 'S'){
       if(ans == 'o'){
            return 'W';
       }else{
            return 'S';           
       }
    }else if(x == 'S' && y == 'W'){
       if(ans == 'o'){
            return 'W';
       }else{
            return 'S';           
       }
    }else if(x == 'W' && y == 'W'){
       if(ans == 'o'){
            return 'S';
       }else{
            return 'W';           
       }
    }
    return 'x';
}

string func(string s, char first, char last, char checkF, char checkL){
    char next;
    string ans = "";
    ans.push_back(first); 
    REP(i, s.size()){
        next = Next(s[i], last, first);
        if(i != s.size()-1){
            ans.push_back(next);
        }
        last = first;
        first = next;
    }
    if(first == checkF && last == checkL){
        return ans;
    }else{
        return "-1";
    }
}

