char *search(char a, char b, char *s, int N) {
  char *ans = (char *)malloc(N + 2);
  ans[0] = a;
  ans[1] = b;
  for (int i = 0; i < N - 1; i++) {
    if (s[i + 1] == 'o' && ans[i + 1] == 'S') {
      ans[i + 2] = ans[i];
    } else if (s[i + 1] == 'x' && ans[i + 1] == 'W') {
      ans[i + 2] = ans[i];
    } else {
      if (ans[i] == 'S') {
        ans[i + 2] = 'W';
      } else {
        ans[i + 2] = 'S';
      }
    }
  }
  if (s[0] == 'o' && ans[0] == 'S') {
    ans[N + 1] = ans[1];
  } else if (s[0] == 'x' && ans[0] == 'W') {
    ans[N + 1] = ans[1];
  } else {
    if (ans[1] == 'S') {
      ans[N + 1] = 'W';
    } else {
      ans[N+1] = 'S';
    }
  }
  if (ans[N-1] == ans[N + 1] && ans[0] == a[N]) {
    ans[N] = '\0';
    ans[N + 1] = '\0';
    return ans;
  } else {
    return NULL;
  }
  free(ans);
}

