using namespace std;
bool conf[100005];
string s;
bool didIt;
int n;

void solve() {
    if (didIt) return;
    static int bla = 0;
    bla++;
    for (int i = 1; i < n - 2; i++) {
        if ((!conf[i] && s[i] == 'o') || (conf[i] && s[i] == 'x'))
            conf[i + 1] = conf[i - 1];
        else
            conf[i + 1] = !conf[i - 1];
    }
    int i = n - 2;

    if ((!conf[i] && s[i] == 'o') || (conf[i] && s[i] == 'x'))
        if (conf[i - 1] != conf[i + 1]) return;
    else
        if (conf[i - 1] == conf[i + 1]) return;

    i = n - 1;
    if ((!conf[i] && s[i] == 'o') || (conf[i] && s[i] == 'x')) {
        if (conf[i - 1] != conf[0]) return;
    }
    else
        if (conf[i - 1] == conf[0]) return;

    didIt = true;
    cout << bla << endl;
    for (int i = 0; i < n; i++) {
        if (conf[i]) cout << 'W';
        else cout << 'S';
    }
    cout << endl;

}


