        conf[n - 1] = 0;
        solve();
        conf[1] = 1;
        conf[n - 1] = 1;
        solve();
    }
    else {
        conf[1] = 0;
        conf[n - 1] = 1;
        solve();
        conf[1] = 1;
        conf[n - 1] = 0;
        solve();
    }

    if (!didIt) cout << -1 << endl;


    return 0;
}

