        if(S[0] == 'x' && res[N-1] != res[1]) ok = false;
    }
    for(int i=1;i<N;i++){
        if(res[i] == 'S'){
            if(S[i] == 'o' && res[i-1] != res[(i+1)%N]) ok = false;
            if(S[i] == 'x' && res[i-1] == res[(i+1)%N]) ok = false;
        }
        else {
            if(S[i] == 'o' && res[i-1] == res[(i+1)%N]) ok = false;
            if(S[i] == 'x' && res[i-1] != res[(i+1)%N]) ok = false;
        }
    }

    //cout << res << endl;

    if(!ok) return "-1";
    return res;
}

