{
    zoo[0] = first;
    zoo[1] = second;
    for (int i = 2; i < N; i++) {
        if (s[i - 1] == 'o') {
            if (zoo[i - 1] == 'S') {
                if (zoo[i - 2] == 'S') {
                    zoo[i] = 'S';
                } else {
                    zoo[i] = 'W';
                }
            } else {
                if (zoo[i - 2] == 'S') {
                    zoo[i] = 'W';
                } else {
                    zoo[i] = 'S';
                }
            }
        } else {
            if (zoo[i - 1] == 'S') {
                if (zoo[i - 2] == 'S') {
                    zoo[i] = 'W';
                } else {
                    zoo[i] = 'S';
                }
            } else {
                if (zoo[i - 2] == 'S') {
                    zoo[i] = 'S';
                } else {
                    zoo[i] = 'W';
                }
            }
        }
    }

    if (zoo[N - 1] == 'S') {
        if (s[N - 1] == 'o') {
            return zoo[N - 2] == zoo[0];
        } else {
            return zoo[N - 2] != zoo[0];
        }
    } else {
        if (s[N - 1] == 'o') {
            return zoo[N - 2] == zoo[0];
        } else {
            return zoo[N - 2] == zoo[0];
        }
    }
}

