int main() {
	ll N;
	scanf("%lld", &N);
	char s[101010];
	scanf("%s", s);

	vector<vector<char>> dp(N + 1, vector<char>(4, 0));
	dp[0][0] = 'S';
	dp[0][1] = 'S';
	dp[0][2] = 'W';
	dp[0][3] = 'W';
	dp[1][0] = 'S';
	dp[1][1] = 'W';
	dp[1][2] = 'S';
	dp[1][3] = 'W';

	for (ll i = 2; i < N + 1; i++) {
		for (ll j = 0; j < 4; j++) {
			ll count = 0;

			if (dp[i - 2][j] == 'S') {
				count++;
			}

			if (dp[i - 1][j] == 'S') {
				count++;
			}

			if (s[i - 1] == 'o') {
				count++;
			}

			dp[i][j] = (count % 2 == 0) ? 'W' : 'S';
		}
	}

	for (ll j = 0; j < 4; j++) {
		if (dp[N][j] == dp[0][j]) {
			ll count = 0;

			if (dp[N - 1][j] == 'S') {
				count++;
			}

			if (dp[0][j] == 'S') {
				count++;
			}

			if (dp[1][j] == 'S') {
				count++;
			}

			if (s[0] == 'o') {
				count++;
			}

			if (count % 2 == 0) {
				for (ll i = 0; i < N; i++) {
					printf("%c", dp[i][j]);
				}
				printf("\n");

				return 0;
			}
		}
	}

	ll result = -1;

	printf("%lld\n", result);
}


