#define for1(i, n) for (int i = 1; i < int(n); ++i)

int n;
string s;

void turn(vector<char>& a, int i) {
	if (a[i - 1] == 'S')
		a[i + 1] = 'W';
	else
		a[i + 1] = 'S';
}

bool sim(vector<char>& a) {
	for1(i, n - 1) {
		if (a[i] == 'S') {
			if (s[i] == 'o')
				a[i + 1] = a[i - 1];
			else
				turn(a, i);
		}
		else {
			if (s[i] == 'x')
				a[i + 1] = a[i - 1];
			else
				turn(a, i);
		}
	}

	if (a[0] == 'S')
		if (s[0] == 'o' && a.back() != a[1] || s[0] == 'x' && a.back() == a[1])
			return false;

	if (a[0] == 'W')
		if (s[0] == 'x' && a.back() != a[1] || s[0] == 'o' && a.back() == a[1])
			return false;

	if (a.back() == 'S')
		if (s.back() == 'o' && a[0] != a[n - 2] || s.back() == 'x' && a[0] == a[n - 2])
			return false;

	if (a.back() == 'W')
		if (s.back() == 'x' && a[0] != a[n - 2] || s.back() == 'o' && a[0] == a[n - 2])
			return false;

	return true;
}

void print(vector<char>& a) {
	forn(i, n)
		cout << a[i];
	cout << endl;
}

