	if (sim(a)) {
		print(a);
		return 0;
	}

	if (sim(b)) {
		print(b);
		return 0;
	}

	if (sim(c)) {
		print(c);
		return 0;
	}

	if (sim(d)) {
		print(d);
		return 0;
	}

	cout << -1 << endl;
}

