bool translate(int n, string s, string in)
{
	ss = in;
	s = s + s[0];
	for(int i=1; i<n+1; i++) {
		if(ss[i] == 'S') {
			if(s[i] == 'o')
				ss = ss + ss[i-1];
			else {
				char ch = 'W' ^ 'S' ^ ss[i-1];
				ss = ss + ch;
			}
		}
		else {
			if(s[i] == 'o') {
				char ch = 'W' ^ 'S' ^ ss[i-1];
				ss = ss + ch;
			}
			else
				ss = ss + ss[i-1];
		}
	}

	if(ss[0] == ss[n] && ss[1] == ss[n+1])
		ss[n] = '\0';
	else
		return false;
	return true;
}

