        v[i+1] = v[i-1];
      } else {
        v[i+1] = 1 - v[i-1];
      }
    }
  }

  int i = N-1;
  if (v[i] == 0) {
    if (s[i] == 'o') {
      if (v[0] != v[i-1]) {
        return false;
      }
    } else {
      if (v[0] != 1-v[i-1]) {
        return false;
      }
    }
  } else {
    if (s[i] == 'x') {
      if (v[0] != v[i-1]) {
        return false;
      }
    } else {
      if (v[0] != 1-v[i-1]) {
        return false;
      }
    }
  }

  i = 0;
  if (v[i] == 0) {
    if (s[i] == 'o') {
      if (v[i+1] != v[N-1]) {
        return false;
      }
    } else {
      if (v[i+1] != 1-v[N-1]) {
        return false;
      }
    }
  } else {
    if (s[i] == 'x') {
      if (v[i+1] != v[N-1]) {
        return false;
      }
    } else {
      if (v[i+1] != 1-v[N-1]) {
        return false;
      }
    }
  }

  return true;
}


