int valid(int t1, int t2, int t3){
    res[1] = t1; res[2] = t2; res[3] = t3;
    for(int i=3; i<n; i++){
        if(res[i]){
            if(a[i]) res[i+1] = res[i-1];
            else res[i+1] = !res[i-1];
        }
        else{
            if(!a[i]) res[i+1] = res[i-1];
            else res[i+1] = !res[i-1];
        }
    }
    for(int i=1; i<=n; i++){
        int j = i-1 > 0 ? i-1 : n;
        int k = i+1 <= n ? i+1 : 1;
        if(res[i]){
            if(a[i] && res[j] != res[k]) return 0;
            if(!a[i] && res[j] == res[k]) return 0;
        }
        else{
            if(!a[i] && res[j] != res[k]) return 0;
            if(a[i] && res[j] == res[k]) return 0;
        }
    }
    for(int i=1; i<=n; i++) cout << (res[i] ? 'S' : 'W');
    return 1;
}

