int n;
string s;

bool solve(string &t){
    for(int i = 1; i < n; i++){
        if(s[i] == 'o'){
            if(t[i] == 'W'){
                if(t[i - 1] == 'S') t.pb('W');
                else t.pb('S');
            }
            else{
                if(t[i - 1] == 'S') t.pb('S');
                else t.pb('W');
            }
        }
        else{
            if(t[i] == 'W'){
                if(t[i - 1] == 'S') t.pb('S');
                else t.pb('W');
            }
            else{
                if(t[i - 1] == 'S') t.pb('W');
                else t.pb('S');
            }
        }
    }
    return t.back() == t.front();
}

