  FORN(i, n) answers[i] = (s[i] == 'o'); // yes = o, no = x
//  printf("answers: "); FORN(i, n) printf("%c ", s[i]); printf("\n");
//  printf("answers: "); FORN(i, n) printf("%d ", answers[i]); printf("\n");

  if (traverse(1, 1)) {printans(); return 0;}
  if (traverse(1, 0)) {printans(); return 0;}
  if (traverse(0, 1)) {printans(); return 0;}
  if (traverse(0, 0)) {printans(); return 0;}
  printf("-1\n"); return 0;
}

