bool possible(int N, string S, char first, char second, char* s) {
  s[0] = first;
  s[1] = second;
  for(int i = 1; i < N - 1; i++) {
    bool same = false;
    if(s[i] == 'S' && S[i] == 'o') 
      same = true;

    if(s[i] == 'W' && S[i] == 'x')
      same = true;

    if(same)
      s[i + 1] = s[i - 1];
    else
      s[i + 1] = rev(s[i - 1]);
  }

  bool same = false;

  if(s[N - 1] == 'S' && S[N - 1] == 'o')  same = true;
  if(s[N - 1] == 'W' && S[N - 1] == 'x')  same = true;

  if(same && s[N - 2] != s[0])
    return false;
  if(!same && s[N - 2] == s[0])
    return false;

  same = false;
  if(s[0] == 'S' && S[0] == 'o') same = true;
  if(s[0] == 'W' && S[0] == 'x') same = true;

  if(same && s[1] != s[N - 1])
    return false;
  if(!same && s[1] == s[N - 1])
    return false;

  return true;
}

