bool set_or_check(int i) {
  int prev = i-1 == -1 ? n-1 : i-1;
  int next = i+1 ==  n ?   0 : i+1;

  assert(r[i] != 'Z');
  if(r[next] == 'Z') { // set
    if ((s[i] == 'o' && r[i] == 'S') || (s[i] == 'x' && r[i] == 'W'))
      r[next] = r[prev];
    else
      r[next] = r[prev] == 'W' ? 'S' : 'W';
    return true;
  }
  else { // check
    if ((s[i] == 'o' && r[i] == 'S') || (s[i] == 'x' && r[i] == 'W'))
      return r[next] == r[prev];
    else
      return r[next] != r[prev];
  }
}

void chain() {
  rep(i, 1, n-2) assert(set_or_check(i));
  if(!set_or_check(n-2) || !set_or_check(n-1)) return;

  rep(i,n) cout << r[i];
  cout << endl;
  exit(0);
}

