      FILL(r, 'Z');
      r[0] = z, r[1] = r[n-1] = 'S';
      chain();

      FILL(r, 'Z');
      r[0] = z, r[1] = r[n-1] = 'W';
      chain();
    }
    else {
      FILL(r, 'Z');
      r[0] = z, r[1] = 'S', r[n-1] = 'W';
      chain();

      FILL(r, 'Z');
      r[0] = z, r[1] = 'W', r[n-1] = 'S';
      chain();
    }
  }
  cout << -1 << endl;
