#include <cstdio>
#include <algorithm>
using namespace std;

int n;
char ans[100003];
char out[100003];

char same(char c) {
	return c == 'S' ? 'S' : 'W';
}
char diff(char c) {
	return c == 'S' ? 'W' : 'S';
}

void assign(int i) {
	if (out[i] == 'S' && ans[i] == 'o') {
		out[i + 1] = same(out[i - 1]);
	}
	else if (out[i] == 'S' && ans[i] == 'x') {
		out[i + 1] = diff(out[i - 1]);
	}
	else if (out[i] == 'W' && ans[i] == 'o') {
		out[i + 1] = diff(out[i - 1]);
	}
	else {
		out[i + 1] = same(out[i - 1]);
	}
}

bool check(int i) {
	char ret;
	if (out[i] == 'S' && ans[i] == 'o') {
		ret = same(out[i - 1]);
	}
	else if (out[i] == 'S' && ans[i] == 'x') {
		ret = diff(out[i - 1]);
	}
	else if (out[i] == 'W' && ans[i] == 'o') {
		ret = diff(out[i - 1]);
	}
	else {
		ret = same(out[i - 1]);
	}
	return out[(i + 1) % n] == ret;
}

void proc() {
	scanf("%d", &n);
	scanf("%s", ans);

	for (char a : { 'S', 'W' }) {
		for (char b : { 'S', 'W' }) {
			out[0] = a;
			out[1] = b;
			for (int i = 1; i + 1 < n; ++i) {
				assign(i);
			}

			if (check(n - 1) && check(0)) {
				printf("%s", out);
				return;
			}
		}
	}
	printf("-1");
}

int main() {
	//freopen("input.txt", "r", stdin);
	proc();
	return 0;
}

