#include <iostream>
#include <string>
using namespace std;

enum Animal { WOLF, SHEEP };

Animal get_next(char c, Animal prev, Animal now) {
    bool x = prev == SHEEP;
    bool y = now == SHEEP;
    bool z = c == 'o';
    return (x == y == z) ? SHEEP : WOLF;
}

bool validate(Animal prev, Animal now, Animal next, char c) {
    bool w = prev == SHEEP;
    bool x = now == SHEEP;
    bool y = next == SHEEP;
    bool z = c == 'o';
    return w == x == y == z;
}

string solve(Animal prev, Animal now, string s, int n) {
    Animal first = prev, second = now;
    string ans(n, ' ');
    ans[0] = (prev == SHEEP) ? 'S' : 'W';
    for (int i = 1; i < n; i++) {
        Animal next = get_next(s[i], prev, now);
        prev = now;
        now = next;
        ans[i] = (prev == SHEEP) ? 'S' : 'W';
    }
    if (now != first) return "";
    if (!validate(prev, now, second, s[0])) return "";
    return ans;
}

int main() {
    int n;
    cin >> n;
    string s;
    cin >> s;
    Animal animals[] = {SHEEP, WOLF};
    for (auto first: animals) {
        for (auto second: animals) {
            string ans = solve(first, second, s, n);
            if (ans != "") {
                cout << ans << endl;
                return 0;
            }
        }
    }
    cout << "-1" << endl;
    return 0;
}

