using namespace std;


enum Animal {
  SHEEP = 0,
  WOLF = 1,
};


enum Answer {
  SAME = 0,
  DIFFER = 1,
};


constexpr int right(int left, int center, int answer)
{
  return (left + center + answer) % 2;
}


vector<int> animals(int fst, int snd, const vector<int>& answers)
{
  size_t size = answers.size();

  vector<int> ret;
  ret.reserve(size);

  ret.push_back(fst);
  ret.push_back(snd);

  for (size_t i=2; i<size; ++i) {
    int r = right(ret[i-2], ret[i-1], answers[i-1]);
    ret.push_back(r);
  }

  if ((ret[size-1] + ret[0] + ret[1] + answers[0]) % 2)
    ret.clear();
  else if ((ret[size-2] + ret[size-1] + ret[0] + answers[size-1]) % 2)
    ret.clear();

  return ret;
}


void show_animals(const vector<int>& animals)
{
  for (auto a : animals) {
    if (a == SHEEP)
      cout << 'S';
    else
      cout << 'W';
  }
  cout << endl;
}


