void solve() {
	int i,j,k,l,r,x,y; string s;

	cin>>N>>S;
	FOR(i,4) {
		if(i==0) T="SS";
		if(i==1) T="SW";
		if(i==2) T="WS";
		if(i==3) T="WW";
		for(j=1;j<N-1;j++) {
			if((T[j]=='S') ^ (S[j]=='o')){
				T.push_back('S'+'W'-T[j-1]);
			}
			else {
				T.push_back(T[j-1]);
			}
