vec<bool> str, ans;

void f(bool a, bool b) {
   ans.resize(n, false);
   ans[0] = a, ans[1] = b;
   repp (i, 1, n-1) {
      if (str[i]) { // oのとき
         if (ans[i]) { // 羊
            ans[i+1] = ans[i-1];
         } else { // 狼
            ans[i+1] = !ans[i-1];
         }
      } else { // xのとき
         if (ans[i]) { // 羊
            ans[i+1] = !ans[i-1];
         } else { // 狼
            ans[i+1] = ans[i-1];
         }
      }
   }
}

bool judge() {
   bool ok = true;
   if (str[n-1]) { // oのとき
      if (ans[n-1]) { // 羊
         if (ans[n-2] != ans[0]) ok = false;
      } else { // 狼
         if (ans[n-2] == ans[0]) ok = false;
      }
   } else { // xのとき
      if (ans[n-1]) { // 羊
         if (ans[n-2] == ans[0]) ok = false;
      } else { // 狼
         if (ans[n-2] != ans[0]) ok = false;
      }
   }

   if (str[0]) { // oのとき
      if (ans[0]) { // 羊
         if (ans[n-1] != ans[1]) ok = false;
      } else { // 狼
         if (ans[n-1] == ans[1]) ok = false;
      }
   } else { // xのとき
      if (ans[0]) { // 羊
         if (ans[n-1] == ans[1]) ok = false;
      } else { // 狼
         if (ans[n-1] != ans[1]) ok = false;
      }
   }

   return ok;
}

void print() { rep (i, n) { cout << (ans[i]?'S':'W'); } cout << endl; }

