   rep (i, n) {
      str[i] = s[i]=='o'?true:false;
   }

   rep (i, 2) {
      rep (j, 2) {
         f(i, j);
         if (judge()) {
            print();
            return 0;
         }
      }
   }

   printf("%d\n", -1);

   return 0;
}

