void end_(string t)
{
	for(int i=0;i<t.size();i++)
		putchar(t[i]);
	exit(0);
}
char change(char c)
{
	if(c=='S')
		return 'W';
	else
		return 'S';
}
void dfs(int now,string t)
{
	if(now==n-2)
	{
		if(s[n-1]=='o'&&t[n-2]=='W'&&t[0]=='W'&&t[n-1]=='S')end_(t);
		if(s[n-1]=='o'&&t[n-2]=='S'&&t[0]=='S'&&t[n-1]=='S')end_(t);
		if(s[n-1]=='o'&&t[n-2]=='S'&&t[0]=='W'&&t[n-1]=='W')end_(t);
		if(s[n-1]=='o'&&t[n-2]=='S'&&t[0]=='S'&&t[n-1]=='S')end_(t);
		if(s[n-1]=='x'&&t[n-2]=='S'&&t[0]=='W'&&t[n-1]=='S')end_(t);
		if(s[n-1]=='x'&&t[n-2]=='S'&&t[0]=='S'&&t[n-1]=='W')end_(t);
		if(s[n-1]=='x'&&t[n-2]=='W'&&t[0]=='W'&&t[n-1]=='W')end_(t);
		if(s[n-1]=='x'&&t[n-2]=='W'&&t[0]=='S'&&t[n-1]=='S')end_(t);
		return;
	}
	int bef=now-1;
	if(now==0)bef=n-1;
	int to=(now+1)%n;
	if(t[now]=='S')
	{
		if(s[now]=='x')t[to]=change(t[bef]);
		else t[to]=t[bef];
	}
	else
	{
		if(s[now]=='o')t[to]=change(t[bef]);
		else t[to]=t[bef];
	}
	dfs(now+1,t);
}
int main()
{
	cin>>n>>s;
	string t=s;
	if(s[0]=='x')
	{
		t[0]='S';
		t[n-1]='S';
		t[1]='W';
		dfs(0,t);
		t[n-1]='W';
		t[1]='S';
		dfs(0,t);
		t[0]='W';
		t[n-1]=t[1]='S';//狼羊 
		dfs(0,t);
		t[n-1]=t[1]='W';//狼狼 
		dfs(0,t);
	}
	else
	{
		t[0]='W';
		t[n-1]='S';
		t[1]='W';
		dfs(0,t);
		t[n-1]='W';
		t[1]='S';
		dfs(0,t);
		t[0]='S';
		t[n-1]=t[1]='S';
		dfs(0,t);
		t[n-1]=t[1]='W';
		dfs(0,t);
	}
	cout<<"-1\n";
