#include <cstdio>

int N;
char s[100010];
char t[100010];

int suc()
{
	int i;
	for(i=2; i<N; i++){
		if(t[i-1] == 's'){
			if(s[i-1] == 'o')
				t[i] = t[i-2];
			else{
				if(t[i-2] == 's')
					t[i] = 'w';
				else
					t[i] = 's';
			}
		}
		else{
			if(s[i-1] == 'x')
				t[i] = t[i-2];
			else{
				if(t[i-2] == 's')
					t[i] = 'w';
				else
					t[i] = 's';
			}
		}
	}
	if(t[N-1] == 's'){
		if(s[N-1] == 'o'){
			if(t[N-2] != t[0])
				return 0;
		}
		else{
			if(t[N-2] == t[0])
				return 0;
		}
	}
	else{
		if(s[N-1] == 'o'){
			if(t[N-2] == t[0])
				return 0;
		}
		else{
			if(t[N-2] != t[0])
				return 0;
		}
	}
	if(t[0] == 's'){
		if(s[0] == 'o'){
			if(t[N-1] != t[1])
				return 0;
		}
		else{
			if(t[N-1] == t[1])
				return 0;
		}
	}
	else{
		if(s[0] == 'o'){
			if(t[N-1] == t[1])
				return 0;
		}
		else{
			if(t[N-1] != t[1])
				return 0;
		}
	}
	return 1;
}

void solve()
{
	int i;
	t[0] = 's';
	t[1] = 's';
	if(suc() ){
		printf("%s\n", t);
		return ;
	}
	t[0] = 's';
	t[1] = 'w';
	if(suc() ){
		printf("%s\n", t);
		return ;
	}
	t[0] = 'w';
	t[1] = 's';
	if(suc() ){
		printf("%s\n", t);
		return ;
	}
	t[0] = 'w';
	t[1] = 'w';
	if(suc() ){
		printf("%s\n", t);
		return ;
	}
	printf("-1\n");
}

int main()
{
	scanf("%d", &N);
	scanf("%s", s);
	solve();
	return 0;
}

