int main(){
//	freopen("input.inp", "r", stdin);
	scanf("%d%s",&n,&s);
	for(int p = 0; p < 2; ++p){
		for(int q = 0; q < 2; ++q){
			if (p == 0) an[0] = 'W'; else an[0] = 'S';
			if (q == 0) an[1] = 'W'; else an[1] = 'S';
			for(int i = 2; i < n; ++i){
				if (an[i - 1] == 'S' && s[i - 1] == 'o') an[i] = an[i - 2];
				if (an[i - 1] == 'S' && s[i - 1] == 'x'){
					if (an[i - 2] == 'W') an[i] = 'S';
					else an[i] = 'W';
				}
				if (an[i - 1] == 'W' && s[i - 1] == 'x') an[i] = an[i - 2];
				if (an[i - 1] == 'W' && s[i - 1] == 'o'){
					if (an[i - 2] == 'W') an[i] = 'S';
					else an[i] = 'W';					
				}
			}
			if (an[0] == 'S' && s[0] == 'o' && an[n - 1] != an[1]) continue;
			if (an[0] == 'S' && s[0] == 'x' && an[n - 1] == an[1]) continue;
			if (an[0] == 'W' && s[0] == 'o' && an[n - 1] == an[1]) continue;
			if (an[0] == 'W' && s[0] == 'x' && an[n - 1] != an[1]) continue;
			if (an[n - 1] == 'S' && s[n - 1] == 'o' && an[n - 2] != an[0]) continue;
			if (an[n - 1] == 'S' && s[n - 1] == 'x' && an[n - 2] == an[0]) continue;
			if (an[n - 1] == 'W' && s[n - 1] == 'o' && an[n - 2] == an[0]) continue;
			if (an[n - 1] == 'W' && s[n - 1] == 'x' && an[n - 2] != an[0]) continue;			
			printf("%s",an);
			return 0;
		}
	}
	printf("-1");
	return 0;
}

#include <bits/stdc++.h>
using namespace std;

int n;
string s;
bool ok(vector<bool> &is_sheep, bool s1, bool s2) {
  is_sheep[0] = s1;
  is_sheep[1] = s2;
  for (int i=1; i<n-1; i++) {
    if (is_sheep[i]) {
      if (s[i] == 'o') {
        is_sheep[i+1] = is_sheep[i-1];
      } else {
        is_sheep[i+1] = !is_sheep[i-1];
      }
    } else {
      if (s[i] == 'o') {
        is_sheep[i+1] = !is_sheep[i-1];
      } else {
        is_sheep[i+1] = is_sheep[i-1];
      }
    }
  }
  if (is_sheep[n-1]) {
    if (s[n-1] == 'o') {
      return is_sheep[0] == is_sheep[n-2];
    } else {
      return is_sheep[0] != is_sheep[n-2];
    }
  } else {
    if (s[n-1] == 'o') {
      return is_sheep[0] != is_sheep[n-2];
    } else {
      return is_sheep[0] == is_sheep[n-2];
    }
  }
}
int main() {
  cin>>n;
  cin>>s;
  vector<bool> is_sheep(n);
  bool state[2] = {true, false};
  for (bool s1: state) {
    for (bool s2: state) {
      if (ok(is_sheep, s1, s2)) {
        for (bool b: is_sheep) {
          if (b) {
            cout<<"S";
          } else {
            cout<<"W";
          }
        }
        cout<<endl;
        return 0;
      }
    }
  }
  cout<<-1<<endl;
}

