int n;
int A[N],ans[N];

bool check(int i){
  int l = (i+n-1)%n,r = (i+1)%n;
  if(ans[i]==0){
    if(A[i] == 1) return ans[l]==ans[i]&&ans[r]==ans[i];
    if(A[i] == 0) return !(ans[l]==ans[i]&&ans[r]==ans[i]);
  }
  if(ans[i]==1){
    if(A[i] == 1) return !(ans[l]==ans[i]&&ans[r]==ans[i]);
    if(A[i] == 0) return ans[l]==ans[i]&&ans[r]==ans[i];
  }
}

bool check(){
  for(int i=0;i<n;i++)if(!check(i))return 0;
  return 1;
}

int dfs(int pos,int cnt){
  if(cnt==n)return check();
  if(A[pos]){ //o
    if(ans[pos] == 0 ) ans[pos+1] = 0;
    else ans[pos+1] = !ans[(pos+n-1)%n];
    if(dfs((pos+1)%n,cnt+1))return 1;
  }
  else {     //x
    if(ans[pos] == 0 )ans[pos+1] = !ans[(pos+n-1)%n];
    if(ans[pos] == 1 ) ans[pos+1] = 1;
    if(dfs((pos+1)%n,cnt+1))return 1;
  }
  return 0;
}

int idx=0;
void pr(){
  char ch[]={'S','W'};
  for(int i=0;i<n;i++)cout<<ch[ans[i]];
