  for(int i=0;i<n;i++) if(A[i]==1) idx=i;
  if(idx==n){cout<<-1<<endl;return 0;}
  ans[idx] = 0;
  ans[(idx-n-1)%n] = 0;

  if(dfs(0,0)) pr();

  idx=0;
  for(int i=0;i<n;i++) if(A[i]==0) idx=i;
  ans[idx] = 1;
  ans[(idx-n-1)%n] = 1;

