	int N;
	string str;
	cin >> N >> str;
	vector<bool> ans(N);
	vector<bool> res(N);
	for(int i=0;i<N;++i){
		ans[i] = str[i] == 'x';
	}
	bool flag;
	for(int i=0;i<4;++i){
		flag = true;
		res[0] = (i/2)>0;
		res[1] = (i%2)>0;
		for(int j=1;j+1<N;++j){
			res[(j+1)%N] = (res[(j)%N]+res[(j+N-1)%N]+ans[j] )%2 > 0;
		}
		for(int j=N-3;j<N;++j){
			if( (res[(j+N-1)%N]+res[j%N]+res[(j+1)%N])%2 > 0 != ans[j%N] ){
				flag = false;
				break;
			}
		}
		if( flag ){
			for(int j=0;j<N;++j){
				if( res[j] ){
					cout << "W";
				}else{
					cout << "S";
				}
			}
			cout << endl;
			return;
		}
	}
	cout << -1 << endl;
}

