using namespace std;

char different(char c) {
    return c=='S' ? 'W' : 'S';
}

char neg(char c) {
    return c=='o' ? 'x' : 'o';
}

char gen(char prev, char says) {
    return says=='o' ? prev : different(prev);
}

char normalize(char who, char says) {
    return who=='W' ? neg(says) : says;
}

string gen_str(string ptn, int n, char fst, char snd) {
    string res(n, ' ');
    res[0] = fst;
    res[1] = snd;
    for(int i=2; i<n; i++) {
        res[i] = gen(res[i-2], normalize(res[i-1], ptn[i-1]));
    }
    return res;
}

bool judge(string ptn, string ans, int n) {
    return gen(ans[1], normalize(ans[0], ptn[0])) == ans[n-1] && gen(ans[n-2], normalize(ans[n-1], ptn[n-1])) == ans[0];
}

int main() {
    int n;
    string s;
    cin >> n;
    cin >> s;
    string r;
    r = gen_str(s, n, 'S', 'S');
    if(judge(s, r, n)) {
        cout << r << endl;
        return 0;
    }
    r = gen_str(s, n, 'S', 'W');
    if(judge(s, r, n)) {
        cout << r << endl;
        return 0;
    }
    r = gen_str(s, n, 'W', 'W');
    if(judge(s, r, n)) {
        cout << r << endl;
        return 0;
    }
    r = gen_str(s, n, 'W', 'S');
    if(judge(s, r, n)) {
        cout << r << endl;
        return 0;
    }
    cout << "-1" << endl;
}

