using namespace std;

using Vector = vector<bool>;

template<typename T>
T mod(T i, T N)
{
  return (i + N) % N;
}

bool is_okay(
  const Vector& answers,
  const Vector& animals,
  const Vector& determined, size_t now
) {
  const auto N = animals.size();
  auto next = mod(now + 1, N);
  auto prev = mod(now - 1, N);

  if (!determined[now] or !determined[next] or !determined[prev]) return true;
  if (animals[now]) {
    // sheep
    return
      (answers[now] and animals[prev] == animals[next]) or
      (!answers[now] and animals[prev] != animals[next]);
  } else {
    // wolf
    return
      (answers[now] and animals[prev] != animals[next]) or
      (!answers[now] and animals[prev] == animals[next]);
  }
}

bool traverse(const Vector& answers, Vector& animals, Vector& determined) {
  const auto N = animals.size();

  /*
  for (size_t i = 0; i < N; ++i) {
    cout << (determined[i] ? (animals[i] ? 'S' : 'W') : '?');
  }
  cout << endl;
  */

  bool values[] = {false, true};
  for (size_t now = 0; now < N; ++now) {
    if (!determined[now]) {
      auto next = mod(now + 1, N);
      auto prev = mod(now - 1, N);
      determined[now] = true;
      for (int i = 0; i < 2; ++i) {
        animals[now] = values[i];
        if (is_okay(answers, animals, determined, now) and
            is_okay(answers, animals, determined, prev) and
            is_okay(answers, animals, determined, next)) {
          if (traverse(answers, animals, determined)) return true;
        }
      }
      determined[now] = false;
      return false;
    }
  }
  for (size_t now = 0; now < N; ++now) {
    cout << (animals[now] ? 'S' : 'W');
  }
  return true;
}

int main()
{
  int N;
  cin >> N;
  Vector answers(N);
  Vector animals(N);
  Vector determined(N, false);

  for (int i = 0; i < N; ++i) {
    char c;
    cin >> c;
    answers[i] = c == 'o' ? true : false;
  }

  if (!traverse(answers, animals, determined)) cout << -1;
  cout << endl;

  return 0;
}

