int N;
string s;
vector<char> ans;

bool solve(char zero,char one,char last){
    ans.assign(N,'-');
    ans[0] = zero;
    ans[1] = one;
    for(int i=1;i<N-1;i++){
        char tc = s[i];
        if(ans[i]=='W'){
            if(s[i]=='o') tc = 'x';
            else tc = 'o';
        }

        if(tc=='o'){
            ans[i+1] = ans[i-1];
        }else{
            if(ans[i-1]=='W'){
                ans[i+1] = 'S';
            }else{
                ans[i+1] = 'W';
            }
        }
    }
    //cout << zero << " " << one << " " << last << " " << (ans[N-1] == last) << endl;
    if(ans[N-1]!=last) return false;

    if(ans[N-1]=='S'){
        if(s[N-1]=='o' and ans[0]!=ans[N-2]) return false;
        if(s[N-1]=='x' and ans[0]==ans[N-2]) return false;
    }else{
        if(s[N-1]=='x' and ans[0]!=ans[N-2]) return false;
        if(s[N-1]=='o' and ans[0]==ans[N-2]) return false;
    }
    return true;
}

int main(){
    cin >> N >> s;

    if(s[0] == 'o'){
        if(solve('S','S','S') or solve('S','W','W') or solve('W','S','W') or solve('W','W','S')){
            rep(i,N) cout << ans[i];
            cout << endl;
            return 0;
        }
    }else{
        if(solve('S','S','W') or solve('S','W','S') or solve('W','W','W') or solve('W','S','S')){
            rep(i,N) cout << ans[i];
            cout << endl;
            return 0;
        }
    }
    cout << -1 << endl;
}

