using namespace utils;

class solver{
    istream& is;
    ostream& os;

public:
    solver(istream& I, ostream& O) :is(I), os(O) {}
    ll N;
    string S;
    vector<int> V;
    void run();

    bool check(){
        for (int i = 1; i < N-1; ++i) {
            assert(V[i] != -1);
            int pre = i-1;
            int next = i+1;
            V[next] = V[pre] ^ (S[i] == 'o') ^ !V[i];
        } // end i

        for (int i = 0; i < N; ++i) {
            int pre = i-1; if(pre < 0) pre += N;
            int next = i+1; if(next >= N) next -= N;
            if(V[next] == V[pre] xor S[i] == 'o' xor V[i]){
                return false;
            }
        } // end i
        return true;

    }

};

