}


void solver::run(){
    is >> N;
    if(!is) return;
    is >> S;
    for (int i = 0; i < 4; ++i) {
        V = make_mdvector(N, -1);
        V[0] = (i & 1) >= 1;
        V[1] = (i & 2) >= 1;
        if(check()) {
            for (auto &&v : V) {
                os << (v ? 'W' : 'S');
            } // end v
            os << endl;
            return;
        }
    } // end i
    os << -1 << endl;


}

