bool f(int a, int b, string &S) {
  int N = S.size();
  vector<int> kind(N, -1);
  kind[0] = a, kind[1] = b;
  for (int i = 1; i <= N; i++) {
    int r = (i + 1) % N;
    int l = (i + N - 1) % N;
    int newk;
    if (((kind[i % N] == 0) ^ (S[i % N] == 'o')) == 0) {
      newk = kind[l];
    } else {
      newk = 1 - kind[l];
    }
    if (kind[r] == -1) {
      kind[r] = newk;
    } else {
      if (kind[r] != newk) return false;
    }
  }
  for (int i = 0; i < N; i++) {
    if (kind[i] == 0) {
      cout << "S";
    } else {
      cout << "W";
    }
  }
  cout << endl;
}

int main() {
  int N;
  string S;
  cin >> N >> S;

  bool flag = false;
  for(int i = 0; i < 4; i++) {
    flag |= f(i & 1, i >> 1 & 1, S);
    if (flag) break;
  }
  if (!flag) {
    cout << -1 << endl;
  }
  return 0;
}

