using namespace std;

bool solve(string ans, string s, ll N) {
    for (ll i = 1; i <= N-1; i++) {
        string pre = ans.substr(i-1, 2);
        if (s[i] == 'o') {
            if (pre == "SS" || pre == "WW") ans += 'S';
            else ans += 'W';
        } else {
            if (pre == "WS" || pre == "SW") ans += 'S';
            else ans += 'W';
        }
    }

    if (ans[N] == ans[0]) {
        cout << ans.substr(0, N) << "\n";
        return true;
    } else return false;
}

int main(){
    cin.tie(0);
    ios::sync_with_stdio(false);

    ll N;
    string s;
    cin >> N >> s;

    if (solve("SS", s, N)) return 0;
    else if (solve("SW", s, N)) return 0;
    else if (solve("WS", s, N)) return 0;
    else if (solve("WW", s, N)) return 0;

    cout << -1 << "\n";
}

