string fill(int i, int n, string &s, string &result) {
	int prev = (i - 1 + n) % n;
	char kind = result[i];
	char prev_kind = result[prev];
	char answer = s[i];

	if (i == n - 1) {
		char next_kind = result[0];
		if (answer == 'o') {
			if ((kind == 'S' && prev_kind == next_kind) || 
				(kind == 'W' && prev_kind != next_kind)) {
				return result;
			} else {
				return "";
			}
		} else {
			if ((kind == 'S' && prev_kind != next_kind) ||
				(kind == 'W' && prev_kind == next_kind)) {
				return result;
			} else {
				return "";
			}
		}
	}

	if (answer == 'o') {
		if (kind == 'S') {
			result[i + 1] = prev_kind;
		} else {
			result[i + 1] = prev_kind == 'S' ? 'W' : 'S';
		}
	} else {
		if (kind == 'S') {
			result[i + 1] = prev_kind == 'S' ? 'W' : 'S';
		} else {
			result[i + 1] = prev_kind;
		}
	}

	return fill(i + 1, n, s, result);
}

