int N;
char s[100000];
int ans[100001];
int i = 1;
void result() {
	for (int j = 0; j < N; j++) {
		if (ans[j] == 1) {
			std::cout << "S";
		}
		else if (ans[j] == -1) {
			std::cout << "W";
		}
	}
	std::cout << std::endl;
}
bool solve(int one) {
	ans[i] = one;
	if (i == N) {
		if (ans[0] != ans[N]) {
			return false;
		}
		if (ans[0] == 1) {
			if (s[0] == 'o') {
				i = 1;
				return ans[1] == ans[N - 1];

			}
			else {
				i = 1;
				return ans[1] != ans[N - 1];
			}
		}
		else if (ans[0] == -1) {
			if (s[0] == 'o') {
				i = 1;
				return ans[1] != ans[N - 1];
			}
			else {
				i = 1;
				return ans[1] == ans[N - 1];
			}
		}
	}
	if (one == 1) {
		if (s[i] == 'o') {
			ans[i + 1] = ans[i - 1];
			i++;
			solve(ans[i]);
		}
		else {
			ans[i + 1] = -ans[i - 1];
			i++;
			solve(ans[i]);
		}
	}
	else if (one == -1) {
		if (s[i] == 'o') {
			ans[i + 1] = -ans[i - 1];
			i++;
			solve(ans[i]);
		}
		else {
			ans[i + 1] = ans[i - 1];
			i++;
			solve(ans[i]);
		}
	}
}
void zero() {
	for (int q = 0; q < N + 1; q++) {
		ans[q] = 0;
	}
}
int main() {
	std::cin >> N;
	for (int j = 0; j < N; j++) {
		std::cin >> s[j];
	}
	ans[0] = 1;
	if (solve(1)) {
		result();
		return 0;
	}
	else {
		zero();
	}
	ans[0] = 1;
	if (solve(-1)) {
		result();
		return 0;
	}
	else {
		zero();
	}
	ans[0] = -1;
	if (solve(1)) {
		result();
		return 0;
	}
	else {
		zero();
	}
	ans[0] = -1;
	if (solve(-1)) {
		result();
		return 0;
	}
	else {
		zero();
	}
	std::cout << -1 << std::endl;
	return 0;
}

