char *search(char a, char b, char *s, int N) {
  char *ans = (char *)malloc(N + 1);
  ans[0] = a;
  ans[1] = b;
  for (int i = 0; i < N - 1; i++) {
    if (s[i + 1] == 'o' && ans[i + 1] == 'S') {
      ans[i + 2] = ans[i];
    } else if (s[i + 1] == 'x' && ans[i + 1] == 'W') {
      ans[i + 2] = ans[i];
    } else {
      if (ans[i] == 'S') {
        ans[i + 2] = 'W';
      } else {
        ans[i + 2] = 'S';
      }
    }
  }
  if (ans[0] == ans[N]) {
    ans[N] = '\0';
    return ans;
  } else {
    return NULL;
  }
  free(ans);
}

