class Main {
public:
	string withAssumption(string says, string asp) {
		int n = says.size();
		string ans = asp;
		for (int i = 1;i < n;i++) {
			int li = (i + (n - 1)) % n;
			int ri = (i + 1) % n;

			if ((ans[i] == 'S' && says[i] == 'o') || (ans[i] == 'W' && says[i] == 'x')) { ans[ri] = ans[li]; }
			else { ans[ri] = (ans[li] == 'S') ? 'W' : 'S'; }
		}
		return ans[0] == asp[0] ? ans : "XX";
	}

	string getAns(string says) {
		int n = says.size();

		string ans;
		for (int i = 0;i < n;i++) {
			ans += "S";
		}

		ans[0] = 'S';
		ans[1] = 'S';
		ans = withAssumption(says, ans);
		if (ans[0] != 'X') return ans;

		ans[0] = 'S';
		ans[1] = 'W';
		ans = withAssumption(says, ans);
		if (ans[0] != 'X') return ans;

		ans[0] = 'W';
		ans[1] = 'S';
		ans = withAssumption(says, ans);
		if (ans[0] != 'X') return ans;

		ans[0] = 'W';
		ans[1] = 'W';
		ans = withAssumption(says, ans);
		if (ans[0] != 'X') return ans;

		return "X";
	}
};


