int N,ans = 0,M = -1;
char animal[4][NMAX],truth[NMAX];
char S[NMAX];
char dx[4][2];

int solve(int a){
	animal[a][0] = dx[a][0];
	animal[a][1] = dx[a][1];
	for (int i = 1; i < N-1; ++i)
	{
		if(animal[a][i] == 'S'){
			truth[i] = S[i];
		}else{
			if(S[i] == 'o'){
				truth[i] = 'x';
			}else{
				truth[i] = 'o';
			}
		}
		if(truth[i] == 'o'){
			if(animal[a][i-1] == 'S'){
				if(animal[a][i+1] != 'S'){
					return ans = -1;
				}
				animal[a][i+1] = 'S';
			}else{
				if(animal[a][i-1] != 'W'){
					return ans = -1;
				}
				animal[a][i+1] = 'W';
			}
		}else{
			if(animal[a][i-1] == 'S'){
				if(animal[a][i+1] != 'W'){
					return ans = -1;
				}
				animal[a][i+1] = 'W';
			}else{
				if(animal[a][i-1] != 'S'){
					return ans = -1;
				}
				animal[a][i+1] = 'S';
			}
		}
	}
	if(animal[a][N-1] == 'S'){
		truth[N-1] = S[N-1];
	}else{
		if(S[N-1] == 'o'){
			truth[N-1] = 'x';
		}else{
			truth[N-1] = 'o';
		}
	}
	if(truth[N-1] == 'o'){
		if(animal[a][N-2] == 'S'){
			if(animal[a][0] != 'S'){
				return ans = -1;
			}
			animal[a][0] = 'S';
		}else{
			if(animal[a][N-2] != 'W'){
				return ans = -1;
			}
			animal[a][0] = 'W';
		}
	}else{
		if(animal[a][N-2] == 'S'){
			if(animal[a][0] != 'W'){
				return ans = -1;
			}
			animal[a][0] = 'W';
		}else{
			if(animal[a][N-2] != 'S'){
				return ans = -1;
			}
			animal[a][0] = 'S';
		}
	}
	for (int j = 0; j < N; ++j)
	{
		cout << animal[a][j] << "\n";
	}
	cout << "\n";
	return ans = 0;
}

