    if (s[0] == 'x' && alist[0] == 'S') {
        if (alist[1] == alist[n-1]) return false;
    }
    if (s[0] == 'x' && alist[0] == 'W') {
        if (alist[1] != alist[n-1]) return false;
    }

    if (s[n-1] == 'o' && alist[n-1] == 'S') {
        if (alist[0] != alist[n-2]) return false;
    }
    if (s[n-1] == 'o' && alist[n-1] == 'W') {
        if (alist[0] == alist[n-2]) return false;
    }
    if (s[n-1] == 'x' && alist[n-1] == 'S') {
        if (alist[0] == alist[n-2]) return false;
