int Judge(const string s, string &ans) {
	for (int i = 1; i < s.size(); i++) {
		if (ans[i] == 'S') {
			if (s[i] == 'o')
				ans += ans[i - 1];
			else {
				if (ans[i - 1] == 'S')
					ans += "W";
				else
					ans += "S";
			}
		}
		else {
			if (s[i] == 'x')
				ans += ans[i - 1];
			else {
				if (ans[i - 1] == 'S')
					ans += "W";
				else
					ans += "S";
			}
		}
	}
	if (ans[0] == ans[ans.size() - 1])
		return true;
	return false;
}

