int n;
string s;
char ans[100001];

bool solve(char one, char two) {
  ans[0] = one;
  ans[1] = two;
  for (int i = 1; i < n - 1; i++) {
    if (ans[i] == 'S') {
      if (s[i] == 'o') ans[i + 1] = ans[i - 1];
      else ans[i + 1] = (ans[i - 1] == 'S'?'W':'S');
      continue;
    }
    if (s[i] == 'x') ans[i + 1] = ans[i - 1];
    else ans[i + 1] = (ans[i - 1] == 'S'?'W':'S');
  }
  bool ok = 1;
  if (ans[0] == 'S') {
    if (s[0] == 'o') {
      if (ans[1] != ans[n - 1]) ok = 0;
    } else {
      if (ans[1] == ans[n - 1]) ok = 0;
    }
  } else {
    if (s[0] == 'o') {
      if (ans[1] == ans[n - 1]) ok = 0;
    } else {
      if (ans[1] != ans[n - 1]) ok = 0;
    }
  }
  if (ans[n - 1] == 'S') {
    if (s[n - 1] == 'o') {
      if (ans[0] != ans[n - 2]) ok = 0;
    } else {
      if (ans[0] == ans[n - 2]) ok = 0;
    }
  } else {
    if (s[n - 1] == 'o') {
      if (ans[0] == ans[n - 2]) ok = 0;
    } else {
      if (ans[0] != ans[n - 2]) ok = 0;
    }
  }
  if (ok) return true;
  return false;
}

int main() {
#ifdef LOCAL_DEFINE
     setInput("in.txt");
     setOutput("out.txt");
     //setError("err.txt");
#endif
  read(n);
  setLength(n);
  read(s);
  if (solve('S', 'S')) {
    writeln(ans);
    return 0;
  }
  if (solve('S', 'W')) {
    writeln(ans);
    return 0;
  }
  if (solve('W', 'S')) {
    writeln(ans);
    return 0;
  }
  if (solve('W', 'W')) {
    writeln(ans);
    return 0;
  }
  writeln(-1);
#ifdef LOCAL_DEFINE
  cerr << "Time elapsed: " << 1.0 * clock() / CLOCKS_PER_SEC << "s.\n";
#endif
  return 0;
}

