bool judge(string &zoo) {
    bool check = true;
    rep(i, n) {
        if (i == 0) {
            if (s[i] == 'x') zoo[i + 1] = 'W';
        } else if (i == n - 1) {
            if (zoo[i] == 'S') {
                if (s[i] == 'x' && zoo[i - 1] == 'S') check = false;
                if (s[i] == 'o' && zoo[i - 1] == 'W') check = false;
            } else { // W
                if (s[i] == 'x' && zoo[i - 1] == 'W') check = false;
                if (s[i] == 'o' && zoo[i - 1] == 'S') check = false;
            }
        } else {
            if (s[i] == 'o') {
                if (zoo[i] == 'S') {
                    if (zoo[i - 1] != zoo[i + 1]) zoo[i + 1] = 'W';
                } else { // W
                    if (zoo[i - 1] == zoo[i + 1]) zoo[i + 1] = 'W';
                }
            } else { // x
                if (zoo[i] == 'S') {
                    if (zoo[i - 1] == zoo[i + 1]) zoo[i + 1] = 'W';
                } else { // W
                    if (zoo[i - 1] != zoo[i + 1]) zoo[i + 1] = 'W';
                }
            }
        }
    }
    if (check) return true;
    else return false;
}

