const int MaxN = 2e5;
int n, a[MaxN + 5];
char s[MaxN + 5];

void Print(int a[])
{
	for (int i = 1; i <= n; i++)
		if (a[i] == 1) printf("S");
			else printf("W");
	printf("\n");
}

bool Judge(char ch, int x)
{
	if (x == 1) return ch == 'o';
	else return ch == 'x';
}

bool Check(int a[])
{
	for (int i = 2; i <= n - 2; i++) 
		if (Judge(s[i - 1], a[i])) a[i + 1] = a[i - 1]; else a[i + 1] = 1 - a[i - 1];
	if (Judge(s[n - 2], a[n - 1]) && a[n - 2] != a[n]) return false;
	if (!Judge(s[n - 2], a[n - 1]) && a[n - 2] == a[n]) return false;
	if (Judge(s[n - 1], a[n]) && a[n - 1] != a[1]) return false;
	if (!Judge(s[n - 1], a[n]) && a[n - 1] == a[1]) return false;
	return true;
}

void Solve()
{
	scanf("%s", s);
	for (int i = 0; i <= 1; i++) {
		a[1] = i;
		if (!Judge(s[0], a[1])) {
			a[n] = 1; a[2] = 0;
			if (Check(a)) {Print(a); return;}
			a[n] = 0; a[2] = 1;
			if (Check(a)) {Print(a); return;}
		}
		else {
			a[n] = 1; a[2] = 1;
			if (Check(a)) {Print(a); return;}
			a[n] = 0; a[2] = 0;
			if (Check(a)) {Print(a); return;}
		}
	}
	printf("-1\n");
}

int main()
{
	while (~scanf("%d", &n)) {
		Solve();
	}
	return 0;
}

