int ok() {
	for (int i = 1; i < N; i++) {
		int p = (i - 1 + N) % N;
		int q = (i + 1) % N;
		if (i != N - 1) {
			if (s[i] == 'o' && ans[i] == 'S') {
				ans[q] = ans[p];
			} else if (s[i] == 'o' && ans[i] == 'W') {
				ans[q] = ans[p] == 'S' ? 'W' : 'S';
			} else if (s[i] == 'x' && ans[i] == 'S') {
				ans[q] = ans[p] == 'S' ? 'W' : 'S';
			} else if (s[i] == 'x' && ans[i] == 'W') {
				ans[q] = ans[p];
			}
		} else {
			if (s[i] == 'o' && ans[i] == 'S') {
				return ans[p] == ans[q];
			} else if (s[i] == 'o' && ans[i] == 'W') {
				return ans[p] != ans[q];
			} else if (s[i] == 'x' && ans[i] == 'S') {
				return ans[p] != ans[q];
			} else if (s[i] == 'x' && ans[i] == 'W') {
				return ans[p] == ans[q];
			}
		}
	}
}

