#include <bits/stdc++.h>
using namespace std;
typedef long long ll;

int N;
string s;
char zoo[100007] = {};

bool solve(char first, char second)
{
    zoo[0] = first;
    zoo[1] = second;
    for (int i = 2; i < N; i++) {
        if (s[i - 1] == 'o') {
            if (zoo[i - 1] == 'S') {
                if (zoo[i - 2] == 'S') {
                    zoo[i] = 'S';
                } else {
                    zoo[i] = 'W';
                }
            } else {
                if (zoo[i - 2] == 'S') {
                    zoo[i] = 'W';
                } else {
                    zoo[i] = 'S';
                }
            }
        } else {
            if (zoo[i - 1] == 'S') {
                if (zoo[i - 2] == 'S') {
                    zoo[i] = 'W';
                } else {
                    zoo[i] = 'S';
                }
            } else {
                if (zoo[i - 2] == 'S') {
                    zoo[i] = 'S';
                } else {
                    zoo[i] = 'W';
                }
            }
        }
    }

    if (zoo[N - 1] == 'S') {
        if (s[N - 1] == 'o') {
            return zoo[N - 2] == zoo[0];
        } else {
            return zoo[N - 2] != zoo[0];
        }
    } else {
        if (s[N - 1] == 'o') {
            return zoo[N - 2] == zoo[0];
        } else {
            return zoo[N - 2] == zoo[0];
        }
    }
}

void display()
{
    string ans;
    for (auto c : zoo) {
        ans += c;
    }
    cout << ans << endl;
}

int main()
{
    ios::sync_with_stdio(false);
    cin.tie(0);

    cin >> N >> s;

    if (solve('S', 'S')) {
        display();
        return 0;
    } else if (solve('S', 'W')) {
        display();
        return 0;
    } else if (solve('W', 'W')) {
        display();
        return 0;
    } else if (solve('W', 'S')) {
        display();
        return 0;
    }
    cout << -1 << endl;

    return 0;
}

