bool hoge(vector<bool> &t) {
    int ret=0;
    FOR(i,1,n) {
        if(i!=n-1) {
            if(t[i]==S) {
                if(s[i]=='o') {
                    t.push_back(t[i-1]);
                }
                else {
                    t.push_back(!t[i-1]);
                }
            }
            else {
                if(s[i]=='o') {
                    t.push_back(!t[i-1]);
                }
                else {
                    t.push_back(t[i-1]);
                }
            }
        }
        else {
            if(t[i]==S) {
                if(s[i]=='o') {
                    ret=(t[i-1]==t[0]);
                }
                else {
                    ret=(t[i-1]!=t[0]);
                }
            }
            else {
                if(s[i]=='o') {
                    ret=(t[i-1]!=t[0]);
                }
                else {
                    ret=(t[i-1]==t[0]);
                }
            }
        }
    }
    if(t[0]==S) {
        if(s[0]=='o') ret+=(t[n-1]==t[1]);
        else ret+=(t[n-1]!=t[1]);
    }
    else {
        if(s[0]=='o') ret+=(t[n-1]!=t[1]);
        else ret+=(t[n-1]==t[1]);
    }
    return ret==2;
}
