bool solve() {
    for( int i = 1; i < n-1; ++i ) {

        if( ans[i] ) {
            if( A[i] == 'o' ) {
                ans[i+1] = ans[i-1];
            } else {
                ans[i+1] = !ans[i-1];
            }
        } else {
            if( A[i] == 'o' ) {
                ans[i+1] = !ans[i-1];
            } else {
                ans[i+1] = ans[i-1];
            }
        }
    }

    if( ans[n-1] ) {
        if( A[n-1] == 'o' ) {
            if( ans[n-2] != ans[0] ) {
                return false;
            }
        } else {
            if( ans[n-2] == ans[0] ) {
                return false;
            }
        }
    } else {
        if( A[n-1] == 'o' ) {
            if( ans[n-2] == ans[0] ) {
                return false;
            }
        } else {
            if( ans[n-2] != ans[0] ) {
                return false;
            }
        }
    }

    if( ans[0] ) {
        if( A[0] == 'o' ) {
            if( ans[n-1] != ans[1] ) {
                return false;
            }
        } else {
            if( ans[n-1] == ans[1] ) {
                return false;
            }
        }
    } else {
        if( A[0] == 'o' ) {
            if( ans[n-1] == ans[1] ) {
                return false;
            }
        } else {
            if( ans[n-1] != ans[1] ) {
                return false;
            }
        }
    }
    return true;
}

int main() {
    scanf( "%d", &n );
    scanf( "%s", A );

    ans[0] = 0;
    ans[1] = 1;
    if( solve() ) {
        print();
        return 0;
    }

    ans[0] = 0;
    ans[1] = 0;
    if( solve() ) {
        print();
        return 0;
    }

    ans[0] = 1;
    ans[1] = 1;
    if( solve() ) {
        print();
        return 0;
    }

    ans[0] = 1;
    ans[1] = 0;
    if( solve() ) {
        print();
        return 0;
    }

    puts( "-1" );
    return 0;
}

