}

bool flag(int *A, int N, char *s) {
    bool flg;
    for (int i = 1; i < N; i++) {
        if (s[i] == 'o') A[i+1] = A[i] * A[i-1];
        else A[i+1] = -1 * A[i] * A[i-1];
    }

    if (s[0] == 'o') {
        if (A[0] * A[1] == A[N-1] && A[N] == A[0]){
            print(A, N);
            flg = true;
        } else {
            flg =  false; 
        }

    } else {
        if (A[0] * A[1] == -A[N] && A[N] == A[0]){
            print(A, N);
            flg =  true;
        } else {
            flg =  false; 
        }
    }
    return flg;
}

int main() {
    int N, A[100005];
    char s[100005];
    scanf("%d", &N);
    scanf("%s", s);

    bool flg = false;
    A[0] = A[1] = 1;

    flg = flag(A, N, s);
    if (flg == false) {
        A[0] = 1; A[1] = -1; flg = flag(A, N, s);
    } 
    if (flg == false) {
        A[0] = -1; A[1] = 1; flg = flag(A, N, s);
    }
    if (flg == false) {
        A[0] = A[1] = -1; flg = flag(A, N, s);  
    } 
    if (flg == false) printf("%d", -1);
    return 0;
}

