        } else if (c[i] == 1 && s[i] == 'o') {
            c[(i + 1 + n) % n] = !c[(i - 1 + n) % n];
        } else if (c[i] == 0 && s[i] == 'x') {
            c[(i + 1 + n) % n] = !c[(i - 1 + n) % n];
        } else if (c[i] == 1 && s[i] == 'x') {
            c[(i + 1 + n) % n] = c[(i - 1 + n) % n];
        }
    }
    bool flag = true;
    rep(i, n)
    {
        //cout << c[i] << ' ';
        if (c[i] == 0 && s[i] == 'o') {
            flag &= (c[(i + 1 + n) % n] == c[(i - 1 + n) % n]);
        } else if (c[i] == 1 && s[i] == 'o') {
            flag &= (c[(i + 1 + n) % n] == !c[(i - 1 + n) % n]);
        } else if (c[i] == 0 && s[i] == 'x') {
            flag &= (c[(i + 1 + n) % n] == !c[(i - 1 + n) % n]);
        } else if (c[i] == 1 && s[i] == 'x') {
            flag &= (c[(i + 1 + n) % n] == c[(i - 1 + n) % n]);
        }
    }
    if (flag) {
        rep(i, n)
        {
            if (c[i])
                cout << 'S';
            else
                cout << 'W';
        }
        cout << endl;
    } else {
        cout << -1 << endl;
        return 0;
    }
}

