            o[i+1] = (s[i-1] == 'o' ? (o[i-1] == 'W' ? 'S' : 'W') : o[i-1]);
        }
    }
    //o[N] == o0, o1==oN+1
    return o[0] == o[N] && o[1] == o[N+1];
}

