int solve_left() {
	for(i=N-1;i>1;i--) {
		pre = (i + 1) % N;
		next = i - 1;
		if(ans[i] == 'S') {
			if(s[i] == 'o' && ans[pre] != ans[next]) {
				ans[next] = ans[pre];
			}
			if(s[i] == 'x' && ans[pre] == ans[next]) {
				ans[next] = ans[next] == 'S' ? 'W' : 'S';
			}
		} else {
			if(s[i] == 'o' && ans[pre] == ans[next]) {
				ans[next] = ans[next] == 'S' ? 'W' : 'S';
			}
			if(s[i] == 'x' && ans[pre] != ans[next]) {
				ans[next] = ans[pre];
			}
		}
	}
	if(ans[0] == 'S') {
		if(s[0] == 'o' && ans[N-1] == ans[1]) {
			ps(ans);
			return 1;
		}
		if(s[0] == 'x' && ans[N-1] != ans[1]) {
