#include <stdio.h>
#include <stdlib.h>
#include <string.h>

int main(void) {
    int i, j, N, W, X;
    char S[100010], T[100010];
    scanf("%d%s", &N, &S);

    W = 0;
    for (i=0;i<N;i++) if (S[i] == 'x') W++;
    if (W%2) printf("-1\n");
    else {
        W = 0; X = 0; j = 0;
        for (i=0;i<N;i++) {
            if (!W && S[i] == 'o') T[j++] = 'S';
            else if (!W && S[i] == 'x') {
                T[j++] = 'S';
                W = 1;
            } else if (W && S[i] == 'o') {
                T[j++] = 'W';
                X++;
            } else if (W && S[i] == 'x') {
                if (!X) { printf("-1\n"); return 0; }
                T[j++] = 'S';
                W = 0; X = 0;
            }
        }
        printf("\n");
    }

    return 0;
}

