#include <stdio.h>

#define MAX 100000
#define SHEEP 1
#define WOLF 2

int check(long long int n, long ans[MAX], const char s[MAX]) {
    for(long long int i = 1; i < n - 1; i++) {
        if(ans[i] == SHEEP) {
            if(*(s + i) == 'o') {
                if(ans[i + 1] != 0 && ans[i + 1] != ans[i - 1]) {
                    return 1;
                }
                ans[i + 1] = ans[i - 1];
            } else {
                if(ans[i + 1] != 0 && ans[i + 1] != (ans[i - 1] == SHEEP ? WOLF : SHEEP)) {
                    return 1;
                }
                ans[i + 1] = ans[i - 1] == SHEEP ? WOLF : SHEEP;
            }
        } else {
            if(*(s + i) == 'o') {
                if(ans[i + 1] != 0 && ans[i + 1] != (ans[i - 1] == SHEEP ? WOLF : SHEEP)) {
                    return 1;
                }
                ans[i + 1] = ans[i - 1] == SHEEP ? WOLF : SHEEP;
            } else {
                if(ans[i + 1] != 0 && ans[i + 1] != ans[i - 1]) {
                    return 1;
                }
                ans[i + 1] = ans[i - 1];
            }
        }
    }

    return 0;
}
