typedef unsigned long long ULL;

enum{SHEEP, WOLF};



int ans(ULL N, char *s, int first, int second, int *animals) {
    //int *animals = malloc(sizeof(int) * N);
    memset(animals, 0, sizeof(int) * N);
    int result = 0;

    *animals = first;
    *(animals + 1) = second;

    for(ULL i = 1; i < N - 1; i++) {
        char ans = *(s + i);
        if(ans == 'o') {
            if(*(animals + i) == SHEEP) {
                *(animals + i + 1) = *(animals + i - 1);
            } else {
                *(animals + i + 1) = *(animals + i - 1) == SHEEP ? WOLF : SHEEP;
            }
        } else {
            if(*(animals + i) == SHEEP) {
                *(animals + i + 1) = *(animals + i - 1) == SHEEP ? WOLF : SHEEP;
            } else {
                *(animals + i + 1) = *(animals + i - 1);
            }
        }
    }
    //check first, last and last - 1
    if(*(animals + N - 1) == SHEEP) {
        if(*(s+ N - 1) == 'o') {
            result = *(animals + 0) == *(animals + N - 2);
        } else {
            result = *(animals + 0) != *(animals + N - 2);
        }
    } else {
        if(*(s+ N - 1) == 'o') {
            result = *(animals + 0) != *(animals + N - 2);
        } else {
            result = *(animals + 0) == *(animals + N - 2);
        }
    }
    if(result) {
        if(*(animals) == SHEEP) {
            if(*(s) == 'o') {
                result = *(animals + 1) == *(animals + N - 2);
            } else {
                result = *(animals + 1) != *(animals + N - 2);
            }
        } else {
            if(*(s) == 'o') {
                result = *(animals + 1) != *(animals + N - 2);
            } else {
                result = *(animals + 1) == *(animals + N - 2);
            }
        }
    }

    return result;
}

void menagerie(ULL N, char *s) {
    int *animals = malloc(sizeof(int) * N);
    memset(animals, 0, sizeof(int) * N);

    int result = ans(N, s, SHEEP, SHEEP, animals);
    if(!result) {
        result = ans(N, s, SHEEP, WOLF, animals);
    }
    if(!result) {
        result = ans(N, s, WOLF, WOLF, animals);
    }
    if(!result) {
        result = ans(N, s, WOLF, SHEEP, animals);
    }

    if(result) {
        for(ULL i = 0; i < N; i++) {
            printf("%s", *(animals + i) == SHEEP ? "S" : "W");
        }
    }else {
        printf("-1");
    }
    printf("\n");
    free(animals);
}


