int main(void)
{
	//変数の宣言
	int n;
	char s[100010];
	int sint[100010];
	int animal[100010];
	int flag=0;
	int i,j,k;

	//データの読み込み
	scanf("%d\n%s",&n,&s);

	for(i=0;i<n;i++){
		if(s[i]=='o'){
			sint[i]=0;
		}else{
			sint[i]=1;
		}
	}

//	printf("nは%dです\n", n);
//	printf("データの読み込み終了\n");
	//実際の処理

	for(i=0;i<4;i++){
		if(i%2==0){
			animal[0]=0;
		}else{
			animal[0]=1;
		}
		if(i<2){
			animal[1]=0;
		}else{
			animal[1]=1;
		}

		for(j=2;j<=n;j++){
			animal[j]=(animal[j-2]+animal[j-1]+sint[j-1])%2;
		}

//		printf("0→%d,n→%d\n",animal[0],animal[n]);
		if(animal[n]==animal[0]&&animal[1]==(animal[n-1]+animal[n]+sint[0])%2){
			flag=1;
			break;
		}
	}


//	for(i=0;i<n;i++){
//		printf("sint[%d]=%d\n",i,sint[i]);
//	}

//	for(i=0;i<n;i++){
//		printf("animal[%d]=%d\n",i,animal[i]);
//	}


//	printf("計算部分終了\n");

	//出力

	if(flag==1){
		for(i=0;i<n;i++){
			if(animal[i]==0){
				printf("S");
			}else{
				printf("W");
			}
		}
	}else{
		printf("-1");
	}


//	printf("結果の出力終了\n");

	return 0;
}

#include <stdio.h>
#include <stdlib.h>
#include <string.h>

int N;

int check(const char *s, char *t, int flag) {
    int i;

    if (flag & 1) t[0] = 'W';
    else t[0] = 'S';
    if (flag & 2) t[1] = 'W';
    else t[1] = 'S';
    i = 0;
    while (++i < N-1) {
        if (t[i] == 'S') {
            if (s[i] == 'o') t[i+1] = t[i-1];
            else if (t[i-1] == 'S') t[i+1] = 'W';
            else t[i+1] = 'S';
        } else {
            if (s[i] == 'o') {
                if (t[i-1] == 'W') t[i+1] = 'S';
                else t[i+1] = 'W';
            } else t[i+1] = t[i-1];
        }
    }
    if (((t[N-2] == t[0] && t[N-1] == 'S' && s[N-1] == 'o') || 
         (t[N-2] != t[0] && t[N-1] == 'S' && s[N-1] == 'x') ||
         (t[N-2] == t[0] && t[N-1] == 'W' && s[N-1] == 'x') ||
         (t[N-2] != t[0] && t[N-1] == 'W' && s[N-1] == 'o')) && 
        ((t[N-1] == t[1] && t[0] == 'S' && s[0] == 'o') || 
         (t[N-1] != t[1] && t[0] == 'S' && s[0] == 'x') ||
         (t[N-1] == t[1] && t[0] == 'W' && s[0] == 'x') ||
         (t[N-1] != t[1] && t[0] == 'W' && s[0] == 'o'))) {
        t[N] = '\0';
        return 0;
    } else {
        return 1;
    }
}

int main(void) {
    int i, res;
    char S[100010], T[100010];
    scanf("%d%s", &N, &S);
    memset(T,0,100010);

    memset(T,0,100010);
    res = check(S, T, 0);
    while (res && ++i<4) {
        memset(T,0,100010);
        res = check(S, T, i);
    }
    if (!res) printf("%s\n", T);
    else printf("-1\n");
    return 0;
}

#include <stdio.h>
#include <stdlib.h>

int N;
char s[1000000];

char wariate[1000000];

int create_wariate(void) {
	int i;
	for (i = 2; i <= N + 1; i++) {
		if (s[i - 1] == (wariate[i - 1] == 'S' ? 'o' : 'x')) {
			/* 両隣が同じ */
			wariate[i] = wariate[i - 2];
		} else {
			wariate[i] = (wariate[i - 2] == 'S' ? 'W' : 'S');
		}
	}
	return wariate[0] == wariate[N] && wariate[1] == wariate[N + 1];
}

void check(const char* initial) {
	wariate[0] = initial[0];
	wariate[1] = initial[1];
	if (create_wariate()) {
		wariate[N] = '\0';
		puts(wariate);
		exit(0);
	}
}

