	if (scanf("%d", &N) != 1) return 1;
	if (scanf("%s", s) != 1) return 1;
	s[N] = s[0];
	s[N + 1] = s[1];
	check("SS");
	check("SW");
	check("WS");
	check("WW");
	puts("-1");
	return 0;
}

