}

int f(void)
{
    char op;

    for (int i = 1; i < n; i++) {
        op = s[i];

        if (a[i] == 'W') {
            op = sinv(op);
        }

        if (op == 'o') {
            a[i + 1] = a[i - 1];
        }
        else {
            a[i + 1] = ainv(a[i - 1]);
        }
    }

    op = s[0];
    if (a[0] == 'W') {
        op = sinv(op);
    }

    if (a[n] == a[0] &&
        op == 'o' && a[n - 1] == a[1]) {
        a[n] = 0;
        return 1;
    }

    if (a[n] == a[0] &&
        op == 'x' && a[n - 1] != a[1]) {
        a[n] = 0;
        return 1;
    }

    return 0;
}

