    for(long long int i = 0; i < n; i++) {
        ans[i] = 0;
    }

    ans[0] = SHEEP;
    ans[1] = SHEEP;
    ans[n-1] = SHEEP;

    int result = check(n, ans, s);

    if(result == 1) {
        for(long long int i = 0; i < n; i++) {
            ans[i] = 0;
        }
        ans[1] = WOLF;
        ans[n-1] = WOLF;
        result = check(n, ans, s);
    }
    if(result == 1) {
        for(long long int i = 0; i < n; i++) {
            ans[i] = 0;
        }
        ans[0] = WOLF;
        if(*(s) == 'o') {

            ans[1] = WOLF;
            ans[n-1] = SHEEP;

            result = check(n, ans, s);
            if(result == 1) {
                for(long long int i = 0; i < n; i++) {
                    ans[i] = 0;
                }
                ans[0] = WOLF;
                ans[1] = SHEEP;
                ans[n-1] = WOLF;

                result = check(n, ans, s);
            }

        } else {
            ans[1] = WOLF;
            ans[n-1] = WOLF;
            result = check(n, ans, s);
            if(result == 1) {
                for(long long int i = 0; i < n; i++) {
                    ans[i] = 0;
                }
                ans[0] = WOLF;
                ans[1] = SHEEP;
                ans[n-1] = SHEEP;

                result = check(n, ans, s);
            }

        }
    }


    if(result == 1) {
        printf("-1");
