#define MAX 100000
#define SHEEP 1
#define WOLF 2

int check(int n, int ans[MAX], const char s[MAX]) {
    for(int i = 1; i < n; i++) {
        if(ans[i] == SHEEP) {
            if(*(s + i) == 'o') {
                if(ans[(i + 1)%n] != 0 && ans[(i + 1)%n] != ans[i - 1]) {
                    return 1;
                }
                ans[i + 1] = ans[i - 1];
            } else {
                if(ans[(i + 1)%n] != 0 && ans[(i + 1)%n] != (ans[i - 1] == SHEEP ? WOLF : SHEEP)) {
                    return 1;
                }
                ans[i + 1] = ans[i - 1] == SHEEP ? WOLF : SHEEP;
            }
        } else {
            if(*(s + i) == 'o') {
                if(ans[(i + 1)%n] != 0 && ans[(i + 1)%n] != (ans[i - 1] == SHEEP ? WOLF : SHEEP)) {
                    return 1;
                }
                ans[i + 1] = ans[i - 1] == SHEEP ? WOLF : SHEEP;
            } else {
                if(ans[(i + 1)%n] != 0 && ans[(i + 1)%n] != ans[i - 1]) {
                    return 1;
                }
                ans[i + 1] = ans[i - 1];
            }
        }
    }

    return 0;
}
