fun solve(N: Int, s: String){
    // animals[0]が W, Sの二通り, animals[1]がW, Sの二通り 2つ決めたら一意に決まる

    val animalsPattern = Array(4){ IntArray(N) }
    animalsPattern[0][0] = S
    animalsPattern[1][0] = S
    animalsPattern[2][0] = W
    animalsPattern[3][0] = W
    animalsPattern[0][1] = S
    animalsPattern[1][1] = W
    animalsPattern[2][1] = S
    animalsPattern[3][1] = W
    for (i in 2 until N){
        for(j in 0..3){
            // same
            if ((animalsPattern[j][i-1] == S && s[i-1] == 'o') || (animalsPattern[j][i-1] == W && s[i-1]=='x')){
                animalsPattern[j][i] = animalsPattern[j][i-2]
            }else{
                animalsPattern[j][i] = animalsPattern[j][i-2] xor 1
            }
        }
    }
    for(j in 0..3){
        // same
        val lastFromHead = if ((animalsPattern[j][0] == S && s[0] == 'o') || (animalsPattern[j][0] == W && s[0]=='x')) animalsPattern[j][1] else animalsPattern[j][1] xor 1
        val firstFromTail= if ((animalsPattern[j][N-1] == S && s[N-1] == 'o') || (animalsPattern[j][N-1] == W && s[N-1]=='x')) animalsPattern[j][N-2] else animalsPattern[j][N-2] xor 1
        if (lastFromHead == animalsPattern[j][N-1] && firstFromTail == animalsPattern[j][0]){
            animalsPattern[j].map{ if (it==S) 'S' else 'W' }.joinToString(separator="").let{ println(it) }
            return
        }
    }
    println(-1)
    return
}


