		this.N = cin.nextInt();
		this.s = cin.next().toCharArray();
	}

	void main() {

		String[] a = new String[]{"00", "01", "10", "11"};
		for (int i = 0; i < 4; i++) {
			int[] arr = new int[N];
			for (int j = 0; j < 2; j++) {
				arr[j] = Integer.valueOf(String.valueOf(a[i].charAt(j)));
			}

			for (int j = 1; j < N - 1; j++) {
				char c = s[j];
				int num = arr[j-1] + arr[j];
				if (c == 'o') {
					if (num % 2 == 0) {
						arr[j + 1] = 0;
					} else {
						arr[j + 1] = 1;
					}
				} else {
					if (num % 2 == 0) {
						arr[j + 1] = 1;
					} else {
						arr[j + 1] = 0;
					}
				}
			}

			int num = 0;
			char c = 0;
			num = arr[N - 2] + arr[N - 1] + arr[0];
			c = s[N - 1];
			if (c == 'o') {
				if (num % 2 != 0) {
					continue;
				}
			} else {
				if (num % 2 == 0) {
					continue;
				}
			}

			num = arr[N - 1] + arr[0] + arr[1];
			c = s[0];
			if (c == 'o') {
				if (num % 2 != 0) {
					continue;
				}
			} else {
				if (num % 2 == 0) {
					continue;
