                        if (st[i - 1] == st[0]) {
                            return false;
                        }
                    }
                }
            } else {
                if (st[i] == 'S') {
                    if (i + 1 < n - 1) {
                        st[i + 1] = opposite(st[i - 1]);
                    } else if (i + 1 == n - 1) {
                        if (st[i - 1] == st[i + 1]) {
                            return false;
                        }
                    } else {
                        if (st[i - 1] == st[0]) {
                            return false;
                        }
                    }
                } else {
                    if (i + 1 < n - 1) {
                        st[i + 1] = (st[i - 1]);
                    } else if (i + 1 == n - 1) {
                        if (st[i - 1] != st[i + 1]) {
                            return false;
                        }
                    } else {
                        if (st[i - 1] != st[0]) {
                            return false;
                        }
                    }
                }
            }
        }
        return true;
    }

    private char opposite(char c) {
        if (c == 'S') return 'W';
        else return 'S';
    }
}

