//                    ans[i] = 'W';
//                }
//                else{
//                    ans[i] = 'S';
//                }
//            }
        }

        boolean valid  = true;

        if(s.charAt(s.length()-1)=='o'){
            if(ans[0]!=ans[s.length()-2]){
                valid = false;
            }
        }
        else{
            if(ans[0]==ans[s.length()-2]){
                valid = false;
            }
        }

        if(s.charAt(0)=='o'){
