    char[] s = sc.next().toCharArray();

    int[][] arr = {{1, 1}, {-1, -1}, {1, -1}, {-1, 1}};
    int[] ret = null;
    for (int[] v : arr) {
      ret = make(v[0], v[1], s);
      if (ret != null) {
        break;
      }
    }
    if (ret == null) {
      System.out.println(-1);
    } else {
