using System;
using System.Collections.Generic;
using System.IO;
using System.Linq;

class Program
{
    static void Main(string[] args)
    {
        var sw = new StreamWriter(Console.OpenStandardOutput()) { AutoFlush = false };
        Console.SetOut(sw);
        Solve();
        Console.Out.Flush();
    }
    static void Solve()
    {
        var N = sc.ReadInt();
        var S = sc.ReadStr();
        S += S;

        foreach (var x0 in new int[] { -1, 1 })
        {
            foreach (var x1 in new int[] { -1, 1 })
            {
                var sw = new int[N];
                sw[0] = x0;
                sw[1] = x1;

                var ok = true;
                for (int i = 1; i < N; i++)
                {
                    if (sw[i] == 1)
                    {
                        // S と仮定
                        if (S[i] == 'o')
                        {
                            // 両隣が同じ
                            sw[(i + 1) % N] = sw[i - 1];
                        }
                        else
                        {
                            // 両隣が異なる
                            sw[(i + 1) % N] = -sw[i - 1];
                        }
                    }
                    else
                    {
                        // W と仮定
                        if (S[i] == 'o')
                        {
                            // 両隣が異なる
                            sw[(i + 1) % N] = -sw[i - 1];
                        }
                        else
                        {
                            // 両隣が同じ
                            sw[(i + 1) % N] = sw[i - 1];
                        }
                    }
                }
                for (int i = 0; i < N; i++)
                {
                    var l = (i - 1);
                    if (l < 0) l = N - 1;
                    var r = (i + 1) % N;
                    if ((sw[i] == 1 && S[i] == 'o') || (sw[i] == -1 && S[i] == 'x'))
                    {
                        // 両隣が同じ
                        if (sw[l] != sw[r]) ok = false;
                    }
                    else
                    {
                        // 両隣が異なる
                        if (sw[l] == sw[r]) ok = false;
                    }
                }

                if (ok)
                {
                    for (int i = 0; i < N; i++)
                    {
                        Console.Write(sw[i] == 1 ? 'S' : 'W');
                    }
                    Console.WriteLine();
                    return;
                }
            }
        }
        Console.WriteLine(-1);
    }
    static Scanner sc = new Scanner();
}
