    class Class403
    {
        static char[][] pattern = new char[4][]
        {
            new char[2]{'S','S'},
            new char[2]{'S','W'},
            new char[2]{'W','S'},
            new char[2]{'W','W'}
        };
        static void Main()
        {
            int N = int.Parse(Console.ReadLine());
            string s = Console.ReadLine();
            for (int j = 0; j < 4; j++)
            {
                char[] ans = new char[N + 2];
                ans[0] = pattern[j][0];
                ans[1] = pattern[j][1];

                for (int i = 1; i < N+1; i++)
                {
                    int num = i % N;

                    if (ans[i] == 'S')
                    {
                        if (s[num] == 'o') ans[i + 1] = ans[i - 1];
                        else ans[i + 1] = Swap(ans[i - 1]);
                    }
                    else
                    {
                        if (s[num] == 'o') ans[i + 1] = Swap(ans[i - 1]);
                        else ans[i + 1] = ans[i - 1];
                    }
                }

                if (ans[0] == ans[N] && ans[1] == ans[N + 1])
                {

                    Console.WriteLine(string.Join("", ans.Take(N)));
                    return;

                }
            }

            Console.WriteLine(-1);

        }
        static char Swap(char c)
        {
            if (c == 'S') return 'W';
            else return 'S';
        }
    }
