public class Hello
{
    public static void Main()
    {
        Console.WriteLine(program(new string[] { Console.ReadLine(), Console.ReadLine() }));
    }

    private static string program(string[] args)
    {
        var n = int.Parse(args[0]);
        var s = args[1].ToCharArray();

        return (new String[] { "SS", "SW", "WS", "WW" }).Select(animals =>
            s.Aggregate(new StringBuilder(animals, n),
                (t, elem) => t.Append(isXor(t[t.Length - 1], elem) ? not(t[t.Length - 2]) : t[t.Length - 2]))
        )
        .Select(sb => sb.ToString())
        .FirstOrDefault(result => result.Substring(0, 2) == result.Substring(result.Length - 2, 2))?.Substring(1, n) ?? "-1";
    }

    private static bool isXor(char animal, char ans) => animal == 'S' && ans == 'x' || animal == 'W' && ans == 'o';

    private static char not(char animal) => animal == 'S' ? 'W' : 'S';
}

using System;

class p
{
    static string t;

    //i,i+1文字目からi-1文字目を決めて返す
    static char backChar(string s,string temp,int i)
    {
        if (temp[i] == 'S')//i文字目が羊
        {
            if (s[i] == 'o')//羊かつ〇なら両側が同じ
                return temp[i + 1];
            else //羊かつ×なら両側が異なる
            {
                if (temp[i + 1] == 'S') return 'W';
                else return 'S';
            }
        }
        else //i文字目が狼
        {
            if (s[i] == 'x')//狼かつ×なら両側が同じ
                return temp[i + 1];
            else //狼かつ〇なら両側が異なる
            {
                if (temp[i + 1] == 'S') return 'W';
                else return 'S';
            }
        }
    }

    //i-1,i文字目からi+1文字目を決めて返す
    static char nextChar(string s,string temp,int i)
    {
        if (temp[i] == 'S')//i文字目が羊
        {
            if (s[i] == 'o')//羊かつ〇なら両側が同じ
                return temp[i - 1];
            else //羊かつ×なら両側が異なる
            {
                if (temp[i - 1] == 'S') return 'W';
                else return 'S';
            }
        }
        else //i文字目が狼
        {
            if (s[i] == 'x')//狼かつ×なら両側が同じ
                return temp[i - 1];
            else //狼かつ〇なら両側が異なる
            {
                if (temp[i - 1] == 'S') return 'W';
                else return 'S';
            }
        }
    }

    static void Main(string[] a)
    {
        int N = int.Parse(Console.ReadLine());
        string s = Console.ReadLine();
        //s は o と x のみからなる長さ N の文字列
        t = "-1";
        //t は長さ N で S と W のみからなる文字列;解がない場合の-1を代入
        string temp = "";
        //１，２文字目を仮定してシミュレーションするための文字列temp
        char lastNext;
        char firstBack;

        string[] strarray = { "SS", "SW", "WS", "WW" };

        foreach (string str in strarray)
        {
            if (t != "-1") break;
            temp = str;
            for (int i = 1; i < N - 1; i++)
            {
                temp += nextChar(s, temp, i);
            }
            lastNext = nextChar(s, temp, N - 1);
            firstBack = backChar(s, temp, 0);
            if (lastNext == temp[0] && firstBack == temp[N - 1]) t = temp;
        }

        Console.WriteLine(t);

    }
}

