public class Scanner
{
    private StreamReader Sr;

    private string[] S;
    private int Index;
    private const char Separator = ' ';

    public Scanner(Stream source)
    {
        Index = 0;
        S = new string[0];
        Sr = new StreamReader(source);
    }

    private string[] Line()
    {
        return Sr.ReadLine().Split(Separator);
    }

    public string Next()
    {
        string result;
        if (Index >= S.Length)
        {
            S = Line();
            Index = 0;
        }
        result = S[Index];
        Index++;
        return result;
    }
    public int NextInt()
    {
        return int.Parse(Next());
    }
    public double NextDouble()
    {
        return double.Parse(Next());
    }
    public long NextLong()
    {
        return long.Parse(Next());
    }
    public decimal NextDecimal()
    {
        return decimal.Parse(Next());
    }
    public string[] StringArray(int index = 0)
    {
        Next();
        Index = S.Length;
        return S.Skip(index).ToArray();
    }
    public int[] IntArray(int index = 0)
    {
        return StringArray(index).Select(int.Parse).ToArray();
    }
    public long[] LongArray(int index = 0)
    {
        return StringArray(index).Select(long.Parse).ToArray();
    }
    public bool EndOfStream
    {
        get { return Sr.EndOfStream; }
    }
}

public class Magatro
{
    private Scanner Cin;
    private int N;
    private string s;

    private void Scan()
    {
        Cin = new Scanner(Console.OpenStandardInput());
        N = Cin.NextInt();
        s = Cin.Next();
    }
    public void Solve()
    {
        Scan();
        int[] ar = new int[N];
        ar[0] = 1;
        ar[1] = 1;
        if (Ans(ar))
        {
            Console.WriteLine(string.Join("", ar.Select(S).ToArray()));
            return;
        }
        ar = new int[N];
        ar[0] = -1;
        ar[1] = 1;
        if (Ans(ar))
        {
            Console.WriteLine(string.Join("", ar.Select(S).ToArray()));
            return;
        }
        ar = new int[N];
        ar[0] = -1;
        ar[1] = -1;
        if (Ans(ar))
        {
            Console.WriteLine(string.Join("", ar.Select(S).ToArray()));
            return;
        }
        ar = new int[N];
        ar[0] = 1;
        ar[1] = -1;
        if (Ans(ar))
        {
            Console.WriteLine(string.Join("", ar.Select(S).ToArray()));
            return;
        }
        Console.WriteLine(-1);
    }

    private string S(int i)
    {
        if (i == 1) return "S";
        else return "W";
    }
    private bool Ans(int[] arr)
    {
        for (int i = 1; i <= N; i++)
        {
            int p = i % N;
            int before = i - 1;
            int next = (i + 1) % N;
            switch (s[p])
            {
                case 'o':
                    if (arr[p] == 1)
                    {
                        arr[next] = arr[before];
                    }
                    else
                    {
                        arr[next] = arr[before] * -1;
                    }
                    break;
                case 'x':
                    if (arr[p] == -1)
                    {
                        arr[next] = arr[before];
                    }
                    else
                    {
                        arr[next] = arr[before] * -1;
                    }
                    break;
            }
        }
        for (int i = 0; i < N; i++)
        {
            int b = (N + i - 1) % N;
            int n = (i + 1) % N;
            if (arr[i] == 1)
            {
                if (s[i] == 'o')
                {
                    if (arr[n] != arr[b])
                    {
                        return false;
                    }
                }
                else
                {
                    if (arr[b] == arr[n])
                    {
                        return false;
                    }
                }
            }
            else
            {
                if (s[i] != 'o')
                {
                    if (arr[n] != arr[b])
                    {
                        return false;
                    }
                }
                else
                {
                    if (arr[b] == arr[n])
                    {
                        return false;
                    }
                }
            }
        }
        return true;
    }
}

