class Program
{
    static void Main(string[] args)
    {
        var sw = new StreamWriter(Console.OpenStandardOutput()) { AutoFlush = false };
        Console.SetOut(sw);
        Solve();
        Console.Out.Flush();
    }
    static void Solve()
    {
        var N = sc.ReadInt();
        var S = sc.ReadStr();
        //for (int x = (1 << 2) - 1; x >= 0; x--)
        for (int x = 0; x < (1 << 2); x++)
        {
            var ws = new int[N];
            ws[0] = (x >> 0) & 1;
            ws[1] = (x >> 1) & 1;
            for (int i = 1; i < N; i++)
            {
                var ni = (i + 1) % N;
                if (ws[i] == 0)
                {
                    // i番目が羊の時
                    if (S[i] == 'o')
                    {
                        ws[ni] = ws[i - 1];
                    }
                    else
                    {
                        ws[ni] = ws[i - 1] ^ 1;
                    }
                }
                else
                {
                    // i番目が狼の時
                    if (S[i] == 'o')
                    {
                        ws[ni] = ws[i - 1] ^ 1;
                    }
                    else
                    {
                        ws[ni] = ws[i - 1];
                    }
                }
            }
            var ok = ((x >> 0) & 1) == ws[0];
            if (ok)
            {
                var ans = new string(ws.Select(x => x == 0 ? 'S' : 'W').ToArray());
                Console.WriteLine(ans);
                return;
            }
        }
        Console.WriteLine(-1);
    }
    static Scanner sc = new Scanner();
}
