	internal class Program {
		private static void Main(string[] args) {
			var sw = new StreamWriter(OpenStandardOutput()) { AutoFlush = false };
			SetOut(sw);
			new Calc().Solve();
			Out.Flush();
		}

		public class Calc
		{
			public void Solve() {
				int N = NextInt();
				var S = ReadLine();

				var box = S.Select(x => x == 'o').ToArray();

				var stPattern = new [,] {{true, true}, {true, false}, {false, false}, {false, true}}; //開始パターン

				Func<List<bool>, List<bool>> make = (input) =>
				{
					//発言と初期パターンからNまでの列を作ってみる
					//矛盾は外で判断して
					for (int i = 1; i < N-1; i++) {
						if (box[i] && input[i]) { //oで羊なので同じ奴
							input.Add(input[i - 1]);
						}
						else if (box[i] && !input[i]) { //oで狼なので違うやつ
							input.Add(!input[i - 1]);
						}
						else if (!box[i] && input[i]) { //xで羊なので違うやつ
							input.Add(!input[i - 1]);
						}
						else { //xで狼なので同じ奴
							input.Add(input[i - 1]);
						}
					}

					return input;
				};

				Func<List<bool>, string> fil = (input) => input.Select(x => x ? 'S' : 'W').StringJoin();

				var last = N - 1;
				var boo = last - 1;

				for (int i = 0; i < 4; i++) {
					var list = new List<bool> {stPattern[i, 0], stPattern[i, 1]};
					list = make(list);
					//矛盾チェック
					if (box[last]) {
						//最後がo
						if (list[last]) {
							//最後は羊
							if (list[boo] != list[0]) continue;
							fil(list).WL();
							return;
						}
						else {
							//最後が狼
							if (list[boo] == list[0]) continue;
							fil(list).WL();
							return;
						}
					}
					else {
						//最後がx
						if (list[last]) {
							//最後は羊
							if (list[boo] == list[0]) continue;
							fil(list).WL();
							return;
						}
						else {
							if (list[boo] != list[0]) continue;
							fil(list).WL();
							return;
						}
					}
				}
				"-1".WL();


				return;
			}

		}


	}
