class Program
{
    static void Main(string[] args)
    {
        var N = sc.ReadInt();
        var S = sc.ReadStr();
        if (S.All(c => c == 'o'))
        {
            Console.WriteLine(new string('S', N));
            return;
        }
        else if (S.All(c => c == 'x'))
        {
            Console.WriteLine(new string('W', N));
            return;
        }
        var rle = RLE(S).ToArray();
        if (rle.Length == 0)
        {
            if (S[0] == 'o')
            {
                Console.WriteLine(new string('S', N));
                return;
            }
            else if (S[0] == 'x')
            {
                Console.WriteLine(new string('W', N));
                return;
            }
        }
        else if (rle.Length <= 3)
        {
            Console.WriteLine(-1);
            return;
        }
        var ans = new List<char>();
        var next = 'S';
        var o = false;
        for (int i = 0; i < rle.Length; i++)
        {
            var r = rle[i];
            if (r.Item1 == 'x')
            {
                ans.AddRange(Enumerable.Repeat(next, r.Item2));
            }
            else if (r.Item1 == 'o')
            {
                if (next == 'S')
                {
                    ans.AddRange(Enumerable.Repeat(next, r.Item2));
                    if (i < rle.Length - 1)
                    {
                        ans.AddRange(Enumerable.Repeat(next, rle[i + 1].Item2));
                        i++;
                    }
                    next = 'W';
                }
                else
                {
                    if (r.Item2 < 2)
                    {
                        Console.WriteLine(-1);
                        return;
                    }
                    ans.AddRange(Enumerable.Repeat(next, r.Item2));
                    next = 'S';
                }
            }
        }

        Console.WriteLine(string.Join("", ans));
    }
    static IEnumerable<Tuple<char, int>> RLE(string s)
    {
        var count = 1;
        var c = s[0];
        for (int i = 1; i < s.Length; i++)
        {
            if (c == s[i])
            {
                count++;
            }
            else
            {
                yield return Tuple.Create(c, count);
                count = 1;
            }
            c = s[i];
        }
        yield return Tuple.Create(c, count);
    }
    static Scanner sc = new Scanner();
}

