class Program
{
    static void Main(string[] args)
    {
        var sw = new StreamWriter(Console.OpenStandardOutput()) { AutoFlush = false };
        Console.SetOut(sw);
        Solve();
        Console.Out.Flush();
    }
    static void Solve()
    {
        var N = sc.ReadInt();
        var S = sc.ReadStr();

        foreach (var x0 in new int[] { -1, 1 })
        {
            foreach (var x1 in new int[] { -1, 1 })
            {
                var sw = new int[N].ToList();
                sw[0] = x0;
                sw[1] = x1;
                sw.Add(x0);

                var ok = true;
                for (int i = 1; i < N; i++)
                {
                    if (sw[i] == 1)
                    {
                        // S と仮定
                        if (S[i] == 'o')
                        {
                            // 両隣が同じ
                            sw[i + 1] = sw[i - 1];
                        }
                        else
                        {
                            // 両隣が異なる
                            sw[i + 1] = -sw[i - 1];
                        }
                    }
                    else
                    {
                        // W と仮定
                        if (S[i] == 'o')
                        {
                            // 両隣が異なる
                            sw[i + 1] = -sw[i - 1];
                        }
                        else
                        {
                            // 両隣が同じ
                            sw[i + 1] = sw[i - 1];
                        }
                    }
                }

                // 先頭と末尾チェック
                if (sw[0] != sw[N]) ok = false;

                if (ok)
                {
                    for (int i = 0; i < N; i++)
                    {
                        Console.Write(sw[i] == 1 ? 'S' : 'W');
                    }
                    Console.WriteLine();
                    return;
                }
            }
        }
        Console.WriteLine(-1);
    }
    static Scanner sc = new Scanner();
}
