public class Prog
{
    private const int INF = 1000000007;
    public struct Pair { public int x, y; public Pair(int x, int y) { this.x = x; this.y = y; } }
    public static void Solve()
    {
        int N = NextInt();
        string s = NextString();
        //決め打ちでどうにかする
        if (Menagerie(s, N, 1, 1)) return;
        if (Menagerie(s, N, 1, -1)) return;
        if (Menagerie(s, N, -1, 1)) return;
        if (Menagerie(s, N, -1, -1)) return;
        Console.WriteLine(-1);
    }
    public static bool Menagerie(string s, int N, int a, int b)
    {
        int[] ans = new int[N + 1];
        ans[0] = a;
        ans[1] = b;
        for (int i = 1; i < N; i++)
        {
            if (ans[i] == 1)
            {
                if (s[i] == 'o') ans[i + 1] = ans[i - 1];
                else ans[i + 1] = -ans[i - 1];
            }
            else
            {
                if (s[i] == 'o') ans[i + 1] = -ans[i - 1];
                else ans[i + 1] = ans[i - 1];
            }
        }
        if (ans[0] == ans[N])
        {
            for (int i = 0; i < N; i++) Console.Write(ans[i] == 1 ? "S" : "W");
            Console.WriteLine();
            return true;
        }
        else return false;
    }
    public static void Main()
    {
        var sw = new System.IO.StreamWriter(Console.OpenStandardOutput()) { AutoFlush = false };
        Console.SetOut(sw);
        Solve();
        Console.Out.Flush();
    }
