namespace AtCorder
{
	public class Program
	{
		static void Main(string[] args)
		{
			var cin = new Scanner2();
			int n = cin.Int();
			string s = cin.Next();

			var conds = new Tuple<bool, bool>[] {
				new Tuple<bool, bool>(true, true),
				new Tuple<bool, bool>(true, false),
				new Tuple<bool, bool>(false, true),
				new Tuple<bool, bool>(false, false),
			};

			var sim = new bool[n + 1];
			foreach (var cond in conds) {
				sim[0] = cond.Item1;
				sim[1] = cond.Item2;
				for (int i = 2; i < n + 1; i++) {
					sim[i] = (sim[i - 1] ^ s[i - 1] == 'o') ? !sim[i - 2] : sim[i - 2];
				}

				bool prev = (sim[0] ^ s[0] == 'o') ? !sim[1] : sim[1];
				if (sim[0] == sim[n] && sim[n - 1] == prev) {
					var result = new char[n];
					for (int i = 0; i < n; i++) {
						result[i] = sim[i] ? 'S' : 'W';
					}

					Console.WriteLine(new string(result));
					return;
				}
			}

			Console.WriteLine(-1);
		}
	}

	public class Scanner2
	{
		private readonly char[] delimiter_ = new char[] { ' ' };
		private readonly string filePath_;
		private string[] buf_;
		private int index_;
		Func<string> reader_;

		public Scanner2(string file = "")
		{
			if (string.IsNullOrWhiteSpace(file)) {
				reader_ = Console.ReadLine;
			} else {
				filePath_ = file;
				var fs = new StreamReader(file);
				reader_ = fs.ReadLine;
			}
			buf_ = new string[0];
			index_ = 0;
		}

		public string Next()
		{
			if (index_ < buf_.Length) {
				return buf_[index_++];
			}

			string st = reader_();
			while (st == "") {
				st = reader_();
			}

			buf_ = st.Split(delimiter_, StringSplitOptions.RemoveEmptyEntries);
			if (buf_.Length == 0) {
				return Next();
			}

			index_ = 0;
			return buf_[index_++];
		}

		public int Int() => int.Parse(Next());
		public long Long() => long.Parse(Next());
		public double Double() => double.Parse(Next());

		public int[] ArrayInt(int N, int add = 0)
		{
			int[] Array = new int[N];
			for (int i = 0; i < N; i++) {
				Array[i] = Int() + add;
			}
			return Array;
		}

		public long[] ArrayLong(int N, long add = 0)
		{
			long[] Array = new long[N];
			for (int i = 0; i < N; i++) {
				Array[i] = Long() + add;
			}
			return Array;
		}

		public double[] ArrayDouble(int N, double add = 0)
		{
			double[] Array = new double[N];
			for (int i = 0; i < N; i++) {
				Array[i] = Double() + add;
			}
			return Array;
		}

		public void Save(string text)
		{
			if (string.IsNullOrWhiteSpace(filePath_)) {
				return;
			}

			File.WriteAllText(filePath_ + "_output.txt", text);
		}
	}
}

