public class CompetitiveProgramming {
  public void Solve () {
    var N = Int1;
    var s = Str;

    //cur[k]==0 sheep
    //cur[k]==1 wolf
    for (int i = 0; i < 2; ++i) {
      for (int j = 0; j < 2; ++j) {
        var cur = Enumerable.Repeat (-1, N).ToArray ();
        cur[0] = i;
        cur[1] = j;

        for (int k = 2; k < N; ++k) {
          if (cur[k - 1] == 0) {
            if (s[k - 1] == 'o') {
              cur[k] = cur[k - 2];
            } else {
              cur[k] = (1 - cur[k - 2]);
            }
          } else {
            if (s[k - 1] == 'x') {
              cur[k] = cur[k - 2];
            } else {
              cur[k] = (1 - cur[k - 2]);
            }
          }
        }
        var flg = false;
        var flg2 = false;
        if (cur[N - 1] == 0 && s[N - 1] == 'o' && cur[N - 2] == cur[0]) flg = true;
        if (cur[N - 1] == 0 && s[N - 1] == 'x' && cur[N - 2] != cur[0]) flg = true;
        if (cur[N - 1] == 1 && s[N - 1] == 'o' && cur[N - 2] != cur[0]) flg = true;
        if (cur[N - 1] == 1 && s[N - 1] == 'x' && cur[N - 2] == cur[0]) flg = true;
        if (cur[0] == 0 && s[0] == 'o' && cur[N - 1] == cur[1]) flg2 = true;
        if (cur[0] == 0 && s[0] == 'x' && cur[N - 1] != cur[1]) flg2 = true;
        if (cur[0] == 1 && s[0] == 'o' && cur[N - 1] != cur[1]) flg2 = true;
        if (cur[0] == 1 && s[0] == 'x' && cur[N - 1] == cur[1]) flg2 = true;
        if (flg && flg2) {
          var ans = new StringBuilder ();

          for (int k = 0; k < N; ++k) {
            if (cur[i] == 0) ans.Append ('S');
            else ans.Append ('W');
          }
          Put (ans);
          return;
        }
      }
    }
    Put ("-1");
  }
}

public static class Math2 {
  public const int INF = 1 << 29;
  public const long INFL = 1L << 60;
  public const long MOD = 1000000007;
  public const int MOD2 = 998244353;

  public static long Power (long a, long b, long MOD = 1000000007) //i^N
  {
    long res = 1;
    while (b > 0) {
      if ((b & 1) != 0) res = res * a % MOD;
      a = a * a % MOD;
      b >>= 1;
    }
    return res;
  }
  public static long Power2 (long a, long b) //i^N
  {
    long res = 1;
    while (b > 0) {
      if ((b & 1) != 0) res = res * a;
      a = a * a;
      b >>= 1;
    }
    return res;
  }
  public static long GCD (long a, long b) {
    while (b > 0) {
      var r = a % b;
      a = b;
      b = r;
    }
    return a;
  }
  public static long LCM (long a, long b) => (b / GCD (a, b)) * a;
  public static long Comb (long n, long r, int MOD = 1000000007) {
    if (r > n - r) r = n - r;
    long Nume = 1;
    long Deno = 1;

    if (r > n - r) r = n - r;
    for (long i = 1; i <= r; ++i) {
      Deno = (Deno * i) % MOD;
      Nume = Nume * (n - i + 1) % MOD;
    }
    return (Nume * inv (Deno)) % MOD;
  }
  public static long Comb2 (long n, long r) {
    long Nume = 1;
    long Deno = 1;

    if (r > n - r) r = n - r;
    for (long i = 1; i <= r; ++i) {
      Deno *= i;
      Nume *= n - i + 1;
    }
    return Nume / Deno;
  }
  public static long inv (long x, int MOD = 1000000007) {
    return Power (x, MOD - 2, MOD);
  }
}
public static class Utils {
  public static void Swap<T> (ref T A, ref T B) {
    T x = A;
    A = B;
    B = x;
  }
  public static int DigitSum (int N) {
    string s = N.ToString ();
    int ret = 0;
    for (int i = 0; i < s.Length; ++i) ret += s[i] - '0';
    return ret;
  }
  public static string ConvertBase (long N, int K) {
    StringBuilder ret = new StringBuilder ();
    while (N > 0) {
      var r = N % K;
      N /= K;
      ret.Append (r);
    }
    return new string (ret.ToString ().ToCharArray ().Reverse ().ToArray ());
  }
}
