namespace AtCoderRegularContest069
{
    public class Program
    {
        static void Main(string[] args)
        {
            Console.WriteLine(program1(new String[] { Console.ReadLine(), Console.ReadLine() }));
        }

        public static string program1(string[] args)
        {
            var n = int.Parse(args[0]);
            var s = args[1].ToCharArray();

            var animalPattern = new List<char>[] { new List<char>() { 'C', 'C' }, new List<char> { 'C', 'W' }, new List<char> { 'W', 'W' }, new List<char> { 'W', 'C' } };

            return string.Join("", animalPattern.Select(animals =>
            {
                var prevAnimal = animals.First();

                foreach(var ans in s.Skip(1))
                {
                    var last = animals.Last();

                    if (last == 'C')
                    {
                        if (ans == 'x')
                        {
                            animals.Add(prevAnimal == 'C' ? 'W' : 'C');
                        }
                        else animals.Add(prevAnimal);
                    }
                    else
                    {
                        if (ans == 'o')
                        {
                            animals.Add(prevAnimal == 'C' ? 'W' : 'C');
                        }
                        else animals.Add(prevAnimal);
                    }
                    prevAnimal = last;
                }

                return animals;
            }).FirstOrDefault(animals => {
                if (animals.First() == animals.Last())
                {
                    if (s.First() == 'o')
                    {
                        return animals.ElementAt(1) == animals.ElementAt(n - 1);
                    }
                    else
                    {
                        return animals.ElementAt(1) != animals.ElementAt(n - 1);
                    }
                }
                else return false;
            })?.Take(n) ?? new List<char>() { '-', '1' }) ;
        }
    }
}

using System;
using System.Collections.Generic;
using System.Text;
using System.Linq;

class Program
{
    void solve()
    {
        int N = int.Parse(Console.ReadLine());
        string s = Console.ReadLine();

        byte[] said = new byte[N];
        byte[,] who = new byte[4, N];

        who[0, 0] = 0; who[0, N - 1] = 0;
        who[1, 0] = 0; who[1, N - 1] = 1;
        who[2, 0] = 1; who[2, N - 1] = 0;
        who[3, 0] = 1; who[3, N - 1] = 1;


        for (int i = 0; i < N; ++i)
            said[i] = (byte)(s[i] == 'o' ? 0 : 1);

        for (int i = 0; i < N; ++i)
        {
            for (int j = 0; j < 4; ++j)
            {
                who[j, (i + 1) % N] = (byte)(said[i] ^ who[j, (N + i - 1) % N] ^ who[j, i]);
            }
        }

        int k = -1;
        if (who[0, 0] == 0 && who[0, N - 1] == 0)
            k = 0;
        else if (who[1, 0] == 0 && who[1, N - 1] == 1)
            k = 1;
        else if (who[2, 0] == 1 && who[2, N - 1] == 0)
            k = 2;
        else if (who[3, 0] == 1 && who[3, N - 1] == 1)
            k = 3;

        string ans = string.Empty;
        if (k == -1)
        {
            ans = "-1";
        }
        else
        {
            StringBuilder sb = new StringBuilder();
            for (int i = 0; i < N; ++i)
            {
                sb.Append(who[k, i] == 1 ? 'W' : 'S');
                //ans += who[k, i] == 1 ? "W" : "S";
            }
            ans = sb.ToString();
        }
        Console.WriteLine(ans);
    }
    public static int Main()
    {
        bool loop = false;
#if ES_DEBUG
        loop = true;
#endif
        do
        {
            new Program().solve();
        } while (loop);
        return 0;
    }
}

