namespace ARC069
{
    public class D
    {
        private string F(int kind, string S)
        {
            bool isLastSheep = ((kind & 1) != 0);
            bool isFirstSheep = ((kind & 2) != 0);

            var builder = new StringBuilder();
            bool isPrevSheep = isLastSheep;
            bool isCurrentSheep = isFirstSheep;
            bool isNextSheep;
            for (int i = 0; i < S.Length - 2; ++i)
            {
                builder.Append(isCurrentSheep ? 'S' : 'W');
                if (isCurrentSheep)
                {
                    isNextSheep = ((S[i] == 'o') == isPrevSheep);
                }
                else
                {
                    isNextSheep = ((S[i] == 'o') != isPrevSheep);
                }
                isPrevSheep = isCurrentSheep;
                isCurrentSheep = isNextSheep;
            }

            if (isCurrentSheep != ((S[S.Length - 2] == 'o') == (isPrevSheep == isLastSheep))) { return null; }
            builder.Append(isCurrentSheep ? 'S' : 'W');

            if (isLastSheep != ((S[S.Length - 1] == 'o') == (isCurrentSheep == isFirstSheep))) { return null; }
            builder.Append(isLastSheep ? 'S' : 'W');
            return builder.ToString();
        }

        private void Run()
        {
            var N = int.Parse(Console.ReadLine().Trim());
            var S = Console.ReadLine().Trim();

            Console.WriteLine(Enumerable.Range(0, 4).Select(i => F(i, S)).FirstOrDefault(s => s != null) ?? "-1");
        }

        public static void Main()
        {
            var old = Console.Out;
            using (var writer = new System.IO.StreamWriter(Console.OpenStandardOutput()) { AutoFlush = false })
            {
                Console.SetOut(writer);
                new D().Run();
                Console.Out.Flush();
                Console.SetOut(old);
            }
        }
    }
}

using System;

namespace D_Menagerie {
    class Program {
        static string Solve(string input) {
            var N = input.Length;
            var prefs = new string[]{"SS", "SW", "WS", "WW"};
            foreach (var pref in prefs) {
                var ans = pref;
                char x, y, a;
                y = ans[0];
                for (int i = 2; i < N; i++) {
                    x = y; y = ans[i - 1]; a = input[i - 1];
                    ans += (y == 'S') ^ (a == 'o') ^ (x == 'S') ? 'S': 'W';
                }
                x = y; y = ans[N - 1]; a = input[N - 1];
                var invalid = (ans[0] == 'S') ^ (y == 'S') ^ (a == 'o') ^ (x == 'S');
                x = y; y = ans[0]; a = input[0];
                invalid |= (ans[1] == 'S') ^ (y == 'S') ^ (a == 'o') ^ (x == 'S');
                if (!invalid) return ans;
            }
            return "-1";
        }
        static void Main(string[] args) {
            var N = int.Parse(Console.ReadLine());
            var str = Console.ReadLine();
            Console.WriteLine(Solve(str));
        }
    }
}

