    class Problem : IDisposable
    {
        bool IsGCJ;
        int Repeat;
        Scanner sc;
        Printer pr;
        public Problem(bool isGCJ, Scanner scanner, Printer printer)
        {
            sc = scanner;
            pr = printer;
            IsGCJ = isGCJ;
            if (isGCJ) Repeat = sc.nextInt();
            else Read();
        }
        public Problem(bool isGCJ) : this(isGCJ, new Scanner(), new Printer()) { }
        public Problem(bool isGCJ, Scanner scanner) : this(isGCJ, scanner, new Printer()) { }
        public Problem(bool isGCJ, Printer printer) : this(isGCJ, new Scanner(), printer) { }
        public void Solve()
        {
            if (IsGCJ) for (var i = 0; i < Repeat; i++) { Read(); pr.Write("Case #" + (i + 1) + ": "); SolveOne(); }
            else SolveOne();
        }
        public void Dispose()
        {
            sc.Dispose();
            pr.Dispose();
        }
        public int Size { get { return 1; } }
        public const long Mod = 1000000007;

        // 使用する変数をここに書く
        // string S;
        // int a;
        bool[] isSheep;
        int n;
        string s;

        /// <summary>
        /// 読み込み処理をここに書く
        /// </summary>
        void Read()
        {

        }
        /// <summary>
        /// メイン処理をここに書く
        /// </summary>
        void SolveOne()
        {
            n = sc.nextInt();
            s = sc.next();
            s += s[0];
            isSheep = new bool[n + 2];

            // SS**
            isSheep = new bool[n + 2];
            isSheep[0] = true;
            isSheep[n] = true;
            isSheep[1] = true;
            isSheep[n + 1] = true;
            if (Judge()) return;

            // SW**
            isSheep = new bool[n + 2];
            isSheep[0] = true;
            isSheep[n] = true;
            if (Judge()) return;

            // WS**
            isSheep = new bool[n + 2];
            isSheep[1] = true;
            isSheep[n + 1] = true;
            if (Judge()) return;

            // WW**
            isSheep = new bool[n + 2];
            if (Judge()) return;

            // else
            Console.WriteLine(-1);
            return;

        }

        private bool Judge()
        {
            for (int i = 1; i <= n; i++)
            {
                if (isSheep[i])
                {
                    if (s[i] == 'o')
                    {
                        isSheep[i + 1] = isSheep[i - 1];
                    }
                    else
                    {
                        isSheep[i + 1] = !isSheep[i - 1];
                    }
                }
                else
                {
                    if (s[i] == 'o')
                    {
                        isSheep[i + 1] = !isSheep[i - 1];
                    }
                    else
                    {
                        isSheep[i + 1] = isSheep[i - 1];
                    }
                }
            }
            if (isSheep[0] == isSheep[n] && isSheep[1] == isSheep[n + 1])
            {
                StringBuilder sb = new StringBuilder();
                for (int i = 0; i < n; i++)
                {
                    if (isSheep[i]) sb.Append('S');
                    else sb.Append('W');
                }
                Console.WriteLine(sb.ToString());

                return true;
            }
            else return false;
        }
    }
