    private string Solve(string s, bool isSheep1, bool isSheep2) {
        var builder = new StringBuilder();
        builder.Append(isSheep1 ? 'S' : 'W');
        builder.Append(isSheep2 ? 'S' : 'W');

        for (int i = 1; i < s.Length + 10; i++) {
            if (s[i % s.Length] == 'o' ^ builder[i] == 'W') { // same
                builder.Append(builder[i - 1]);
            } else { // diff
                builder.Append(builder[i - 1] == 'W' ? 'S' : 'W');
            }
        }

        for (int i = 0; i + s.Length < builder.Length; i++) {
            if (builder[i] != builder[i + s.Length]) return null;
        }

        return builder.ToString().Substring(0, s.Length);
    }
}

