          s[j-1] == 'o' && answers[j-1] == "W")
        {
          if(answers[j-2] == "S") answers[j] = "W";
          else answers[j] = "S";
        }
      }

      if(s[n-1] == 'o' && answers[n-1] == "S" ||
        s[n-1] == 'x' && answers[n-1] == "W")
      {
        if(answers[0] != answers[n-2]) continue;
