			for (var i = 0; i < N; i++) s[i] = S[i] == 'o';
			var b = new bool[N];
			for (var x = 0; x < 2; x++)
				for (var y = 0; y < 2; y++)
				{
					b[0] = x == 1;
					b[1] = y == 1;
					for (var i = 1; i + 1 < N; i++) b[i + 1] = b[i - 1] == (b[i] == s[i]);
					if ((s[0] == b[0]) == (b[1] == b[N - 1]) && (s[N - 1] == b[N - 1]) == (b[N - 2] == b[0]))
					{
						pr.WriteLine(string.Join("", b.Select(z => z ? "S" : "W")));
						return;
					}
				}
			pr.WriteLine(-1);
		}
		int[] SuffixArray(string S)
		{
			var N = S.Length;
			var sa = new int[N + 1];
			var r = new int[N + 1];
			for (var i = 0; i <= N; i++)
			{
				sa[i] = i;
				r[i] = i < N ? S[i] : -1;
			}
			var k = 1;
			Comparison<int> comp = (i, j) =>
			  {
				  if (r[i] != r[j]) return r[i] - r[j];
				  var a = i + k <= N ? r[i + k] : -1;
				  var b = j + k <= N ? r[j + k] : -1;
				  return a - b;
			  };
			for (; k <= N; k *= 2)
			{
				Array.Sort(sa, comp);
				var tmp = new int[N + 1];
				for (var i = 1; i <= N; i++) tmp[sa[i]] = tmp[sa[i - 1]] + (comp(sa[i - 1], sa[i]) < 0 ? 1 : 0);
				r = tmp;
			}
			return sa;
		}
	}
