        const bool wolf = false;

        bool IsValid(bool[] cur)
        {
            if (s[0] == 'o')
            {
                if (cur[0])
                {
                    if (cur[cur.Length - 1] != cur[1]) return false;
                }
                else if (cur[cur.Length - 1] == cur[1]) return false;
            }
            else
            {
                if (!cur[0])
                {
                    if (cur[cur.Length - 1] != cur[1]) return false;
                }
                else if (cur[cur.Length - 1] == cur[1]) return false;
            }

            if (s[s.Length - 1] == 'o')
            {
                if (cur[cur.Length - 1])
                {
                    if (cur[cur.Length - 2] != cur[0]) return false;
                }
                else if (cur[cur.Length - 2] == cur[0]) return false;
            }
            else
            {
                if (!cur[cur.Length - 1])
                {
                    if (cur[cur.Length - 2] != cur[0]) return false;
                }
                else if (cur[cur.Length - 2] == cur[0]) return false;
            }
            return true;
        }
