                    case 'o':
                        cur[index + 1] = cur[index - 1];
                        break;
                    case 'x':
                        cur[index + 1] = !cur[index - 1];
                        break;
                }
            }
            else
            {
                switch (s[index])
                {
                    case 'o':
                        cur[index + 1] = !cur[index - 1];
                        break;
                    case 'x':
                        cur[index + 1] = cur[index - 1];
                        break;
                }
            }

        }


