        //    said[i] = (byte)(s[i] == 'o' ? 0 : 1);

        for (int i = 0; i < N; ++i)
        {
            for (int j = 0; j < 4; ++j)
            {
                who[j][(i + 1) % N] = ((s[i] == 'o' ? 0 : 1) ^ (who[j][(N + i - 1) % N] == 'S' ? 0 : 1) ^ (who[j][i] == 'S' ? 0 : 1)) == 1 ? 'W' : 'S';
            }
        }

        int k = -1;
