using System;

class p
{

    //i,i+1文字目からi-1文字目を決めて返す
    static char backChar(string s,char[] temp,int i)
    {
        if (temp[i] == 'S')//i文字目が羊
        {
            if (s[i] == 'o')//羊かつ〇なら両側が同じ
                return temp[i + 1];
            else //羊かつ×なら両側が異なる
            {
                if (temp[i + 1] == 'S') return 'W';
                else return 'S';
            }
        }
        else //i文字目が狼
        {
            if (s[i] == 'x')//狼かつ×なら両側が同じ
                return temp[i + 1];
            else //狼かつ〇なら両側が異なる
            {
                if (temp[i + 1] == 'S') return 'W';
                else return 'S';
            }
        }
    }

    //i-1,i文字目からi+1文字目を決めて返す
    static char nextChar(string s,char[] temp,int i)
    {
        if (temp[i] == 'S')//i文字目が羊
        {
            if (s[i] == 'o')//羊かつ〇なら両側が同じ
                return temp[i - 1];
            else //羊かつ×なら両側が異なる
            {
                if (temp[i - 1] == 'S') return 'W';
                else return 'S';
            }
        }
        else //i文字目が狼
        {
            if (s[i] == 'x')//狼かつ×なら両側が同じ
                return temp[i - 1];
            else //狼かつ〇なら両側が異なる
            {
                if (temp[i - 1] == 'S') return 'W';
                else return 'S';
            }
        }
    }

    static void Main(string[] a)
    {
        int N = int.Parse(Console.ReadLine());
        string s = Console.ReadLine();
        //s は o と x のみからなる長さ N の文字列
        char[] t = new char[N];
        //t は長さ N で S と W のみからなる文字列;解がない場合の-1を代入
        char[] temp = new char[N];
        //１，２文字目を仮定してシミュレーションするための文字列temp
        char lastNext;
        char firstBack;
        bool flag = false;

        string[] strarray = { "SS", "SW", "WS", "WW" };

        foreach (string str in strarray)
        {
            if (flag != false) break;
            temp[0] = str[0];
            temp[1] = str[1];
            for (int i = 1; i < N - 1; i++)
            {
                temp[i + 1] = nextChar(s, temp, i);
            }
            lastNext = nextChar(s, temp, N - 1);
            firstBack = backChar(s, temp, 0);
            if (lastNext == temp[0] && firstBack == temp[N - 1])
            {
                flag = true;
                for (int i = 0; i < N; i++)
                    t[i] = temp[i];
            }
        }

        if (flag)
        {
            for (int i = 0; i < N; i++) Console.Write(t[i]);
        }
        else Console.Write("-1");
        Console.WriteLine();

    }
}

using System;

namespace D_Menagerie {
    class Program {
        static string Solve(string input) {
            var N = input.Length;
            var prefs = new string[]{"SS", "SW", "WS", "WW"};
            foreach (var pref in prefs) {
                var ans = pref;
                for (int i = 2; i < N; i++) {
                    ans += Guess(ans[i - 1], ans[i - 2], input[i - 1]);
                }
                var valid = ans[0] == Guess(ans[N - 1], ans[N - 2], input[N - 1]) && ans[1] == Guess(ans[0], ans[N - 1], input[0]);
                if (valid) return ans;
            }
            return "-1";
        }
        static char Guess(char x, char y, char a) {
            var flag = (y == 'S') ^ (a == 'o') ^ (x == 'S');
            return flag? 'S': 'W';
        }
        static void Main(string[] args) {
            var N = int.Parse(Console.ReadLine());
            var str = Console.ReadLine();
            Console.WriteLine(Solve(str));
        }
    }
}

