                int m = s[i] == 'o' ? 0 : 1;
                int n2 = n0 ^ n1 ^ m;

                str[(i + 1) % N] = n2 == 0 ? 'S' : 'W';

                n0 = n1;
                n1 = n2;
            }

            if (n0 == j % 2 && n1 == j / 2) {
                Console.WriteLine(new string(str));
                return;
            }
        }

        Console.WriteLine("-1");
    }
}

