namespace AtCoder.ARC.D069
{
    using System;
    using System.Collections.Generic;
    using System.Linq;
    using System.Numerics;
    using System.IO;

    using AtCoder.ARC.IO;

    public class Quest
    {
        public object Solve(Parser parser)
        {
            int n = parser.Integer();

            var s = parser.ScanLine();

            string r = "";
            if (Assume(s, 'S', 'S', out r))
            {
                return r;
            }

            if (Assume(s, 'W', 'S', out r))
            {
                return r;
            }

            if (Assume(s, 'S', 'W', out r))
            {
                return r;
            }

            if (Assume(s, 'W', 'W', out r))
            {
                return r;
            }

            return "-1";
        }

        bool Assume(string s, char c0, char c1, out string ans)
        {
            var n = s.Length;
            var ans1 = new char[n];

            ans1[0] = c0;
            ans1[1] = c1;

            for (int i = 0; i < n - 2; i++)
            {
                ans1[i + 2] = Ask(s[i + 1] == 'o', ans1[i], ans1[i + 1]);
            }

            ans = String.Join("", ans1).TrimEnd(new char[] { ' ' });

            return ans1[0] == Ask(s[n - 1] == 'o', ans1[n - 2], ans1[n - 1]);
        }

        private char Ask(bool matched, char left, char right)
        {
            if (left == right)
            {
                return matched ? 'S' : 'W';
            }
            return matched ? 'W' : 'S';
        }
    }

    static class Program
    {
        static void Main(string[] args)
        {
            var i = new Parser(Console.OpenStandardInput());
            var o = new Printer(Console.OpenStandardOutput());
            var got = new Quest().Solve(i);
            o.WriteLine(got);
            o.Flush();
        }
    }
