func solve(an0, an1, n int, s string) (bool, string) {
	ans := make([]int, n)
	ans[0] = an0
	ans[1] = an1
	for i := 0; i < n-2; i++ {
		if ans[(i+1)%n] == 0 {
			if s[i+1] == 'o' {
				ans[(i+2)%n] = ans[i]
			} else {
				ans[(i+2)%n] = 1 - ans[i]
			}
			continue
		}
		if s[i+1] == 'o' {
			ans[(i+2)%n] = 1 - ans[i]
		} else {
			ans[(i+2)%n] = ans[i]
		}
	}

	ss := make([]string, n)
	animal := map[int]string{
		0: "S",
		1: "W",
	}
	for i := 0; i < n; i++ {
		ss[i] = animal[ans[i]]
	}

	animals := strings.Join(ss, "")
	for i := 0; i < n; i++ {
		if ans[i] == 0 {
			if s[i] == 'o' && ans[(i-1+n)%n] != ans[(i+1+n)%n] {
