    for i:=0;i<n;i++ { fmt.Print(d[m[i]]) }
    fmt.Println()
    os.Exit(0)
  }
  fmt.Println(-1)
}
func check(n int,s string,m0 int,m1 int) ([]int,bool) {
  var m []int = make([]int,n)
  m[0],m[1] = m0,m1
  for i:=1;i<n-1;i++ {
    if (m[i] == 0) == (s[i:i+1] == "o") {
      m[i+1] = m[i-1]
    } else {
      m[i+1] = 1-m[i-1]
    }
  }
  if (m[n-1] == 0) == (s[n-1:n] == "o") {
    if m[n-2] == m[0] { return m,true }
  } else {
    if m[n-2] == 1-m[0] { return m,true }
  }
  return nil,false
}

