var S string
var current []byte

func dfs(p int) bool {
	isReverse := true
	switch {
	case current[p] == 'S' && S[p] == 'x':
		isReverse = true
	case current[p] == 'W' && S[p] == 'x':
		isReverse = false
	case current[p] == 'S' && S[p] == 'o':
		isReverse = false
	case current[p] == 'W' && S[p] == 'o':
		isReverse = true
	}

	next := current[p-1]
	if isReverse {
		if next == 'S' {
			next = 'W'
		} else {
			next = 'S'
		}
	}

	if p == len(current)-1 {
		flag := current[0] == next
		if flag {
			firstSame := current[p] == current[1]
			if current[0] == 'S' && S[0] == 'o' || current[0] == 'W' && S[0] == 'x' {
			} else {
				firstSame = !firstSame
			}
			return firstSame
		}
		return false
	}

	current[p+1] = next

	if dfs(p + 1) {
		return true
	}
	return false
}
func output() string {
	return string(current)
}

