func check(N int, s string, v string) string {
	t := make([]byte, N)
	copy(t, v)
	for i := 2; i < N; i++ {
		if (t[i-1] == 'S' && s[i-1] == 'o') || (t[i-1] == 'W' && s[i-1] == 'x') {
			t[i] = t[i-2]
		} else {
			t[i] = not(t[i-2])
		}
	}

	for i := 0; i < N; i++ {
		if (t[i] == 'S' && s[i] == 'o') || (t[i] == 'W' && s[i] == 'x') {
			if t[(N+i-1)%N] != t[(i+1)%N] {
				return ""
			}
		}
		if (t[i] == 'S' && s[i] == 'x') || (t[i] == 'W' && s[i] == 'o') {
			if t[(N+i-1)%N] == t[(i+1)%N] {
				return ""
			}
		}
	}
	return string(t)
}

