func main() {
	fp := os.Stdin
	wfp := os.Stdout

	if os.Getenv("MASPY") == "ますピ" {
		fp, _ = os.Open(os.Getenv("BEET_THE_HARMONY_OF_PERFECT"))
	}
	if os.Getenv("MASPYPY") == "ますピッピ" {
		wfp, _ = os.Create(os.Getenv("NGTKANA_IS_GENIUS10"))
	}

	scanner := getScanner(fp)
	writer := bufio.NewWriter(wfp)

	n := getNextInt(scanner)
	s := getNextString(scanner)

	for i := 0; i < 2; i++ {
		for j := 0; j < 2; j++ {
			ok, ans := solve(i, j, n, s)
			if ok {
				fmt.Println(ans)
				return
			}
		}
	}

	fmt.Fprintln(writer, -1)
	writer.Flush()
}

func solve(an0, an1, n int, s string) (bool, string) {
	ans := make([]int, n)
	ans[0] = an0
	ans[1] = an1
	for i := 0; i < n-2; i++ {
		if ans[(i+1)%n] == 0 {
			if s[i+1] == 'o' {
				ans[(i+2)%n] = ans[i]
			} else {
				ans[(i+2)%n] = 1 - ans[i]
			}
			continue
		}
		if s[i+1] == 'o' {
			ans[(i+2)%n] = 1 - ans[i]
		} else {
			ans[(i+2)%n] = ans[i]
		}
	}

	ss := make([]string, n)
	animal := map[int]string{
		0: "S",
		1: "W",
	}
	for i := 0; i < n; i++ {
		ss[i] = animal[ans[i]]
	}

	if ans[n-1] == 0 {
		if s[n-1] == 'o' {
			return (ans[n-2] == ans[0]), strings.Join(ss, "")
		}
		return (ans[n-2] != ans[0]), strings.Join(ss, "")
	}
	if s[n-1] == 'o' {
		return (ans[n-2] != ans[0]), strings.Join(ss, "")
	}
	return (ans[n-2] == ans[0]), strings.Join(ss, "")
}

