	first := list[0]
	firstAns := ox[0]
	last := list[len(list) - 1]
	lastAns := ox[len(ox) - 1]
	res := true
	if first == "S" {
		if firstAns == "o" {
			res = res && (list[1] == last)
		} else {
			res = res && (list[1] != last)
		}
	} else {
		if firstAns == "o" {
			res = res && (list[1] != last)
		} else {
			res = res && (list[1] == last)
		}
	}
	if last == "S" {
		if lastAns == "o" {
			res = res && (list[len(list) - 2] == first)
		} else {
			res = res && (list[len(list) - 2] != first)
		}
	} else {
		if lastAns == "o" {
			res = res && (list[len(list) - 2] != first)
		} else {
			res = res && (list[len(list) - 2] == first)
		}
	}
	return res
}

