import * as fs from 'fs';

export class Reader {
    lines: string[];
    currentLine: number;

    constructor() {
        this.lines = fs.readFileSync("/dev/stdin", "utf8").trim().split("\n");
        this.currentLine = 0;
    }

    readLine(): string {
        return this.lines[this.currentLine++];
    }

	readChars(): string[] {
		let S = this.readLine();
		return new Array(S.length).fill(null).map((_, i) => S.charAt(i));
	}

    readInt(): number {
        return Number(this.readLine());
    }

    readInts(): number[] {
        return this.readLine().split(" ").map(Number);
    }
} 


function solve(): string {
	let reader = new Reader();
	let N = reader.readInt();
	let s = reader.readLine();
	let isSheep: (boolean|null)[] = new Array(N).fill(false);

	for(let first of [false, true]) {
		for(let second of [false, true]) {
			isSheep.fill(null)
			isSheep[0] = first;
			isSheep[1] = second;
			let found = true;
			for(let i=2; i<N+3; i++) {
				let i2 = (i-2)%N, i1 = (i-1)%N, i0 = i%N;
				let current: null|boolean = null;
				if (isSheep[i1]) {
					if (s.charAt(i1) == 'o') {
						current = isSheep[i2];
					} else {
						current = !isSheep[i2];
					}
				} else {
					if (s.charAt(i1) == 'o') {
						current = !isSheep[i2];
					} else {
						current = isSheep[i2];
					}
				}
				if (isSheep[i0] == null) {
					isSheep[i0] = current;
				} else {
					if (isSheep[i0] != current) {
						found = false;
						break
					}
					isSheep[i0] = current;
				}
			}
			if (found) {
				return isSheep.map((value) => value?'S': 'W').join("");
			}
		}
	}
	return '-1';
}


