bool next(in string s, long i, bool ai, bool aii) {
    if(aii) {
        if(s[(i+1)%s.length] == 'o') {
            return ai;
        } else {
            return !ai;
        }
    } else {
        if(s[(i+1)%s.length] == 'o') {
            return !ai;
        } else {
            return ai;
        }
    }
}

bool test(in string s, bool a0, bool a1) {
    bool ai = a0;
    bool aii = a1;
    foreach(i; iota(s.length)) {
        bool tmp = next(s, i, ai, aii);
        ai = aii;
        aii = tmp;
    }
    return ai == a0 && aii == a1;
}

string solve(in string s, bool a0, bool a1) {
    bool ai = a0;
    bool aii = a1;

    char toStr(bool b) {
        return b ? 'S': 'W';
    }

    string ret = [toStr(a0), toStr(a1)];
    foreach(i; iota(s.length)) {
        bool tmp = next(s, i, ai, aii);
        ai = aii;
        aii = tmp;
        ret ~= toStr(aii);
    }
    return ret[0..s.length];
}

