struct ModIntT(T = int, T MOD = 1_000_000_007)
if(isIntegral!T)
{
    alias value this;
    T value;


    this(U)(U u)
    if(isIntegral!U)
    {
        value = cast(T)(u % MOD);
    }


    ModInt opBinary(string op, U)(U u)
    if(op == "+" || op == "-" || op == "*" || op == "/")
    {
      static if(is(U : typeof(this)))
      {
        static if(op == "+")
          return typeof(this)((this.value + u.value));
        else static if(op == "-")
          return typeof(this)((this.value + MOD - u.value));
        else static if(op == "*")
          return typeof(this)((cast(long)this.value * cast(long)u.value));
        else static if(op == "/")
          return u^^(MOD-2) * this.value;
        else static assert(0);
      }
      else static if(isIntegral!U)
        return this.opBinary!op(typeof(this)(u));
      else static assert(0);
    }


    ModInt opBinary(string op : "^^", U)(U u)
    if(isIntegral!U)
    {
        if(u == 0) return ModInt(1);
        else if(u % 2 == 0){
            long d = cast(long)this.opBinary!"^^"(u / 2);
            return ModInt(d * d);
        }else
            return ModInt((cast(long)this) * cast(long)this.opBinary!"^^"(u-1));
    }


    string toString() { return value.to!string; }

    U opCast(U)() { return cast(U)value; }

    void opAssign(U)(U u) if(isIntegral!U) { value = u % MOD; }
}


alias ModInt = ModIntT!int;
alias ModLong = ModIntT!long;

unittest
