void main()
{
    auto N = scanElem;
    auto S = scanString;

    auto list = new long[N];
    foreach(init; [[0,0], [0,1], [1,0], [1,1]])
    {
        list[0] = init[0];
        list[1] = init[1];
        foreach(i;2..N){
            auto p2 = list[i-2];
            auto p1 = list[i-1];

            auto s = S[i-1];
            if((s=='o'&&p1.isSheep)||(s=='x'&&!p1.isSheep))
            {
                list[i] = p2;
            }else{
                list[i] = 1-p2;
            }
        }
        if(
            ((list[$-2]==list[0])&&((S[$-1]=='o'&&list[$-1].isSheep)||(S[$-1]=='x'&&!list[$-1].isSheep)))||
            ((list[$-2]!=list[0])&&((S[$-1]=='x'&&list[$-1].isSheep)||(S[$-1]=='o'&&!list[$-1].isSheep)))
            )
        {
            foreach(e; list)
            {
                if(e.isSheep)
                {
                    write('S');
                }else{
                    write('W');
                }
            }
            writeln();
            return;
        }
    }
    writeln(-1);
}

