        {
            long l = (N + i - 1) % N;
            long r = (i + 1) % N;
            if (ans[i] == 'S' && S[i] == 'o' && ans[l] != ans[r])
                continue outer;
            if (ans[i] == 'S' && S[i] == 'x' && ans[l] == ans[r])
