def solve(votes):
    for start in [(1, 1), (1, 0), (0, 1), (0, 0)]:
        a = animals(start, votes)
        if a[:2] == a[-2:]:
            return a


def animals(start, votes):
    rv = [None] * len(votes)
    rv[:2] = start
    for i in range(1, len(votes) - 1):
        rv[i + 1] = rv[i - 1] ^ rv[i] ^ votes[i]
    return tuple(rv)


def parse(s):
    return tuple(int(v == "o") for v in s + s[:2])


def display(s):
    if not s:
        return "-1"
    return "".join("S" if v else "W" for v in s[:-2])


