def check(a: str, b: str) -> tuple:
    ret, prev, cur = a + b, a, b
    for i in S[1:]:
        if cur == "S":
            if i == "o":
                ret += prev
                prev, cur = cur, prev
            else:
                x = "W" if prev == "S" else "S"
                ret += x
                prev, cur = cur, x
        else:
            if i == "o":
                x = "W" if prev == "S" else "S"
                ret += x
                prev, cur = cur, x
            else:
                ret += prev
                prev, cur = cur, prev
    return ret[:-1], cur


