def f(a0,a1, N,s, A):
    A[0] = a0
    A[1] = a1
    WOLF = -1
    SHEEP = 1
    for i in range(2,N):
        if s[i-1] == "o" and A[i-1] == WOLF:
            A[i] = -A[i-2]
        elif s[i-1] == "o" and A[i-1] == SHEEP:
            A[i] = A[i-2]
        elif s[i-1] == "x" and A[i-1] == SHEEP:
            A[i] = -A[i-2]
        elif s[i-1] == "x" and A[i-1] == WOLF:
            A[i] = A[i-2]
    for i in range(N):
        same = A[(i-1)%N] == A[(i+1)%N]
        if A[i] == WOLF:
            if  s[i] == "o" and same or s[i] == "x" and not same:
                return False
        if A[i] == SHEEP:
            if  s[i] == "x" and same or s[i] == "o" and not same:
                return False
    return True



