    F = [init[0], init[1]]
    for i, s in enumerate(S):
        if i == 0:
            continue
        d = 1 if s == "o" else -1
        F.append(F[i - 1] * F[i] * d)

    if F[0] != F[-1]:
        return None

    d = 1 if S[0] == "o" else -1
    d *= F[0]
    N = len(S)
    if F[-2] * F[1] == d:
        # print(F)
        return F[:N]
    else:
        return None


