    ans = seed
    for i in range(1, n):
        a, b = ans[-1], ans[-2]
        if int(s[i]) ^ int(b) == 0:
            ans.append(a)
        else:
            ans.append(nt(a))

    if ans[-1] != ans[0]:
        return []
    else:
        del(ans[-1])
        # print(ans)
        if int(s[0]) ^ int(ans[0]) == 0:
            if ans[-1] != ans[1]:
                return []
        else:
            if ans[-1] == ans[1]:
