def menagerie():
	# The key idea is that, if we konw the first two animals
	# by input, we could derive all the others
	n = int(raw_input())
	ans = str(raw_input())

	def _check(f, s, ans):
		siz = len(ans)
		re = ['#']*siz
		re[0] = f
		re[1] = s
		for i in range(1, siz-1):
			_temp_ans = ans[i]
			if re[i]==1:
				if _temp_ans=='o':
					re[i+1] = re[i-1]
				else:
					re[i + 1] = re[i - 1]*(-1)
			if re[i]==-1:
				if _temp_ans=='o':
					re[i+1] = re[i-1]*(-1)
				else:
					re[i + 1] = re[i - 1]
		# check ans[0] and ans[-1]
		c1 = False
		c2 = False
		if re[1]*re[-1]==1:
			if re[0]==1 and ans[0]=='o':
				c1 = True
			if re[0]==-1 and ans[0]=='x':
				c1 = True
		else:
			if re[0]==1 and ans[0]=='x':
				c1 = True
			if re[0]==-1 and ans[0]=='o':
				c1 = True

		if re[-2]*re[0]==1:
			if re[-1]==1 and ans[-1]=='o':
				c2 = True
			if re[-1]==-1 and ans[-1]=='x':
				c2 = True
		else:
			if re[-1]==1 and ans[-1]=='x':
				c2 = True
			if re[-1]==-1 and ans[-1]=='o':
				c2 = True
		if c1 and c2:
			return re
		else:
			return -1
	# w:-1; s:1
	re1 = _check(-1, -1, ans)
	re2 = _check(-1, 1, ans)
	re3 = _check(1, 1, ans)
	re4 = _check(1, -1, ans)

	if re1 != -1:
		op = ['s' if x==1 else 'w' for x in re1]
		print ''.join(op)
		return
	if re2 != -1:
		op = ['s' if x==1 else 'w' for x in re2]
		print ''.join(op)
		return
	if re3 != -1:
		op = ['s' if x==1 else 'w' for x in re3]
		print ''.join(op)
		return
	if re4 != -1:
		op = ['s' if x==1 else 'w' for x in re4]
		print ''.join(op)
		return
	print -1

