def solver(a, b):
	r = [a, b]
	for _ in xrange(n-2):
		r.append(None)

	for i in xrange(1, n):
		last = r[i-1]
		next = (i+1) % n
		if r[i] == 'S':
			if s[i] == 'o':
				r[next] = last
			else:
				r[next] = 'S' if last == 'W' else 'W'
		else:
			if s[i] == 'o':
				r[next] = 'S' if last == 'W' else 'W'
			else:
				r[next] = last

	if r[0] == 'S':
		if s[0] == 'o':
			return r[-1] == r[1], r
		else:
			return r[-1] != r[1], r
	else:
		if s[0] == 'o':
			return r[-1] != r[1], r
		else:
			return r[-2] == r[1], r

