fn order(v: &mut Vec<char>, o: &Vec<char>) -> bool {
    let l = o.len();
    for i in 2..l+1 {
        if (v[i-1] == 'S') ^ (v[i-2] == 'S') ^ (o[i-1] == 'o') {
            v.push('S');
        } else {
            v.push('W');
        }
    }
    v.pop().unwrap() == v[0]
}

use std::io::{stdin, Read};

macro_rules! parse {
    ($it: ident) => {
        $it.next().unwrap().parse().unwrap()
    };
    ($it: ident,2) => {
        (parse!($it), parse!($it))
    };
    ($it: ident,3) => {
        (parse!($it), parse!($it), parse!($it))
    };
    ($it: ident,4) => {
        (parse!($it), parse!($it), parse!($it), parse!($it))
    };
    ($it: ident, $n: expr) => {
        (&mut $it).take($n).map(|e| e.parse().unwrap()).collect();
    };
}

fn solve(s: &str) {
    let mut it = s.split_whitespace();
    let n: usize = parse!(it);
    let s: Vec<bool> = it.next().unwrap().chars().map(|x| x == 'o').collect();
    let mut ok = false;
    let mut ret = vec![];
    let next = |prev: bool, cur: bool, sym: bool| {
        if !(cur ^ sym) {
            prev
        } else {
            !prev
        }
    };
    'outer: for &i in &[true, false] {
        for &j in &[true, false] {
            let mut hyp = vec![false; n];
            hyp[0] = i;
            hyp[1] = j;
            for k in 1..(n - 1) {
                hyp[k + 1] = next(hyp[k - 1], hyp[k], s[k]);
            }
            if hyp[0] == next(hyp[n - 2], hyp[n - 1], s[n - 1])
                && hyp[1] == next(hyp[n - 1], hyp[0], s[0])
            {
                ok = true;
                ret = hyp;
                break 'outer;
            }
        }
    }
    if ok {
        println!(
            "{}",
            ret.into_iter()
                .map(|b| if b { 'S' } else { 'W' })
                .collect::<String>()
        );
    } else {
        println!("{}", -1);
    }
}

