            if if res[u][i+1] == 1 { no1 } else { !no1 } {
                k = 1 - k;
            }
            res[u].push(k);
        }
    }
    for ref u in res {
        if u[n] == u[0] && u[n+1] == u[1] {
            for i in 1..n+1 {
                print!("{}", if u[i] == 0 {"S"} else {"W"});
            }
            println!("");
            return;
        }
    }
    println!("-1");
}

