fn mk_ring(s: &[char], x0: bool, x1: bool) -> Option<Vec<bool>> {
    let n = s.len();
    let mut res = vec![x0, x1];
    let mut cur = 1;
    loop {
        let a = res[cur-1];
        let b = res[cur];
        let next = if s[cur%n] == 'o' {
            match (a, b) {
                (false, true) => false,
                (false, false) => true,
                (true, false) => false,
                (true, true) => true,
            }
        } else {
            match (a, b) {
                (false, true) => true,
                (false, false) => false,
                (true, false) => true,
                (true, true) => false,
            }
        };
        res.push(next);
        cur += 1;

        if cur==n+1 {
            break;
        }
    }

    assert!(res.len() == n+2);
    if res[0]==res[n] && res[1]==res[n+1] {
        res.remove(n+1);
        res.remove(n);
        Some(res)
    } else {
        None
    }
}
