fn check(a0: i32, a1: i32, s: &Vec<char>) -> Option<Vec<i32>> {
    let n = s.len();
    let mut ans = vec![0; n];
    ans[0] = a0;
    ans[1] = a1;
    for i in 1..n-1 {
        match (s[i], ans[i]) {
            ('o', -1) => ans[i+1] = ans[i-1],
            ('x', -1) => ans[i+1] = -ans[i-1],
            ('o', 1) => ans[i+1] = -ans[i-1],
            _ => ans[i+1] = ans[i-1]
        }
    }
    for i in n-1..n+1 {
        if !(match (s[i%n], ans[i%n]) {
            ('o', -1) => {
                ans[(i+1)%n] == ans[i-1]
            },
            ('x', -1) => {
                ans[(i+1)%n] != ans[i-1]
            },
            ('o', 1) => {
                ans[(i+1)%n] != ans[i-1]
            },
            _ => {
                ans[(i+1)%n] == ans[i-1]
            }
        }) {return None;}
    }
    Some(ans)
}

