fn solve(src: &str) -> String {
    let mut sc = Scanner::from_str(src);
    let n: usize = sc.read();
    let s: Vec<_> = sc.get().chars().collect();

    'lp: for &(t0, t1) in [('S', 'S'), ('S', 'W'), ('W', 'S'), ('W', 'W')].iter() {
        let mut t = Vec::new();
        t.push(t0);
        t.push(t1);
        for i in 2..n+1 {
            if (s[i-1] == 'o') ^ (t[i-1] == 'W') {
                let nxt = t[i-2];
                t.push(nxt);
            } else if t[i-2] == 'S' {
                t.push('W');
            } else {
                t.push('S');
            }
        }
        if t[0] != t[n] {
            continue;
        }
        if ((s[0] == 'o') ^ (t[0] == 'W')) != (t[n-1] == t[1]) {
            continue 'lp;
        }
        for i in 0..n-1 {
            if ((s[i+1] == 'o') ^ (t[i+1] == 'W')) != (t[i] == t[i+2]) {
                continue 'lp;
            }
        }
        t.pop();
        return t.into_iter().collect();
    }

    format!("-1\n")
}
