fn valid(s: &str, pat: &str) -> Option<String> {
  let s = s.chars().collect::<Vec<_>>();
  let mut pat = pat.chars().collect::<Vec<_>>();

  let l = s.len();
  for i in 1 .. l + 1 {
    let prev = pat[(i-1)%l];
    match (s[i%l], pat[i%l]) {
      ('o', 'S') => pat.push(prev),
      ('o', 'W') => pat.push(if prev=='S' {'W'} else {'S'}),
      ('x', 'S') => pat.push(if prev=='S' {'W'} else {'S'}),
      ('x', 'W') => pat.push(prev),
      _ => unreachable!()
    }
  }

  if pat[0] == pat[l] && pat[1] == pat[l+1] {
    pat.pop();
    pat.pop();
    Some(pat.iter().map(|&c| c).collect::<String>())
  } else {
    None
  }
}

