fn exec() {
    let mut sc = Scanner::new();
    let n: usize = sc.ne();
    let s = sc.ne::<String>().into_bytes();
    let mut ans = vec![0; n];
    fn yes(a: &Vec<u8>) {
        for &x in a {
            print!("{}", x as char);
        }
        println!("");
        std::process::exit(0);
    }
    for k in 0..4 {
        ans[0] = match k & 1 {
            0 => b'S',
            _ => b'W',
        };
        ans[n - 1] = match k & 2 {
            0 => b'S',
            _ => b'W',
        };
        let mut ok = true;
        for i in 0..n {
            let l = (i + n - 1) % n;
            let r = (i + 1) % n;
            let same = match s[i] {
                b'o' => ans[i] == b'S',
                _ => ans[i] == b'W',
            };
            let rin = match same {
