fn fill(animals: &mut Vec<bool>, statement: &Vec<char>) {
    let n = animals.len();
    for ri in 2..n {
        let li = ri-2;
        let i = ri-1;
        animals[ri] = animals[i] ^ animals[li] ^ (statement[i] == 'o');
    }
}

fn is_valid(animals: &Vec<bool>, statement: &Vec<char>) -> bool {
    let n = animals.len();
    for i in 0..n {
        let li = (i+n-1)%n;
        let ri = (i+1)%n;
        if animals[i] ^ (animals[li] == animals[ri]) ^ (statement[i] == 'x') {
            return false;
        }
    }
    true
}

