fn check(left: usize, central: usize, right: usize, is_sheeps: &Vec<bool>, s: &Vec<char>) -> bool {
    let n = is_sheeps.len();
    if is_sheeps[central] && s[central] == 'o' {
        if !is_sheeps[left] || !is_sheeps[right] {
            return false;
        }
    } else if !is_sheeps[0] && s[0] == 'x' {
        if is_sheeps[left] || is_sheeps[right] {
            return false;
        }
    } else if is_sheeps[left] == is_sheeps[right] {
        return false;
    }
    true
}

fn main() {
    let n: usize = read();
    let s: String = read();
    let s = s.chars().collect::<Vec<_>>();

    for i in 0..4 {
        let mut is_sheeps = vec![false; n];

        if i == 0 {
            is_sheeps[0] = true;
            is_sheeps[1] = true;
        } else if i == 1 {
            is_sheeps[0] = true;
            is_sheeps[1] = false;
        } else if i == 2 {
            is_sheeps[0] = false;
            is_sheeps[1] = true;
        } else {
            is_sheeps[0] = false;
            is_sheeps[1] = false;
        }

        let mut succeeded = true;

        for i in 2..n {
            if s[i - 1] == 'o' && is_sheeps[i - 1] {
                if !is_sheeps[i - 2] {
                    succeeded = false;
                }
                is_sheeps[i] = true;
            } else if s[i - 1] == 'x' && !is_sheeps[i - 1] {
                if is_sheeps[i - 2] {
                    succeeded = false;
                }
                is_sheeps[i] = false;
            } else {
                is_sheeps[i] = !is_sheeps[i - 2];
            }
        }

        succeeded &= check(n - 2, n - 1, 0, &is_sheeps, &s);
        succeeded &= check(n - 1, 0, 1, &is_sheeps, &s);
        succeeded &= check(0, 1, 2, &is_sheeps, &s);

        if succeeded {
            println!(
                "{}",
                is_sheeps
                    .iter()
                    .map(|&x| if x { "S" } else { "W" })
                    .collect::<Vec<_>>()
                    .join("")
            );
            return;
        }
    }
    println!("-1");
}

