fn exec() {
    let mut sc = Scanner::new();
    let n: usize = sc.ne();
    let s = sc.ne::<String>().into_bytes();
    fn yes(a: &Vec<u8>) {
        for &x in a {
            print!("{}", x as char);
        }
        println!("");
        std::process::exit(0);
    }
    for k in 0..4 {
        let mut ans = vec![0; n];
        ans[0] = match k & 1 {
            0 => b'S',
            _ => b'W',
        };
        ans[n - 1] = match k & 2 {
            0 => b'S',
            _ => b'W',
        };
        let mut ok = true;
        for i in 0..n {
            let l = (i + n - 1) % n;
            let r = (i + 1) % n;
            let same = match s[i] {
                b'o' => ans[i] == b'S',
                _ => ans[i] == b'W',
            };
            let rin = match same {
                true => ans[l],
                _ => if ans[l] == b'S' { b'W' } else { b'S' },
            };
            if ans[r] == 0 {
                ans[r] = rin;
            } else {
                if ans[r] != rin {
                    ok = false;
                    break;
                }
            }
        }
        if ok {
            yes(&ans);
        };
    }
    println!("-1");
}
fn main() {
    const DEFAULT_STACK: usize = 16 * 1024 * 1024;
    let builder = thread::Builder::new();
    let th = builder.stack_size(DEFAULT_STACK);
    let handle = th.spawn(|| { exec(); }).unwrap();
    let _ = handle.join();
}

#[allow(dead_code)]
struct Scanner {
    stdin: Stdin,
    id: usize,
    buf: Vec<u8>,
}

#[allow(dead_code)]
impl Scanner {
    fn new() -> Scanner {
        Scanner {
            stdin: io::stdin(),
            id: 0,
            buf: Vec::new(),
        }
    }
    fn next_line(&mut self) -> Option<String> {
        let mut res = String::new();
        match self.stdin.read_line(&mut res) {
            Ok(0) => return None,
            Ok(_) => Some(res),
            Err(why) => panic!("error in read_line: {}", why.description()),
        }
    }
    fn next<T: FromStr>(&mut self) -> Option<T> {
        while self.buf.len() == 0 {
            self.buf = match self.next_line() {
                Some(r) => {
                    self.id = 0;
                    r.trim().as_bytes().to_owned()
                }
                None => return None,
            };
        }
        let l = self.id;
        assert!(self.buf[l] != b' ');
        let n = self.buf.len();
        let mut r = l;
        while r < n && self.buf[r] != b' ' {
            r += 1;
        }
        let res = match str::from_utf8(&self.buf[l..r]).ok().unwrap().parse::<T>() {
            Ok(s) => Some(s),
            Err(_) => {
                panic!("parse error, {:?}",
                       String::from_utf8(self.buf[l..r].to_owned()))
            }
        };
        while r < n && self.buf[r] == b' ' {
            r += 1;
        }
        if r == n {
            self.buf.clear();
        } else {
            self.id = r;
        }
        res
    }
    fn ne<T: FromStr>(&mut self) -> T {
        self.next::<T>().unwrap()
    }
}

