use std::io::{BufRead, Write, stdin, stdout};

fn solve<R: BufRead, W: Write>(mut input: R, mut output: W) {
    let mut s = String::new();
    input.read_line(&mut s).unwrap();
    s.clear();
    input.read_line(&mut s).unwrap();
    let answers: Vec<bool> = s.trim().chars().map(|x| x == 'o').collect();
    let mut result: Vec<bool> = Vec::with_capacity(answers.len());
    for init in &[[true, true], [true, false], [false, true], [false, false]] {
        result.extend(init);
        for i in 2..answers.len() {
            let buf = !(result[i - 2] ^ !(answers[i - 1] ^ result[i - 1]));
            result.push(buf);
        }
        if (result[answers.len() - 2] == result[0]) ==
           !(answers[answers.len() - 1] ^ result[answers.len() - 1]) &&
           (result[answers.len() - 1] == result[1]) == !(answers[0] ^ result[0]) {
            break;
        } else {
            result.clear();
        }
    }
    writeln!(output,
             "{}",
             if result.is_empty() {
                 "-1".to_owned()
             } else {
                 result.iter().map(|&x| if x { 'S' } else { 'W' }).collect::<String>()
             })
        .unwrap();
}

fn main() {
    let stdin = stdin();
    solve(stdin.lock(), stdout());
}

