use std::io::*;

fn putans(a: &Vec<usize>) {
    for &i in a.iter() {
        if i == 0 {
            print!("S");
        } else {
            print!("W");
        }
    }
}
fn check(s: &Vec<char>, a: &mut Vec<usize>, n: usize) -> bool {
    for i in 1..n - 1 {
        if s[i] == 'o' {
            if a[i] == 0 {
                a[i + 1] = a[i - 1];
            } else {
                a[i + 1] = a[i - 1] ^ 1;
            }
        } else {
            if a[i] == 0 {
                a[i + 1] = a[i - 1] ^ 1;
            } else {
                a[i + 1] = a[i - 1];
            }
        }
    }
    let last;
    let first;
    if s[n - 1] == 'o' {
        if a[n - 1] == 0 {
            last = a[n - 2];
        } else {
            last = a[n - 2] ^ 1;
        }
    } else {
        if a[n - 1] == 0 {
            last = a[n - 2] ^ 1;
        } else {
            last = a[n - 2];
        }
    }
    if s[0] == 'o' {
        first = a[1];
    } else {
        first = a[1] ^ 1;
    }
    first == a[n - 1] && last == a[0]
}

