use std::str::FromStr;

trait Readable {
    fn read_item(s: &str) -> Self;
    fn read_line(s: String) -> Self where Self: std::marker::Sized {
        Self::read_item(&s)
    }
}

impl Readable for usize {
    fn read_item(s: &str) -> usize { usize::from_str(s).unwrap() }
}

impl Readable for u64 {
    fn read_item(s: &str) -> u64 { u64::from_str(s).unwrap() }
}

impl Readable for String {
    fn read_item(s: &str) -> String { s.to_string() }
    fn read_line(s: String) -> String { s }
}

impl<T1, T2> Readable for (T1, T2) where T1: Readable, T2: Readable {
    fn read_item(s: &str) -> (T1, T2) {
        let items: Vec<&str> = s.split(' ').collect();
        assert!(items.len() == 2);
        (T1::read_item(items[0]), T2::read_item(items[1]))
    }
}

fn read<T>() -> T where T: Readable {
    let mut line = String::new();
    std::io::stdin().read_line(&mut line).unwrap();

    let last = line.pop();
    match last {
        Some(ch) if ch != '\n' => line.push(ch),
        _ => ()
    }

    T::read_line(line)
}

fn verify(animals: &[u8], parities: &[u8]) -> bool {
    let last = animals.len() - 1;
    (parities[0] + animals[last] + animals[0] + animals[1]) % 2 == 0 &&
        (parities[last] + animals[last-1] + animals[last] + animals[0]) % 2 == 0
}

fn main() {
    let n: usize = read();
    let line: String = read();
    let parities: Vec<u8> = line.chars().map(|ch| {
        if ch == 'o' { 0 } else { 1 }
    }).collect();

    let mut animalss = [vec![0,0], vec![0,1], vec![1,0], vec![1,1]];
    for animals in animalss.iter_mut() {
        for i in 1..n-1 {
            let p = (animals[i-1] + animals[i] + parities[i]) % 2;
            animals.push(p);
        }
        if verify(&animals, &parities) {
            let ans: String = animals.iter()
                .map(|&p| if p == 0 { 'S' } else { 'W' })
                .into_iter().collect();
            println!("{}", ans);
            std::process::exit(0);
        }
    }

    println!("-1");
}

#[allow(unused_macros)]
macro_rules! input {
    (source = $s:expr, $($r:tt)*) => {
        let mut iter = $s.split_whitespace();
        let mut next = || { iter.next().unwrap() };
        input_inner!{next, $($r)*}
    };
    ($($r:tt)*) => {
        let stdin = std::io::stdin();
        let mut bytes = std::io::Read::bytes(std::io::BufReader::new(stdin.lock()));
        let mut next = move || -> String{
            bytes
                .by_ref()
                .map(|r|r.unwrap() as char)
                .skip_while(|c|c.is_whitespace())
                .take_while(|c|!c.is_whitespace())
                .collect()
        };
        input_inner!{next, $($r)*}
    };
}

#[allow(unused_macros)]
macro_rules! input_inner {
    ($next:expr) => {};
    ($next:expr, ) => {};

    ($next:expr, $var:ident : $t:tt $($r:tt)*) => {
        let $var = read_value!($next, $t);
        input_inner!{$next $($r)*}
    };
}

#[allow(unused_macros)]
macro_rules! read_value {
    ($next:expr, ( $($t:tt),* )) => {
        ( $(read_value!($next, $t)),* )
    };

    ($next:expr, [ $t:tt ; $len:expr ]) => {
        (0..$len).map(|_| read_value!($next, $t)).collect::<Vec<_>>()
    };

    ($next:expr, chars) => {
        read_value!($next, String).chars().collect::<Vec<char>>()
    };

    ($next:expr, bytes) => {
        read_value!($next, String).into_bytes()
    };

    ($next:expr, usize1) => {
        read_value!($next, usize) - 1
    };

    ($next:expr, $t:ty) => {
        $next().parse::<$t>().expect("Parse error")
    };
}

use std::cmp::Ordering;

/// Equivalent to std::lowerbound and std::upperbound in c++
pub trait BinarySearch<T> {
    fn lower_bound(&self, &T) -> usize;
    fn upper_bound(&self, &T) -> usize;
}

impl<T: Ord> BinarySearch<T> for [T] {
    fn lower_bound(&self, x: &T) -> usize {
        let mut low = 0;
        let mut high = self.len();

        while low != high {
            let mid = (low + high) / 2;
            match self[mid].cmp(x) {
                Ordering::Less => {
                    low = mid + 1;
                }
                Ordering::Equal | Ordering::Greater => {
                    high = mid;
                }
            }
        }
        low
    }

    fn upper_bound(&self, x: &T) -> usize {
        let mut low = 0;
        let mut high = self.len();

        while low != high {
            let mid = (low + high) / 2;
            match self[mid].cmp(x) {
                Ordering::Less | Ordering::Equal => {
                    low = mid + 1;
                }
                Ordering::Greater => {
                    high = mid;
                }
            }
        }
        low
    }
}






