fn solve(src: &str) -> String {
    let mut sc = Scanner::from_str(src);
    let n: usize = sc.read();
    let s: Vec<_> = sc.get().chars().collect();

    for &(a0, a1) in [('S', 'S'), ('S', 'W'), ('W', 'S'), ('W', 'W')].iter() {
        let mut a = Vec::with_capacity(n+1);
        a.push(a0);
        a.push(a1);
        for i in 2..n+1 {
            let lie = a[i-1] == 'W';
            if (s[i-1] == 'o') ^ lie {
                a.push(a[i-2]);
            } else if a[i-2] == 'S' {
                a.push('W');
            } else {
                a.push('S');
            }
        }
        if a[0] == a[n] {
            a.pop();
            return a.iter().collect();
        }
    }

    format!("-1\n")
