    for i in 1..n - 1 {
        if s[i] == 'o' {
            if a[i] == 0 {
                a[i + 1] = a[i - 1];
            } else {
                a[i + 1] = a[i - 1] ^ 1;
            }
        } else {
            if a[i] == 0 {
                a[i + 1] = a[i - 1] ^ 1;
            } else {
                a[i + 1] = a[i - 1];
            }
        }
    }
    let last;
    if s[n - 1] == 'o' {
        if a[n - 1] == 0 {
            last = a[n - 2];
        } else {
            last = a[n - 2] ^ 1;
        }
    } else {
        if a[n - 1] == 0 {
            last = a[n - 2] ^ 1;
        } else {
            last = a[n - 2];
        }
    }
    last == a[0]
}

