    std::io::stdin().read_line(&mut s).ok();
    s.trim().parse().ok().unwrap()
}

fn check(left: usize, central: usize, right: usize, is_sheeps: &Vec<bool>, s: &Vec<char>) -> bool {
    let n = is_sheeps.len();
    if is_sheeps[central] && s[central] == 'o' {
        if !is_sheeps[left] || !is_sheeps[right] {
            return false;
        }
    } else if !is_sheeps[central] && s[central] == 'x' {
        if is_sheeps[left] || is_sheeps[right] {
            return false;
        }
    } else if is_sheeps[left] == is_sheeps[right] {
        return false;
    }
    true
}

fn main() {
    let n: usize = read();
    let s: String = read();
    let s = s.chars().collect::<Vec<_>>();

    let trials = [(true, true), (false, false), (false, true), (true, false)];
    for trial in trials.iter() {
        let mut is_sheeps = vec![false; n];
        is_sheeps[0] = trial.0;
        is_sheeps[1] = trial.1;

        for i in 2..n {
            if s[i - 1] == 'o' && is_sheeps[i - 1] {
                is_sheeps[i] = true;
            } else if s[i - 1] == 'x' && !is_sheeps[i - 1] {
                is_sheeps[i] = false;
            } else {
                is_sheeps[i] = !is_sheeps[i - 2];
            }
        }
        let mut succeeded = true;
        succeeded &= check(n - 2, n - 1, 0, &is_sheeps, &s);
        succeeded &= check(n - 1, 0, 1, &is_sheeps, &s);
        for i in 1..n - 1 {
            succeeded &= check(i - 1, i, i + 1, &is_sheeps, &s);
        }
        if succeeded {
            println!(
                "{}",
                is_sheeps
                    .iter()
                    .map(|&x| if x { "S" } else { "W" })
                    .collect::<Vec<_>>()
                    .join("")
            );
            return;
        }
    }
    println!("-1");
}

#[allow(unused_macros)]
macro_rules! input {
    (source = $s:expr, $($r:tt)*) => {
        let mut iter = $s.split_whitespace();
        let mut next = || { iter.next().unwrap() };
        input_inner!{next, $($r)*}
    };
    ($($r:tt)*) => {
        let stdin = std::io::stdin();
        let mut bytes = std::io::Read::bytes(std::io::BufReader::new(stdin.lock()));
        let mut next = move || -> String{
            bytes
                .by_ref()
                .map(|r|r.unwrap() as char)
                .skip_while(|c|c.is_whitespace())
                .take_while(|c|!c.is_whitespace())
                .collect()
        };
        input_inner!{next, $($r)*}
    };
}

#[allow(unused_macros)]
macro_rules! input_inner {
    ($next:expr) => {};
    ($next:expr, ) => {};

    ($next:expr, $var:ident : $t:tt $($r:tt)*) => {
        let $var = read_value!($next, $t);
        input_inner!{$next $($r)*}
    };

    ($next:expr, mut $var:ident : $t:tt $($r:tt)*) => {
        let mut $var = read_value!($next, $t);
        input_inner!{$next $($r)*}
    };
}

#[allow(unused_macros)]
macro_rules! read_value {
    ($next:expr, ( $($t:tt),* )) => {
        ( $(read_value!($next, $t)),* )
    };

    ($next:expr, [ $t:tt ; $len:expr ]) => {
        (0..$len).map(|_| read_value!($next, $t)).collect::<Vec<_>>()
    };

    ($next:expr, chars) => {
        read_value!($next, String).chars().collect::<Vec<char>>()
    };

    ($next:expr, usize1) => {
        read_value!($next, usize) - 1
    };

    ($next:expr, $t:ty) => {
        $next().parse::<$t>().expect("Parse error")
    };
}

