use std::io::{stdout, stdin, BufWriter, Write};

fn main() {
    let out = std::io::stdout();
    let mut out = BufWriter::new(out.lock());
    macro_rules! puts {
        ($($format:tt)*) => (writeln!(out,$($format)*).unwrap());
    }

    input!{
      n: usize,
      s: chars,
    }

    let table = vec![
        ('S', 'S'),
        ('S', 'W'),
        ('W', 'S'),
        ('W', 'W'),
    ];

    let inv = |c| if c == 'W' { 'S' } else { 'W' };

    for (a1, a2) in table {
        let mut ans = vec![];
        ans.push(a1);
        ans.push(a2);
        for i in 2..n {
            if s[i-1] == 'o' {
                let tmp = ans[i-2];
                if ans[i-1] == 'S' {
                    ans.push(tmp);
                } else {
                    ans.push(inv(tmp));
                }
            } else if s[i-1] == 'x' {
                let tmp = ans[i-2];
                if ans[i-1] == 'S' {
                    ans.push(inv(tmp));
                } else {
                    ans.push(tmp);
                }
            } else {
                // debug!(a1, a2, s[i-1]);
                unreachable!();
            }
        }

        let ok = match (s[n-1], ans[n-1]) {
            ('o', 'S') => {
                ans[n-2] == ans[0]
            },
            ('o', 'W') => {
                ans[n-2] != ans[0]
            },
            ('x', 'S') =>{
                ans[n-2] != ans[0]
            },
            ('x', 'W') => {
                ans[n-2] == ans[0]
            },
            _ => unreachable!(),
        };

        if ok {
            let ans = ans.into_iter().collect::<String>();
            return puts!("{}", ans);
        }
    }
    puts!("{}", -1);
}

