fn main() {
    input!{
        n: usize,
        s: chars
    }
    let mut vs = vec![vec!['S','S'],vec!['S','W'],vec!['W','S'],vec!['W','W']];
    for v in vs.iter_mut() {
        if !order(v, &s) {
            continue;
        }
        for c in v {
            print!("{}", c);
        }
        print!("\n");
        return;
    }
    println!("-1");
}

fn order(v: &mut Vec<char>, o: &Vec<char>) -> bool {
    let l = o.len();
    for i in 1..l {
        if (v[i-1] == 'S') ^ (v[i] == 'S') ^ (o[i] == 'o') {
            v.push('S');
        } else {
            v.push('W');
        }
    }
    let last = v.pop().unwrap();
    last == v[0] && (v[1] == last) ^ (v[0] == 'S') ^ (o[0] == 'o')
}

