mod reader {
    use std::fmt::Debug;
    use std::str::FromStr;
    use std::collections::VecDeque;
    use std::io::{self, Read};

    fn _read_line() -> String {
        let mut buf = String::new();
        let _ = io::stdin().read_to_string(&mut buf);
        buf
    }

    fn _read_vec_deque_string() -> VecDeque<String> {
        _read_line()
            .split_whitespace()
            .map(|s| s.to_string())
            .collect()
    }

    #[allow(dead_code)]
    pub struct Reader {
        buf: VecDeque<String>,
    }

    #[allow(dead_code)]
    impl Reader {
        pub fn new() -> Reader {
            Reader { buf: VecDeque::new() }
        }

        fn update_buf(&mut self) {
            if self.buf.is_empty() {
                self.buf = _read_vec_deque_string();
            }
        }

        pub fn next<T>(&mut self) -> T
            where
                T: FromStr,
                T::Err: Debug,
        {
            self.update_buf();
            self.buf.pop_front().unwrap().parse::<T>().unwrap()
        }

        pub fn next_n<T>(&mut self, n: usize) -> Vec<T>
            where
                T: FromStr,
                T::Err: Debug,
        {
            let mut vec: Vec<T> = Vec::with_capacity(n);

            for _ in 0..n {
                vec.push(self.next());
            }
            vec
        }
    }
}

use std::io::{BufRead, Write, stdin, stdout};

fn solve<R: BufRead, W: Write>(mut input: R, mut output: W) {
    let mut s = String::new();
    input.read_line(&mut s).unwrap();
    s.clear();
    input.read_line(&mut s).unwrap();
    let answers: Vec<bool> = s.trim().chars().map(|x| x == 'o').collect();
    let mut result: Vec<bool> = Vec::with_capacity(answers.len());
    for init in &[[true, true], [true, false], [false, true], [false, false]] {
        result.extend(init);
        for i in 2..answers.len() {
            let buf = !(result[i - 2] ^ !(answers[i - 1] ^ result[i - 1]));
            result.push(buf);
        }
        if (result[answers.len() - 2] == result[0]) ==
           !(answers[answers.len() - 1] ^ result[answers.len() - 1]) {
            break;
        } else {
            println!("{:?}", result);
            result.clear();
        }
    }
    writeln!(output,
             "{}",
             if result.is_empty() {
                 "-1".to_owned()
             } else {
                 result.iter().map(|&x| if x { 'S' } else { 'W' }).collect::<String>()
             })
        .unwrap();
}

fn main() {
    let stdin = stdin();
    solve(stdin.lock(), stdout());
}

